    fn to_list(&self, py: Python<'_>) -> PyResult<Py<PyList>> {
        let items = self
            .inner
            .labels()
            .iter()
            .map(|l| index_label_to_py(py, l))
            .collect::<PyResult<Vec<_>>>()?;
        Ok(PyList::new(py, items)?.unbind())
    }

