    fn __reduce__<'py>(
        &self,
        py: Python<'py>,
    ) -> PyResult<(Bound<'py, PyAny>, Bound<'py, PyTuple>)> {
        let constructor = py.get_type::<PyIndex>().into_any();
        let idx_labels: Vec<Py<PyAny>> = self
            .inner
            .labels()
            .iter()
            .map(|lbl| index_label_to_py(py, lbl))
            .collect::<PyResult<Vec<_>>>()?;
        let idx_list = PyList::new(py, &idx_labels)?;
        let name = self.inner.name().into_bound_py_any(py)?;
        // Index(data, dtype, copy, name), as pandas' constructor reads its
        // positional arguments.
        let args = PyTuple::new(
            py,
            [
                idx_list.as_any(),
                &py.None().into_bound(py),
                &false.into_bound_py_any(py)?,
                &name,
            ],
        )?;
        Ok((constructor, args))
    }

    fn __getitem__(&self, py: Python<'_>, key: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        if let Ok(idx) = key.extract::<i64>() {
            let pos = if idx < 0 {
                (self.inner.len() as i64 + idx) as usize
            } else {
                idx as usize
            };
            if pos >= self.inner.len() {
                return Err(PyErr::new::<pyo3::exceptions::PyIndexError, _>(
                    "index out of bounds",
                ));
            }
            return index_label_to_py(py, &self.inner.labels()[pos]);
        }
        if let Ok(slice) = key.cast::<pyo3::types::PySlice>() {
            let s_idx = slice.indices(self.inner.len() as isize)?;
            let mut sliced = Vec::new();
            let mut i = s_idx.start;
            if s_idx.step > 0 {
                while i < s_idx.stop {
                    sliced.push(self.inner.labels()[i as usize].clone());
                    i += s_idx.step;
                }
            } else if s_idx.step < 0 {
                while i > s_idx.stop {
                    sliced.push(self.inner.labels()[i as usize].clone());
                    i += s_idx.step;
                }
            }
            let mut out = Index::new(sliced);
            if let Some(n) = self.inner.name() {
                out = out.set_name(n);
            }
            return Ok(Py::new(py, PyIndex { inner: out })?.into_any());
        }
        // A list or array of positions, or a boolean mask, takes those
        // labels (pandas' `index[[0, 2]]`, `index[index > 1]`); it raised
        // TypeError.
        if !key.is_instance_of::<pyo3::types::PyString>() && key.hasattr("__len__")? {
            let positions = resolve_iloc_positions(self.inner.len(), key).map_err(|err| {
                if err.is_instance_of::<pyo3::exceptions::PyTypeError>(py) {
                    PyErr::new::<pyo3::exceptions::PyIndexError, _>(
                        "only integers, slices (`:`), ellipsis (`...`), numpy.newaxis (`None`) \
                         and integer or boolean arrays are valid indices",
                    )
                } else {
                    err
                }
            })?;
            let taken = self.inner.take(&positions).set_names(self.inner.name());
            return Ok(Py::new(py, PyIndex { inner: taken })?.into_any());
        }
        Err(PyErr::new::<pyo3::exceptions::PyIndexError, _>(
            "only integers, slices (`:`), ellipsis (`...`), numpy.newaxis (`None`) and integer \
             or boolean arrays are valid indices",
        ))
    }

