    fn __reversed__<'py>(&self, py: Python<'py>) -> PyResult<Bound<'py, PyAny>> {
        let labels = self
            .inner
            .labels()
            .iter()
            .rev()
            .map(|label| index_label_to_py(py, label))
            .collect::<PyResult<Vec<_>>>()?;
        PyList::new(py, labels)?.call_method0("__iter__")
    }

