    /// pandas' `DatetimeIndex.astype`; astype(str) prints each instant as
    /// `Series.astype(str)` does - the date alone when every instant is at
    /// midnight (it always printed the time).
    fn astype(&self, dtype: &Bound<'_, PyAny>) -> PyResult<PyIndex> {
        let name = index_astype_name(dtype)?;
        let index = self.as_py_index();
        if name != "str" {
            return index.astype_name(&name);
        }
        // A tz-aware index prints each instant as its Timestamp in the zone
        // ('2024-03-09 18:00:00-05:00'); it printed the UTC clock.
        if let Some(zone) = self.inner.tz() {
            let instants: Vec<Option<i64>> = self
                .inner
                .asi8()
                .into_iter()
                .map(|nanos| (nanos != Timestamp::NAT).then_some(nanos))
                .collect();
            let labels = pandas_aware_datetime_texts(&instants, &zone)
                .into_iter()
                .map(IndexLabel::Utf8)
                .collect();
            return Ok(PyIndex {
                inner: Index::new(labels).set_names(index.inner.name()),
            });
        }
        let values: Vec<Scalar> = index
            .inner
            .labels()
            .iter()
            .map(index_label_to_scalar)
            .collect();
        let positions = (0..values.len())
            .map(|position| IndexLabel::Int64(i64::try_from(position).unwrap_or(i64::MAX)))
            .collect();
        let text = Series::from_values("", positions, values)
            .and_then(|series| series.astype(DType::Utf8))
            .map_err(frame_error_to_py)?;
        let labels = text
            .values()
            .iter()
            .map(scalar_to_index_label_converter)
            .collect();
        Ok(PyIndex {
            inner: Index::new(labels).set_names(index.inner.name()),
        })
    }

    fn date(&self, py: Python<'_>) -> PyResult<Py<PyList>> {
        let dt_mod = py.import("datetime")?;
        let date_cls = dt_mod.getattr("date")?;
        let mut out = Vec::with_capacity(self.inner.len());
        let years = self.inner.year();
        let months = self.inner.month();
        let days = self.inner.day();
        for i in 0..self.inner.len() {
            if let (Some(y), Some(m), Some(d)) = (years[i], months[i], days[i]) {
                let py_d = date_cls.call1((y, m, d))?;
                out.push(py_d.into_any().unbind());
            } else {
                out.push(py.None());
            }
        }
        Ok(PyList::new(py, out)?.unbind())
    }

