    #[getter]
    fn is_full(&self) -> bool {
        let vals = self.inner.values();
        if vals.len() <= 1 {
            return true;
        }
        for i in 1..vals.len() {
            if vals[i].ordinal != vals[i - 1].ordinal + 1 {
                return false;
            }
        }
        true
    }

