    /// Return the first n elements. pandas slices `iloc[:n]`, so `n=None`
    /// keeps every element.
    #[pyo3(signature = (n=Some(5)))]
    fn head(&self, n: Option<i64>) -> PyResult<PySeries> {
        let n = n.unwrap_or(i64::MAX);
        let result = self
            .inner
            .head(n)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        Ok(PySeries { inner: result })
    }

    /// Return the last n elements.
    #[pyo3(signature = (n=5))]
    fn tail(&self, n: i64) -> PyResult<PySeries> {
        let result = self
            .inner
            .tail(n)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        Ok(PySeries { inner: result })
    }

    /// Return values as a Python list.
    fn tolist(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        let column = self.inner.column();
        let values: Vec<Py<PyAny>> = column
            .values()
            .iter()
            .map(|s| cell_to_py(py, column, s))
            .collect::<PyResult<Vec<Py<PyAny>>>>()?;
        Ok(PyList::new(py, values)?.into_any().unbind())
    }

    /// `for v in s` yields each value as [`iterated_to_py`]; iteration fell
    /// back to `s[i]`, whose elements are numpy scalars.
    fn __iter__(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        let column = self.inner.column();
        let values = column
            .values()
            .iter()
            .map(|value| iterated_to_py(py, column, value))
            .collect::<PyResult<Vec<_>>>()?;
        Ok(PyList::new(py, values)?.try_iter()?.into_any().unbind())
    }

