    /// Compute numerical data ranks (pandas `Series.rank`).
    #[pyo3(signature = (axis=None, method=None, numeric_only=false, na_option=None, ascending=None, pct=false))]
    fn rank(
        &self,
        axis: Option<&Bound<'_, PyAny>>,
        method: Option<&str>,
        numeric_only: bool,
        na_option: Option<&str>,
        ascending: Option<bool>,
        pct: bool,
    ) -> PyResult<PySeries> {
        let mut m = method.unwrap_or("average");
        if let Some(a) = axis {
            if let Ok(s) = a.extract::<&str>() {
                if matches!(s, "average" | "min" | "max" | "first" | "dense") && method.is_none() {
                    m = s;
                } else {
                    let parsed = parse_axis_param_for_type(Some(a), "Series")?.unwrap_or(0);
                    if parsed != 0 {
                        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                            "No axis named {parsed} for object type Series"
                        )));
                    }
                }
            } else {
                let parsed = parse_axis_param_for_type(Some(a), "Series")?.unwrap_or(0);
                if parsed != 0 {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                        "No axis named {parsed} for object type Series"
                    )));
                }
            }
        }
        if numeric_only
            && !matches!(
                self.inner.dtype(),
                DType::Int64 | DType::Float64 | DType::Bool
            )
        {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "Series.rank does not allow numeric_only=True with non-numeric dtype.",
            ));
        }
        let asc = ascending.unwrap_or(true);
        let na = na_option.unwrap_or("keep");
        let r = self
            .inner
            .rank_with_pct(m, asc, na, pct)
            .map_err(frame_error_to_py)?;
        Ok(PySeries { inner: r })
    }

    /// Sort Series by index labels.
    ///
    /// Matches `s.sort_index(axis=0, level=None, ascending=True, inplace=False, kind='quicksort', na_position='last', sort_remaining=True, ignore_index=False, key=None)`.
    #[pyo3(signature = (
        axis = None,
        level = None,
        ascending = None,
        inplace = false,
        kind = None,
        na_position = "last",
        sort_remaining = true,
        ignore_index = false,
        key = None
    ))]
    #[allow(clippy::too_many_arguments)]
    fn sort_index(
        &mut self,
        py: Python<'_>,
        axis: Option<&Bound<'_, PyAny>>,
        level: Option<&Bound<'_, PyAny>>,
        ascending: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        kind: Option<&str>,
        na_position: &str,
        sort_remaining: bool,
        ignore_index: bool,
        key: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Option<PySeries>> {
        // A Series index is single-level: level 0 is the default order, and
        // sort_remaining only acts on the other levels of a MultiIndex, so
        // pandas ignores it here too.
        let _ = sort_remaining;
        let level_is_default = level.is_none_or(|l| matches!(l.extract::<i64>(), Ok(0)));
        unsupported_params("Series.sort_index", &[("level", level_is_default)])?;
        validate_sort_kind(kind)?;
        let result = (|| -> PyResult<PySeries> {
            let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
            if ax != 0 {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "No axis named {ax} for object type Series"
                )));
            }
            let asc = parse_ascending_bool(ascending)?;
            let sorted = match key {
                Some(key) => {
                    let keyed = key.call1((PyIndex {
                        inner: self.inner.index().clone(),
                    },))?;
                    self.keyed_sort(py, &keyed, asc, na_position)?
                }
                None => self
                    .inner
                    .sort_index_na(asc, na_position)
                    .map_err(frame_error_to_py)?,
            };
            let out = if ignore_index {
                match sorted.reset_index(true).map_err(frame_error_to_py)? {
                    fp_frame::SeriesResetIndexResult::Series(s) => s,
                    fp_frame::SeriesResetIndexResult::DataFrame(_) => unreachable!(),
                }
            } else {
                sorted
            };
            Ok(PySeries { inner: out })
        })()?;
        Ok(series_inplace(&mut self.inner, result, inplace))
    }

    /// pandas' `s.rename(index=None, *, axis=None, copy=None, inplace=False,
    /// level=None, errors='ignore')`: a dict or a callable relabels the index,
    /// anything else (None included) becomes the name (br-frankenpandas-n57tz:
    /// only a str name was taken). As in pandas, a new name with inplace=True
    /// still returns the Series; a relabel with inplace=True returns None.
    #[pyo3(signature = (
        index=None,
        axis=None,
        copy=None,
        inplace=false,
        level=None,
        errors="ignore"
    ))]
    #[allow(clippy::too_many_arguments)]
    fn rename(
        &mut self,
        py: Python<'_>,
        index: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        copy: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        level: Option<&Bound<'_, PyAny>>,
        errors: &str,
    ) -> PyResult<Option<PySeries>> {
        let _ = copy;
        parse_axis_param_for_type(axis, "Series")?;
        unsupported_params(
            "Series.rename",
            &[("level", level.is_none_or(|l| l.is_none()))],
        )?;
        let relabel = index.filter(|i| i.is_instance_of::<PyDict>() || i.is_callable());
        if let Some(mapping) = relabel {
            let labels = self.inner.index().labels().to_vec();
            let pairs = rename_pairs(py, mapping, &labels, errors == "raise")?;
            let map: HashMap<&IndexLabel, &IndexLabel> =
                pairs.iter().map(|(old, new)| (old, new)).collect();
            let relabeled: Vec<IndexLabel> = labels
                .iter()
                .map(|label| {
                    map.get(label)
                        .map_or_else(|| label.clone(), |new| (*new).clone())
                })
                .collect();
            let index = Index::new(relabeled).rename_index(self.inner.index().name());
            let out = Series::new(self.inner.name(), index, self.inner.column().clone())
                .map_err(frame_error_to_py)?;
            if inplace {
                self.inner = out;
                return Ok(None);
            }
            return Ok(Some(PySeries { inner: out }));
        }
        let name = match passed(index) {
            None => String::new(),
            Some(name) => py_to_index_label(&name)?.to_string(),
        };
        let out = self.inner.rename(&name).map_err(frame_error_to_py)?;
        if inplace {
            self.inner = out.clone();
        }
        Ok(Some(PySeries { inner: out }))
    }

    /// Return a boolean Series marking missing values (pandas `Series.isna`).
    fn isna(&self) -> PyResult<PySeries> {
        let r = self
            .inner
            .isna()
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        Ok(PySeries { inner: r })
    }

    /// Return a boolean Series marking non-missing values (pandas `Series.notna`).
    fn notna(&self) -> PyResult<PySeries> {
        let r = self
            .inner
            .notna()
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        Ok(PySeries { inner: r })
    }

    /// Clip values to the `[lower, upper]` range (either bound optional).
    #[pyo3(signature = (lower=None, upper=None, axis=None, inplace=false, **kwargs))]
    fn clip(
        &mut self,
        py: Python<'_>,
        lower: Option<&Bound<'_, PyAny>>,
        upper: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Option<PySeries>> {
        numpy_compat_kwargs("clip", kwargs)?;
        let result = (|| -> PyResult<PySeries> {
            let ax_opt = parse_axis_param_for_type(axis, "Series")?;
            if let Some(ax) = ax_opt {
                if ax != 0 {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                        "No axis named {ax} for object type Series"
                    )));
                }
            }

            // A datetime/timedelta column clips to Timestamp/Timedelta bounds (or
            // strings naming them) on its nanoseconds (fvsao.17).
            let dtype = self.inner.dtype();
            if matches!(dtype, DType::Datetime64 { .. } | DType::Timedelta64) {
                let nanos = |bound: Option<&Bound<'_, PyAny>>| -> PyResult<Option<i64>> {
                    let Some(bound) = bound.filter(|bound| !bound.is_none()) else {
                        return Ok(None);
                    };
                    match comparison_scalar(py, bound, &dtype)? {
                        Some(Scalar::Datetime64(ns) | Scalar::Timedelta64(ns)) => Ok(Some(ns)),
                        _ => Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                            "clip bound must be a {} scalar",
                            pandas_dtype_name(&dtype)
                        ))),
                    }
                };
                let clipped = self
                    .inner
                    .clip_nanos(nanos(lower)?, nanos(upper)?)
                    .map_err(frame_error_to_py)?
                    .expect("temporal dtype checked above");
                return Ok(PySeries { inner: clipped });
            }

            let extract_bound = |b: &Bound<'_, PyAny>| -> PyResult<SeriesOrScalarBound> {
                if let Ok(py_s) = b.extract::<PyRef<'_, PySeries>>() {
                    Ok(SeriesOrScalarBound::Series(Box::new(py_s.inner.clone())))
                } else if let Ok(f) = b.extract::<f64>() {
                    Ok(SeriesOrScalarBound::Scalar(f))
                } else if b.is_none() {
                    Ok(SeriesOrScalarBound::Scalar(f64::NAN))
                } else {
                    Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                        "bound must be a number or Series",
                    ))
                }
            };

            let lo = match lower {
                Some(b) if !b.is_none() => Some(extract_bound(b)?),
                _ => None,
            };
            let hi = match upper {
                Some(b) if !b.is_none() => Some(extract_bound(b)?),
                _ => None,
            };

            let has_series_bound = matches!(lo, Some(SeriesOrScalarBound::Series(_)))
                || matches!(hi, Some(SeriesOrScalarBound::Series(_)));

            if has_series_bound {
                let to_bound_series =
                    |bound: Option<SeriesOrScalarBound>| -> PyResult<Option<Series>> {
                        match bound {
                            None => Ok(None),
                            Some(SeriesOrScalarBound::Series(s)) => Ok(Some(*s)),
                            Some(SeriesOrScalarBound::Scalar(v)) => {
                                let labels = self.inner.index().labels().to_vec();
                                let vals = vec![Scalar::Float64(v); labels.len()];
                                let s = Series::from_values("bounds", labels, vals)
                                    .map_err(frame_error_to_py)?;
                                Ok(Some(s))
                            }
                        }
                    };
                let lo_s = to_bound_series(lo)?;
                let hi_s = to_bound_series(hi)?;
                let r = self
                    .inner
                    .clip_with_series(lo_s.as_ref(), hi_s.as_ref())
                    .map_err(frame_error_to_py)?;
                Ok(PySeries { inner: r })
            } else {
                let lo_f64 = match lo {
                    Some(SeriesOrScalarBound::Scalar(v)) => Some(v),
                    _ => None,
                };
                let hi_f64 = match hi {
                    Some(SeriesOrScalarBound::Scalar(v)) => Some(v),
                    _ => None,
                };
                let r = self.inner.clip(lo_f64, hi_f64).map_err(frame_error_to_py)?;
                Ok(PySeries { inner: r })
            }
        })()?;
        Ok(series_inplace(&mut self.inner, result, inplace))
    }

    /// Replace values dynamically or via an `{old: new}` mapping (pandas `Series.replace`).
    #[pyo3(signature = (to_replace=None, value=None, inplace=false, limit=None, regex=None, method=None))]
    #[allow(clippy::too_many_arguments)]
    fn replace(
        &mut self,
        py: Python<'_>,
        to_replace: Option<&Bound<'_, PyAny>>,
        value: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        limit: Option<usize>,
        regex: Option<&Bound<'_, PyAny>>,
        method: Option<&str>,
    ) -> PyResult<Option<PySeries>> {
        let result = (|| -> PyResult<PySeries> {
            let mut is_regex = false;
            let mut effective_to_replace = to_replace;

            if let Some(reg) = regex {
                if let Ok(b) = reg.extract::<bool>() {
                    is_regex = b;
                } else if reg.extract::<String>().is_ok() || reg.cast::<PyDict>().is_ok() {
                    is_regex = true;
                    if effective_to_replace.is_none() {
                        effective_to_replace = Some(reg);
                    }
                }
            }

            // pandas 2.2 (deprecated there, still its behaviour, fvsao.5): with no
            // `to_replace` the targets are the missing values, and with no
            // `value` each target is padded from its neighbour (`method`, default
            // pad). This returned the Series unchanged.
            let value_given = value.is_some_and(|v| !v.is_none());
            let Some(to_repl) = effective_to_replace.filter(|t| !t.is_none()) else {
                if is_regex {
                    return Ok(PySeries {
                        inner: self.inner.clone(),
                    });
                }
                if value_given {
                    return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                        "'regex' must be a string or a compiled regular expression or a list or dict of strings or regular expressions, you passed a 'bool'",
                    ));
                }
                let filled = match method.unwrap_or("pad") {
                "pad" | "ffill" => self.inner.ffill(limit),
                "backfill" | "bfill" => self.inner.bfill(limit),
                other => {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                        "Invalid fill method. Expecting pad (ffill) or backfill (bfill). Got {other}"
                    )));
                }
            }
            .map_err(frame_error_to_py)?;
                return Ok(PySeries { inner: filled });
            };
            let dict_like =
                to_repl.cast::<PyDict>().is_ok() || to_repl.extract::<PyRef<PySeries>>().is_ok();
            let method = if !value_given && !is_regex && !dict_like {
                method.or(Some("pad"))
            } else {
                method
            };

            if let Some(m) = method {
                let is_ffill = match m {
                    "pad" | "ffill" => true,
                    "backfill" | "bfill" => false,
                    other => {
                        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                            "Invalid fill method. Expecting pad (ffill) or backfill (bfill). Got {other}"
                        )));
                    }
                };
                let targets = if is_py_collection(to_repl) {
                    py_sequence_to_scalars(py, to_repl)?
                } else {
                    vec![py_to_scalar(py, to_repl)?]
                };
                let res = series_replace_with_method(&self.inner, &targets, is_ffill, limit)
                    .map_err(frame_error_to_py)?;
                return Ok(PySeries { inner: res });
            }

            if is_regex {
                if let Ok(dict) = to_repl.cast::<PyDict>() {
                    let mut current = self.inner.clone();
                    for (pat_obj, repl_obj) in dict.iter() {
                        let pat: String = pat_obj.extract()?;
                        let repl: String = if let Ok(s) = repl_obj.extract::<&str>() {
                            python_repl_to_rust_regex_repl(s)
                        } else {
                            let sc = py_to_scalar(py, &repl_obj)?;
                            match sc {
                                Scalar::Utf8(s) => python_repl_to_rust_regex_repl(&s),
                                Scalar::Int64(i) => i.to_string(),
                                Scalar::Float64(f) => f.to_string(),
                                Scalar::Bool(b) => b.to_string(),
                                _ => repl_obj.to_string(),
                            }
                        };
                        current = current
                            .replace_regex(&pat, &repl)
                            .map_err(frame_error_to_py)?;
                    }
                    return Ok(PySeries { inner: current });
                } else if let Ok(pat) = to_repl.extract::<String>() {
                    let repl = if let Some(val_obj) = value {
                        if let Ok(s) = val_obj.extract::<&str>() {
                            python_repl_to_rust_regex_repl(s)
                        } else {
                            let sc = py_to_scalar(py, val_obj)?;
                            match sc {
                                Scalar::Utf8(s) => python_repl_to_rust_regex_repl(&s),
                                Scalar::Int64(i) => i.to_string(),
                                Scalar::Float64(f) => f.to_string(),
                                Scalar::Bool(b) => b.to_string(),
                                _ => val_obj.to_string(),
                            }
                        }
                    } else {
                        String::new()
                    };
                    let res = self
                        .inner
                        .replace_regex(&pat, &repl)
                        .map_err(frame_error_to_py)?;
                    return Ok(PySeries { inner: res });
                } else if is_py_collection(to_repl) {
                    let mut pat_list = Vec::new();
                    for item in to_repl.try_iter()? {
                        pat_list.push(item?.extract::<String>()?);
                    }
                    let mut current = self.inner.clone();
                    if let Some(val_obj) = value {
                        if is_py_collection(val_obj) {
                            let mut repl_list = Vec::new();
                            for item in val_obj.try_iter()? {
                                repl_list.push(item?.extract::<String>()?);
                            }
                            if pat_list.len() != repl_list.len() {
                                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                                    format!(
                                        "Replacement lists must match in length. Expecting {} got {}",
                                        pat_list.len(),
                                        repl_list.len()
                                    ),
                                ));
                            }
                            for (pat, repl) in pat_list.iter().zip(repl_list.iter()) {
                                let repl_conv = python_repl_to_rust_regex_repl(repl);
                                current = current
                                    .replace_regex(pat, &repl_conv)
                                    .map_err(frame_error_to_py)?;
                            }
                        } else {
                            let repl_str = val_obj.extract::<String>()?;
                            let repl_conv = python_repl_to_rust_regex_repl(&repl_str);
                            for pat in &pat_list {
                                current = current
                                    .replace_regex(pat, &repl_conv)
                                    .map_err(frame_error_to_py)?;
                            }
                        }
                    }
                    return Ok(PySeries { inner: current });
                }
            }

            // Literal replacement (regex=false)
            if let Ok(dict) = to_repl.cast::<PyDict>() {
                let pairs = py_dict_to_scalar_pairs(py, dict)?;
                let r = self.inner.replace(&pairs).map_err(frame_error_to_py)?;
                return Ok(PySeries { inner: r });
            }

            if let Ok(py_s) = to_repl.extract::<PyRef<PySeries>>() {
                let s = &py_s.inner;
                let idx_labels = s.index().labels();
                let col_vals = s.column().values();
                let pairs: Vec<(Scalar, Scalar)> = idx_labels
                    .iter()
                    .zip(col_vals.iter())
                    .map(|(label, val)| (index_label_to_scalar(label), val.clone()))
                    .collect();
                let r = self.inner.replace(&pairs).map_err(frame_error_to_py)?;
                return Ok(PySeries { inner: r });
            }

            if is_py_collection(to_repl) {
                let from_scalars = py_sequence_to_scalars(py, to_repl)?;
                let pairs: Vec<(Scalar, Scalar)> = if let Some(val_obj) = value {
                    if is_py_collection(val_obj) {
                        let to_scalars = py_sequence_to_scalars(py, val_obj)?;
                        if from_scalars.len() != to_scalars.len() {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                                "Replacement lists must match in length. Expecting {} got {}",
                                from_scalars.len(),
                                to_scalars.len()
                            )));
                        }
                        from_scalars.into_iter().zip(to_scalars).collect()
                    } else {
                        let to_s = py_to_scalar(py, val_obj)?;
                        from_scalars
                            .into_iter()
                            .map(|s| (s, to_s.clone()))
                            .collect()
                    }
                } else {
                    return Ok(PySeries {
                        inner: self.inner.clone(),
                    });
                };
                let r = self.inner.replace(&pairs).map_err(frame_error_to_py)?;
                return Ok(PySeries { inner: r });
            }

            // Single scalar
            if let Some(val_obj) = value {
                let from_s = py_to_scalar(py, to_repl)?;
                let to_s = py_to_scalar(py, val_obj)?;
                let r = self
                    .inner
                    .replace(&[(from_s, to_s)])
                    .map_err(frame_error_to_py)?;
                return Ok(PySeries { inner: r });
            }

            Ok(PySeries {
                inner: self.inner.clone(),
            })
        })()?;
        Ok(series_inplace(&mut self.inner, result, inplace))
    }

    /// Cast to a dtype given as a pandas name, a Python type (`float`), a
    /// numpy/pandas dtype, or `{name: dtype}` naming this Series; errors="ignore"
    /// returns the Series unchanged on failure, as pandas does.
    #[pyo3(signature = (dtype, copy=None, errors="raise"))]
    fn astype(
        &self,
        dtype: &Bound<'_, PyAny>,
        copy: Option<&Bound<'_, PyAny>>,
        errors: &str,
    ) -> PyResult<PySeries> {
        let _ = copy; // pandas' copy= does not change the result
        let spec = if let Ok(mapping) = dtype.cast::<PyDict>() {
            let name = self.inner.name().to_owned();
            match mapping.get_item(&name)? {
                Some(spec) if mapping.len() == 1 => spec,
                _ => {
                    return Err(PyErr::new::<pyo3::exceptions::PyKeyError, _>(
                        "Only the Series name can be used for the key in Series dtype mappings.",
                    ));
                }
            }
        } else {
            dtype.clone()
        };
        if is_object_dtype_arg(&spec) {
            return Ok(PySeries {
                inner: object_series(&self.inner)?,
            });
        }
        if let Some(inner) = categorical_with_dtype(&self.inner, &spec)? {
            return Ok(PySeries { inner });
        }
        if let Some(inner) = string_dtype_series(&self.inner, &spec)? {
            return Ok(PySeries { inner });
        }
        match self.inner.astype(py_dtype_arg(&spec)?) {
            Ok(inner) => Ok(PySeries { inner }),
            Err(_) if errors == "ignore" => Ok(PySeries {
                inner: self.inner.clone(),
            }),
            Err(e) => Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                e.to_string(),
            )),
        }
    }

    /// pandas' `Series.values`: a numpy array (int64 / float64 / bool /
    /// datetime64[ns] / timedelta64[ns], else object) - it was a list.
    #[getter]
    fn values<'py>(&self, py: Python<'py>) -> PyResult<Bound<'py, PyAny>> {
        column_ndarray(py, self.inner.column())
    }

    /// pandas' `Series.to_numpy(dtype=None, copy=False, na_value=...)`:
    /// always a fresh array; `na_value` fills the missing cells, then
    /// `dtype` casts.
    #[pyo3(signature = (dtype=None, copy=false, na_value=None))]
    fn to_numpy<'py>(
        &self,
        py: Python<'py>,
        dtype: Option<&Bound<'py, PyAny>>,
        copy: bool,
        na_value: Option<&Bound<'py, PyAny>>,
    ) -> PyResult<Bound<'py, PyAny>> {
        let _ = copy; // the array is always a fresh copy
        let column = self.inner.column();
        let missing = na_value
            .map(|_| missing_ndarray(py, &[column], column.len()))
            .transpose()?;
        finish_to_numpy(column_ndarray(py, column)?, missing, dtype, na_value)
    }

    /// The numpy array protocol: `np.asarray(s)`, `np.array(s)` and numpy
    /// functions read the values (they made a 0-d object array of the
    /// repr text).
    #[pyo3(signature = (dtype=None, copy=None))]
    fn __array__<'py>(
        &self,
        py: Python<'py>,
        dtype: Option<&Bound<'py, PyAny>>,
        copy: Option<&Bound<'py, PyAny>>,
    ) -> PyResult<Bound<'py, PyAny>> {
        let _ = copy;
        finish_to_numpy(column_ndarray(py, self.inner.column())?, None, dtype, None)
    }

    /// numpy's ufunc protocol: `np.log(s)` is a Series with this index and
    /// name, as pandas' (see [`array_ufunc`]).
    #[pyo3(signature = (ufunc, method, *inputs, **kwargs))]
    fn __array_ufunc__<'py>(
        slf: &Bound<'py, Self>,
        ufunc: &Bound<'py, PyAny>,
        method: &str,
        inputs: &Bound<'py, PyTuple>,
        kwargs: Option<&Bound<'py, PyDict>>,
    ) -> PyResult<Bound<'py, PyAny>> {
        array_ufunc(slf.as_any(), ufunc, method, inputs, kwargs)
    }

    fn isin(&self, py: Python<'_>, values: &Bound<'_, PyAny>) -> PyResult<PySeries> {
        let mut scalars = Vec::new();
        if let Ok(seq) = values.cast::<pyo3::types::PySequence>() {
            let len = seq.len()?;
            scalars.reserve(len);
            for i in 0..len {
                let item = seq.get_item(i)?;
                scalars.push(py_to_scalar(py, &item)?);
            }
        }
        let res = self.inner.isin(&scalars).map_err(frame_error_to_py)?;
        Ok(PySeries { inner: res })
    }

    #[pyo3(signature = (left, right, inclusive="both"))]
    fn between(
        &self,
        py: Python<'_>,
        left: &Bound<'_, PyAny>,
        right: &Bound<'_, PyAny>,
        inclusive: &str,
    ) -> PyResult<PySeries> {
        // String bounds on a datetime/timedelta column are parsed, as pandas
        // (br-frankenpandas-rc0923-epic-python-honest-dropin-fvsao.17).
        let bound = |value: &Bound<'_, PyAny>| {
            comparison_scalar(py, value, &self.inner.dtype())?.ok_or_else(|| {
                PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                    "Invalid comparison between dtype={} and str",
                    pandas_dtype_name(&self.inner.dtype())
                ))
            })
        };
        let left_scalar = bound(left)?;
        let right_scalar = bound(right)?;
        let res = self
            .inner
            .between(&left_scalar, &right_scalar, inclusive)
            .map_err(frame_error_to_py)?;
        Ok(PySeries { inner: res })
    }

    #[pyo3(signature = (axis=None, skipna=true))]
    fn idxmax(
        &self,
        py: Python<'_>,
        axis: Option<&Bound<'_, PyAny>>,
        skipna: bool,
    ) -> PyResult<Py<PyAny>> {
        let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
        if ax != 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {ax} for object type Series"
            )));
        }
        match self.inner.idxmax_ext(skipna).map_err(frame_error_to_py)? {
            Some(label) => row_label_to_py(py, self.inner.index(), &label),
            None => Ok(pyo3::types::PyFloat::new(py, f64::NAN).into_any().unbind()),
        }
    }

    #[pyo3(signature = (axis=None, skipna=true))]
    fn idxmin(
        &self,
        py: Python<'_>,
        axis: Option<&Bound<'_, PyAny>>,
        skipna: bool,
    ) -> PyResult<Py<PyAny>> {
        let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
        if ax != 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {ax} for object type Series"
            )));
        }
        match self.inner.idxmin_ext(skipna).map_err(frame_error_to_py)? {
            Some(label) => row_label_to_py(py, self.inner.index(), &label),
            None => Ok(pyo3::types::PyFloat::new(py, f64::NAN).into_any().unbind()),
        }
    }

    fn argmax(&self) -> PyResult<i64> {
        self.inner.argmax().map_err(frame_error_to_py)
    }

    fn argmin(&self) -> PyResult<i64> {
        self.inner.argmin().map_err(frame_error_to_py)
    }

    /// Shift index by desired number of periods.
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (periods=1, freq=None, axis=None, fill_value=None, suffix=None))]
    fn shift(
        &self,
        periods: i64,
        freq: Option<&str>,
        axis: Option<&Bound<'_, PyAny>>,
        fill_value: Option<&Bound<'_, PyAny>>,
        suffix: Option<&str>,
    ) -> PyResult<PySeries> {
        unsupported_params("Series.shift", &[("suffix", suffix.is_none())])?;
        let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
        if ax != 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {ax} for object type Series"
            )));
        }
        if let Some(freq) = freq {
            let index = shift_index_by_freq(self.inner.index(), periods, freq, fill_value)?;
            let res = Series::new(self.inner.name(), index, self.inner.column().clone())
                .map_err(frame_error_to_py)?;
            return Ok(PySeries { inner: res });
        }
        let res = if let Some(fv) = fill_value {
            let sc = py_to_scalar(fv.py(), fv)?;
            self.inner
                .shift_with_fill_value(periods, sc)
                .map_err(frame_error_to_py)?
        } else {
            self.inner.shift(periods).map_err(frame_error_to_py)?
        };
        Ok(PySeries { inner: res })
    }

    /// Return Series with duplicate values removed.
    #[pyo3(signature = (keep=None, inplace=false, ignore_index=false))]
    fn drop_duplicates(
        &mut self,
        keep: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        ignore_index: bool,
    ) -> PyResult<Option<PySeries>> {
        let result = (|| -> PyResult<PySeries> {
            let keep_enum = parse_duplicate_keep(keep)?;
            let res = self
                .inner
                .drop_duplicates_keep(keep_enum)
                .map_err(frame_error_to_py)?;
            let final_series = if ignore_index {
                match res.reset_index(true).map_err(frame_error_to_py)? {
                    fp_frame::SeriesResetIndexResult::Series(s) => s,
                    fp_frame::SeriesResetIndexResult::DataFrame(_) => unreachable!(),
                }
            } else {
                res
            };
            Ok(PySeries {
                inner: final_series,
            })
        })()?;
        Ok(series_inplace(&mut self.inner, result, inplace))
    }

    /// Indicate duplicate Series values.
    #[pyo3(signature = (keep=None))]
    fn duplicated(&self, keep: Option<&Bound<'_, PyAny>>) -> PyResult<PySeries> {
        let keep_enum = parse_duplicate_keep(keep)?;
        let res = self
            .inner
            .duplicated_keep(keep_enum)
            .map_err(frame_error_to_py)?;
        Ok(PySeries { inner: res })
    }

    #[pyo3(signature = (n=5, keep="first"))]
    fn nlargest(&self, n: usize, keep: &str) -> PyResult<PySeries> {
        let res = match keep {
            "first" => self.inner.nlargest(n),
            _ => self.inner.nlargest_keep(n, keep),
        }
        .map_err(frame_error_to_py)?;
        Ok(PySeries { inner: res })
    }

    #[pyo3(signature = (n=5, keep="first"))]
    fn nsmallest(&self, n: usize, keep: &str) -> PyResult<PySeries> {
        let res = match keep {
            "first" => self.inner.nsmallest(n),
            _ => self.inner.nsmallest_keep(n, keep),
        }
        .map_err(frame_error_to_py)?;
        Ok(PySeries { inner: res })
    }

    fn isnull(&self) -> PyResult<PySeries> {
        self.isna()
    }

    fn notnull(&self) -> PyResult<PySeries> {
        self.notna()
    }

    fn copy(&self) -> PySeries {
        self.clone()
    }

    #[pyo3(signature = (name=None))]
    fn to_frame(&self, name: Option<&str>) -> PyResult<PyDataFrame> {
        let res = self.inner.to_frame(name).map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: res })
    }

    #[pyo3(signature = (
        level = None,
        drop = false,
        name = None,
        inplace = false,
        allow_duplicates = false
    ))]
    fn reset_index(
        &mut self,
        py: Python<'_>,
        level: Option<&Bound<'_, PyAny>>,
        drop: bool,
        name: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        allow_duplicates: bool,
    ) -> PyResult<Py<PyAny>> {
        // A Series index is single-level, so level 0 is the whole index.
        let level_is_default = level.is_none_or(|l| matches!(l.extract::<i64>(), Ok(0)));
        unsupported_params(
            "Series.reset_index",
            &[
                ("level", level_is_default),
                ("allow_duplicates", !allow_duplicates),
            ],
        )?;
        // In place, the Series can only lose its index (pandas' rule).
        if inplace && !drop {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "Cannot reset_index inplace on a Series to create a DataFrame",
            ));
        }
        let name_str = match name {
            Some(obj) if !obj.is_none() => {
                if let Ok(s) = obj.extract::<String>() {
                    Some(s)
                } else {
                    Some(obj.to_string())
                }
            }
            _ => None,
        };
        match self
            .inner
            .reset_index_with_name(drop, name_str.as_deref())
            .map_err(frame_error_to_py)?
        {
            fp_frame::SeriesResetIndexResult::Series(s) if inplace => {
                self.inner = s;
                Ok(py.None())
            }
            fp_frame::SeriesResetIndexResult::Series(s) => {
                Ok(Py::new(py, PySeries { inner: s })?.into_any())
            }
            fp_frame::SeriesResetIndexResult::DataFrame(df) => {
                Ok(Py::new(py, PyDataFrame { inner: df })?.into_any())
            }
        }
    }

    fn to_dict(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        let dict = PyDict::new(py);
        let keys = row_keys_to_py(py, self.inner.index())?;
        for (k, val) in keys.into_iter().zip(self.inner.values().iter()) {
            let v = scalar_to_py(py, val)?;
            dict.set_item(k, v)?;
        }
        Ok(dict.into_any().unbind())
    }

    /// pandas' `rolling(window, min_periods=, center=)`: `window` a row
    /// count or a time-based window ('7D', Day(7)) over a datetime index
