    #[pyo3(signature = (other, method="pearson", min_periods=None))]
    fn corr(
        &self,
        other: &PySeries,
        method: Option<&str>,
        min_periods: Option<usize>,
    ) -> PyResult<f64> {
        // Fewer than two pairs already correlate to NaN, so min_periods up to
        // 2 is the default answer; a larger floor needs the pair count.
        unsupported_params(
            "Series.corr",
            &[("min_periods", min_periods.is_none_or(|m| m <= 2))],
        )?;
        let m = method.unwrap_or("pearson");
        let res = match m {
            "pearson" => self.inner.corr(&other.inner),
            "spearman" => self.inner.corr_spearman(&other.inner),
            "kendall" => self.inner.corr_kendall(&other.inner),
            other_m => {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "Invalid method '{other_m}', expecting one of ('pearson', 'kendall', 'spearman')"
                )));
            }
        };
        res.map_err(frame_error_to_py)
    }

    #[pyo3(signature = (other, min_periods=None, ddof=1))]
    fn cov(
        &self,
        other: &PySeries,
        min_periods: Option<usize>,
        ddof: Option<usize>,
    ) -> PyResult<f64> {
        let ddof_val = ddof.unwrap_or(1);
        self.inner
            .cov_with_options(&other.inner, min_periods, ddof_val)
            .map_err(frame_error_to_py)
    }

    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (n=None, frac=None, replace=false, weights=None, random_state=None, axis=None, ignore_index=false))]
    /// pandas' `Series.sample`: the rows pandas draws for the same seed,
    /// `weights` included (see [`pandas_sample_positions`]).
    fn sample(
        &self,
        py: Python<'_>,
        n: Option<i64>,
        frac: Option<f64>,
        replace: bool,
        weights: Option<&Bound<'_, PyAny>>,
        random_state: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        ignore_index: bool,
    ) -> PyResult<PySeries> {
        let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
        if ax != 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {ax} for object type Series"
            )));
        }
        let weights = weights
            .filter(|weights| !weights.is_none())
            .map(|weights| sample_weights(py, weights, self.inner.index().labels(), None))
            .transpose()?;
        let positions: Vec<i64> = pandas_sample_positions(
            py,
            self.inner.len(),
            n,
            frac,
            replace,
            weights,
            random_state,
        )?
        .into_iter()
        .map(|position| i64::try_from(position).unwrap_or(i64::MAX))
        .collect();
        let mut res = self.inner.take(&positions).map_err(frame_error_to_py)?;
        if ignore_index {
            res = match res
                .reset_index_with_name(true, None)
                .map_err(frame_error_to_py)?
            {
                fp_frame::SeriesResetIndexResult::Series(s) => s,
                _ => unreachable!(),
            };
        }
        Ok(PySeries { inner: res })
    }

    /// pandas' `Series.groupby` signature (br-frankenpandas-n57tz: only `by`
    /// and `sort` were accepted); as_index=False raises as it does in pandas;
    /// a category key is checked against `observed` and `sort` (see
    /// `check_category_key`).
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (by=None, axis=None, level=None, as_index=true, sort=true, group_keys=true, observed=None, dropna=true))]
    pub fn groupby(
        &self,
        py: Python<'_>,
        by: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        level: Option<&Bound<'_, PyAny>>,
        as_index: bool,
        sort: Option<bool>,
        group_keys: bool,
        observed: Option<bool>,
        dropna: bool,
    ) -> PyResult<Py<PyAny>> {
        if !as_index {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "as_index=False only valid with DataFrame",
            ));
        }
        let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
        if ax != 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {ax} for object type Series"
            )));
        }
        // pd.Grouper(freq=) is pandas' TimeGrouper over the index: the same
        // bins as resample, empty ones included (it raised).
        if let Some(Ok(grouper)) = by.map(|by| by.extract::<PyRef<'_, PyGrouper>>()) {
            return match (&grouper.key, &grouper.level, &grouper.freq) {
                (None, None, Some(freq)) => PyResampler::new(
                    ResampleTarget::Series(self.inner.clone()),
                    freq.clone(),
                    None,
                    None,
                    None,
                )?
                .into_py_any(py),
                (Some(key), _, _) => {
                    Err(PyErr::new::<pyo3::exceptions::PyKeyError, _>(key.clone()))
                }
                _ => Err(not_implemented("this pd.Grouper form on a Series")),
            };
        }
        let sort = sort.unwrap_or(true);
        let by_series = match (by.filter(|b| !b.is_none()), level.filter(|l| !l.is_none())) {
            (Some(by), None) => extract_or_build_series(py, by, &self.inner)?,
            // pandas' level= groups by the index itself (fvsao.19); over a
            // MultiIndex by one of its levels (fvsao.36).
            (None, Some(level)) => {
                let index = self.inner.index();
                if let Some(multi) = index.row_multiindex() {
                    if level.is_instance_of::<PyList>() {
                        return Err(not_implemented("Series.groupby(level=[several levels])"));
                    }
                    let position = multiindex_level_position(multi, level)?;
                    let values: Vec<Scalar> = multi
                        .get_level_values(position)
                        .map_err(index_error_to_py)?
                        .labels()
                        .iter()
                        .map(index_label_to_scalar)
                        .collect();
                    let name = multi.names().get(position).cloned().flatten();
                    Series::new(
                        name.as_deref().unwrap_or(""),
                        index.clone(),
                        Column::from_values(values).map_err(column_error_to_py)?,
                    )
                    .map_err(frame_error_to_py)?
                } else {
                    let values = flat_index_level_values(index, level)?;
                    Series::new(index.name().unwrap_or(""), index.clone(), values)
                        .map_err(frame_error_to_py)?
                }
            }
            (Some(_), Some(_)) => {
                return Err(not_implemented("Series.groupby with both by and level"));
            }
            (None, None) => {
                return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                    "You have to supply one of 'by' and 'level'",
                ));
            }
        };
        let unused = if by_series.column().categorical().is_some() {
            let keys = by_series.to_frame(Some("key")).map_err(frame_error_to_py)?;
            check_category_keys(py, &keys, &["key".to_owned()], observed)?
        } else {
            Vec::new()
        };
        let (series, by) = if self.inner.index() != by_series.index()
            && !self.inner.index().has_duplicates()
            && !by_series.index().has_duplicates()
        {
            let common_labels: Vec<IndexLabel> = self
                .inner
                .index()
                .labels()
                .iter()
                .filter(|lbl| by_series.index().labels().contains(lbl))
                .cloned()
                .collect();
            let aligned_self = self
                .inner
                .reindex(common_labels.clone())
                .map_err(frame_error_to_py)?;
            let aligned_by = by_series
                .reindex(common_labels)
                .map_err(frame_error_to_py)?;
            (aligned_self, aligned_by)
        } else {
            (self.inner.clone(), by_series)
        };
        let (by, groups) = if dropna {
            (by, None)
        } else if unused.is_empty() {
            let (codes, groups) = missing_key_groups(&by, sort)?;
            (codes, Some(groups))
        } else {
            return Err(not_implemented(
                "Series.groupby(dropna=False) by a category key with unused categories",
            ));
        };
        PySeriesGroupBy {
            series,
            by,
            sort,
            as_index: true,
            groups,
            unused,
            group_keys,
        }
        .into_py_any(py)
    }

    /// pandas' `Series.resample(rule, closed=, label=, origin=)`; `rule` a
    /// string alias or an offset object.
    #[pyo3(signature = (freq, closed=None, label=None, origin=None))]
    pub fn resample(
        &self,
        freq: &Bound<'_, PyAny>,
        closed: Option<&str>,
        label: Option<&str>,
        origin: Option<&str>,
    ) -> PyResult<PyResampler> {
        PyResampler::new(
            ResampleTarget::Series(self.inner.clone()),
            freq_alias(freq, "resample")?,
            closed.map(str::to_string),
            label.map(str::to_string),
            origin.map(str::to_string),
        )
    }

    #[pyo3(signature = (freq, method=None))]
    pub fn asfreq(&self, freq: &str, method: Option<&str>) -> PyResult<Self> {
        let res = self
            .inner
            .asfreq_with_options(freq, method, None)
            .map_err(frame_error_to_py)?;
        Ok(Self { inner: res })
    }

    #[getter]
    fn hasnans(&self) -> bool {
        self.inner.hasnans()
    }

    #[getter]
    fn nbytes(&self) -> usize {
        self.inner.nbytes()
    }

    #[getter]
    fn t(&self) -> PySeries {
        PySeries {
            inner: self.inner.clone(),
        }
    }

    #[getter]
    #[allow(non_snake_case)]
    fn T(&self) -> PySeries {
        self.t()
    }

    fn item(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        let s = self.inner.item().map_err(frame_error_to_py)?;
        scalar_to_py(py, &s)
    }

    /// pandas' `Series.any(axis=0, bool_only=False, skipna=True, **kwargs)`
    /// (it took no arguments, so `np.any(s)` raised): `skipna=False` reads
    /// NaN as True and None as False, as pandas; `bool_only` is accepted and,
    /// as pandas' Series does, ignored.
    #[pyo3(signature = (axis=None, bool_only=false, skipna=true, **kwargs))]
    fn any(
        &self,
        py: Python<'_>,
        axis: Option<&Bound<'_, PyAny>>,
        bool_only: bool,
        skipna: bool,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Py<PyAny>> {
        let _ = bool_only;
        self.check_logical_reduction("any", axis, kwargs)?;
        let result = if skipna || !self.inner.column().has_nulls() {
            self.inner.any().map_err(frame_error_to_py)?
        } else {
            self.inner.column().values().iter().any(missing_as_truthy)
        };
        // pandas' np.bool_ (it was a Python bool).
        numpy_scalar(py, &Scalar::Bool(result))
    }

    /// pandas' `Series.all(axis=0, bool_only=False, skipna=True, **kwargs)`
    /// (see [`Self::any`]).
    #[pyo3(signature = (axis=None, bool_only=false, skipna=true, **kwargs))]
    fn all(
        &self,
        py: Python<'_>,
        axis: Option<&Bound<'_, PyAny>>,
        bool_only: bool,
        skipna: bool,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Py<PyAny>> {
        let _ = bool_only;
        self.check_logical_reduction("all", axis, kwargs)?;
        let result = if skipna || !self.inner.column().has_nulls() {
            self.inner.all().map_err(frame_error_to_py)?
        } else {
            self.inner.column().values().iter().all(missing_as_truthy)
        };
        numpy_scalar(py, &Scalar::Bool(result))
    }

    #[pyo3(signature = (axis=None, skipna=true, ddof=1, numeric_only=false))]
    fn sem(
        &self,
        axis: Option<&Bound<'_, PyAny>>,
        skipna: bool,
        ddof: Option<usize>,
        numeric_only: bool,
    ) -> PyResult<Py<PyAny>> {
        check_series_axis(axis)?;
        if numeric_only {
            self.check_numeric_only("sem")?;
        } else {
            self.require_numeric("sem")?;
        }
        let ddof_val = ddof.unwrap_or(1);
        let result = self.inner.column().sem_skipna(ddof_val, skipna);
        Python::attach(|py| reduction_to_py(py, &self.inner, "sem", &result))
    }

    #[pyo3(signature = (axis=None, skipna=true, numeric_only=false))]
    fn kurtosis(
        &self,
        axis: Option<&Bound<'_, PyAny>>,
        skipna: bool,
        numeric_only: bool,
    ) -> PyResult<f64> {
        self.kurt(axis, skipna, numeric_only)
    }

    #[pyo3(signature = (axis=None, skipna=true, numeric_only=false, min_count=0, **kwargs))]
    fn product(
        &self,
        axis: Option<&Bound<'_, PyAny>>,
        skipna: bool,
        numeric_only: bool,
        min_count: Option<usize>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Py<PyAny>> {
        self.prod(axis, skipna, numeric_only, min_count, kwargs)
    }

    #[pyo3(signature = (dropna=true))]
    fn mode(&self, dropna: bool) -> PyResult<PySeries> {
        let res = self
            .inner
            .mode_with_dropna(dropna)
            .map_err(frame_error_to_py)?;
        // The modes are numbered by pandas' RangeIndex.
        let span = res.index().int64_range_span();
        Ok(PySeries {
            inner: res.with_range_span(span),
        })
    }

    #[pyo3(signature = (before=None, after=None, axis=None, copy=None))]
    fn truncate(
        &self,
        before: Option<&Bound<'_, PyAny>>,
        after: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        copy: Option<bool>,
    ) -> PyResult<PySeries> {
        // copy= only lets pandas share buffers, which it never guarantees; a
        // new Series is a valid result for either value.
        let _ = copy;
        if let Some(a) = axis {
            let valid = if let Ok(i) = a.extract::<i64>() {
                i == 0
            } else if let Ok(s) = a.extract::<String>() {
                s == "index" || s == "rows"
            } else {
                false
            };
            if !valid {
                let msg = a.to_string();
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "No axis named {msg} for object type Series"
                )));
            }
        }
        let is_sorted = self.inner.index().is_monotonic_increasing()
            || self.inner.index().is_monotonic_decreasing();
        if !is_sorted {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "truncate requires a sorted index",
            ));
        }
        let b = match before {
            Some(obj) => Some(py_to_index_label(obj)?),
            None => None,
        };
        let a = match after {
            Some(obj) => Some(py_to_index_label(obj)?),
            None => None,
        };
        if let (Some(b_lbl), Some(a_lbl)) = (&b, &a) {
            if self.inner.index().is_monotonic_increasing() && b_lbl > a_lbl {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "Truncate: {a_lbl} must be after {b_lbl}"
                )));
            }
        }
        let res = self
            .inner
            .truncate(b.as_ref(), a.as_ref())
            .map_err(frame_error_to_py)?;
        Ok(PySeries { inner: res })
    }

