    fn first_valid_index(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        match self.inner.first_valid_index() {
            Some(l) => index_label_to_py(py, &l),
            None => Ok(py.None()),
        }
    }

    fn last_valid_index(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        match self.inner.last_valid_index() {
            Some(l) => index_label_to_py(py, &l),
            None => Ok(py.None()),
        }
    }

    fn equals(&self, other: &PySeries) -> bool {
        self.inner.equals(&other.inner)
    }

    fn pop(&mut self, py: Python<'_>, item: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        let label = py_to_index_label(item)?;
        let (scalar, remaining) = self.inner.pop(&label).map_err(frame_error_to_py)?;
        self.inner = remaining;
        scalar_to_py(py, &scalar)
    }

    #[pyo3(signature = (axis=None))]
    fn squeeze(&self, py: Python<'_>, axis: Option<&Bound<'_, PyAny>>) -> PyResult<Py<PyAny>> {
        if let Some(a) = axis {
            let valid = if let Ok(i) = a.extract::<i64>() {
                i == 0
            } else if let Ok(s) = a.extract::<String>() {
                s == "index" || s == "rows"
            } else {
                false
            };
            if !valid {
                let msg = a.to_string();
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "No axis named {msg} for object type Series"
                )));
            }
        }
        if self.inner.len() == 1 {
            let s = self.inner.column().values()[0].clone();
            scalar_to_py(py, &s)
        } else {
            Ok(Py::new(
                py,
                PySeries {
                    inner: self.inner.clone(),
                },
            )?
            .into_any())
        }
    }

    /// pandas' `Series.items()`: an iterator of (label, value) pairs, each
    /// value as iteration yields it (it was a list, so `next(s.items())`
    /// raised, and a nullable dtype's missing value came back None).
    fn items(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        let keys = row_keys_to_py(py, self.inner.index())?;
        let column = self.inner.column();
        let mut list = Vec::with_capacity(keys.len());
        for (py_l, v) in keys.into_iter().zip(column.values().iter()) {
            let py_v = iterated_to_py(py, column, v)?;
            list.push(pyo3::types::PyTuple::new(py, &[py_l, py_v])?);
        }
        Ok(PyList::new(py, list)?.try_iter()?.into_any().unbind())
    }

    fn keys(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        row_index_to_py(py, self.inner.index())
    }

    #[pyo3(signature = (axis=None, inplace=false, limit=None, downcast=None))]
    fn pad(
        &mut self,
        axis: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        limit: Option<isize>,
        downcast: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Option<PySeries>> {
        self.ffill(axis, inplace, limit, downcast, None)
    }

