    /// pandas' `Series.agg(func, axis=0, *args, **kwargs)` (see
    /// [`series_agg`]).
    #[pyo3(signature = (func, axis=None, *args, **kwargs))]
    fn agg<'py>(
        slf: &Bound<'py, Self>,
        func: &Bound<'py, PyAny>,
        axis: Option<&Bound<'py, PyAny>>,
        args: &Bound<'py, PyTuple>,
        kwargs: Option<&Bound<'py, PyDict>>,
    ) -> PyResult<Bound<'py, PyAny>> {
        check_series_axis(axis)?;
        series_agg(slf, func, args, kwargs)
    }

    #[pyo3(signature = (func, axis=None, *args, **kwargs))]
    fn aggregate<'py>(
        slf: &Bound<'py, Self>,
        func: &Bound<'py, PyAny>,
        axis: Option<&Bound<'py, PyAny>>,
        args: &Bound<'py, PyTuple>,
        kwargs: Option<&Bound<'py, PyDict>>,
    ) -> PyResult<Bound<'py, PyAny>> {
        check_series_axis(axis)?;
        series_agg(slf, func, args, kwargs)
    }

    /// pandas' `Series.repeat(repeats, axis=None)`; `np.repeat(s, 2)` passes
    /// `axis=None` (it raised), any other axis is pandas' ValueError.
    #[pyo3(signature = (repeats, axis=None))]
    fn repeat(&self, repeats: i64, axis: Option<&Bound<'_, PyAny>>) -> PyResult<PySeries> {
        if axis.is_some_and(|axis| !axis.is_none()) {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "the 'axis' parameter is not supported in the pandas implementation of repeat()",
            ));
        }
        let repeats = repeat_count(self.inner.len(), repeats)?;
        let res = self.inner.repeat(repeats).map_err(frame_error_to_py)?;
        Ok(PySeries { inner: res })
    }

    /// pandas' `searchsorted(value, side='left', sorter=None)`: one position
    /// for a scalar, an array of them for a list-like (which raised
    /// TypeError).
    #[pyo3(signature = (value, side=None, sorter=None))]
    fn searchsorted(
        &self,
        py: Python<'_>,
        value: &Bound<'_, PyAny>,
        side: Option<&str>,
        sorter: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Py<PyAny>> {
        unsupported_params(
            "Series.searchsorted",
            &[("sorter", sorter.is_none_or(|sorter| sorter.is_none()))],
        )?;
        let side = side.unwrap_or("left");
        let position = |item: &Bound<'_, PyAny>| -> PyResult<usize> {
            self.inner
                .searchsorted(&py_to_scalar(py, item)?, side)
                .map_err(frame_error_to_py)
        };
        if !value.is_instance_of::<pyo3::types::PyString>()
            && let Ok(items) = value.try_iter()
        {
            let positions = items
                .map(|item| position(&item?))
                .collect::<PyResult<Vec<_>>>()?;
            return Ok(py
                .import("numpy")?
                .call_method1("array", (positions,))?
                .unbind());
        }
        position(value)?.into_py_any(py)
    }

    #[pyo3(signature = (index=true))]
    fn memory_usage(&self, index: bool) -> usize {
        if index {
            self.inner.memory_usage()
        } else {
            self.inner.nbytes()
        }
    }

    /// pandas' `s.drop(labels=None, *, axis=0, index=None, columns=None,
    /// level=None, inplace=False, errors='raise')` (br-frankenpandas-n57tz:
    /// labels alone). `columns` means nothing for a Series and is ignored, as
    /// in pandas; `level` is refused.
    #[pyo3(signature = (
        labels=None,
        axis=None,
        index=None,
        columns=None,
        level=None,
        inplace=false,
        errors="raise"
    ))]
    #[allow(clippy::too_many_arguments)]
    fn drop(
        &mut self,
        py: Python<'_>,
        labels: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        index: Option<&Bound<'_, PyAny>>,
        columns: Option<&Bound<'_, PyAny>>,
        level: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        errors: &str,
    ) -> PyResult<Option<PySeries>> {
        parse_axis_param_for_type(axis, "Series")?;
        unsupported_params(
            "Series.drop",
            &[("level", level.is_none_or(|l| l.is_none()))],
        )?;
        let rows = match passed(labels) {
            Some(labels) => {
                if passed(index).is_some() || passed(columns).is_some() {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                        "Cannot specify both 'labels' and 'index'/'columns'",
                    ));
                }
                Some(labels)
            }
            None => passed(index),
        };
        let out = match rows {
            Some(rows) => {
                let wanted = py_label_list(&rows)?;
                let present: HashSet<&IndexLabel> = self.inner.index().labels().iter().collect();
                let (found, missing): (Vec<IndexLabel>, Vec<IndexLabel>) = wanted
                    .into_iter()
                    .partition(|label| present.contains(label));
                if !missing.is_empty() && errors != "ignore" {
                    return Err(not_found_in_axis(py, &missing)?);
                }
                self.inner.drop(&found).map_err(frame_error_to_py)?
            }
            None if passed(columns).is_some() => self.inner.clone(),
            None => {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    "Need to specify at least one of 'labels', 'index' or 'columns'",
                ));
            }
        };
        if inplace {
            self.inner = out;
            return Ok(None);
        }
        Ok(Some(PySeries { inner: out }))
    }

    fn to_list(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        self.tolist(py)
    }

    #[getter]
    fn array(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        self.values(py).map(Bound::unbind)
    }

    #[getter]
    fn axes(&self, py: Python<'_>) -> PyResult<Vec<Py<PyAny>>> {
        Ok(vec![self.index_object(py)?])
    }

    #[getter]
    fn attrs<'py>(&self, py: Python<'py>) -> PyResult<Bound<'py, PyDict>> {
        Ok(PyDict::new(py))
    }

    fn r#bool(&self) -> PyResult<bool> {
        if self.inner.len() == 1 {
            let v = &self.inner.column().values()[0];
            match v {
                Scalar::Bool(b) => Ok(*b),
                Scalar::Int64(i) => Ok(*i != 0),
                Scalar::Float64(f) => Ok(*f != 0.0 && !f.is_nan()),
                Scalar::Utf8(s) => Ok(!s.is_empty()),
                _ => Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    "cannot evaluate bool on null value",
                )),
            }
        } else {
            Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "The truth value of a Series is ambiguous. Use a.empty, a.bool(), a.item(), a.any() or a.all().",
            ))
        }
    }

    fn combine_first(&self, other: &PySeries) -> PyResult<PySeries> {
        let res = self
            .inner
            .combine_first(&other.inner)
            .map_err(frame_error_to_py)?;
        Ok(PySeries { inner: res })
    }

    #[pyo3(signature = (other, join="outer"))]
    fn align(&self, other: &PySeries, join: &str) -> PyResult<(PySeries, PySeries)> {
        let mode = match join {
            "outer" => AlignMode::Outer,
            "inner" => AlignMode::Inner,
            "left" => AlignMode::Left,
            "right" => AlignMode::Right,
            _ => {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "Invalid join mode '{join}'"
                )));
            }
        };
        let (s1, s2) = self
            .inner
            .align(&other.inner, mode)
            .map_err(frame_error_to_py)?;
        Ok((PySeries { inner: s1 }, PySeries { inner: s2 }))
    }

    fn compare(&self, other: &PySeries) -> PyResult<PyDataFrame> {
        let res = self
            .inner
            .compare(&other.inner)
            .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: res })
    }

    fn convert_dtypes(&self) -> PyResult<PySeries> {
        let res = self.inner.convert_dtypes().map_err(frame_error_to_py)?;
        Ok(PySeries { inner: res })
    }

    fn at_time(&self, time: &str) -> PyResult<PySeries> {
        let res = self.inner.at_time(time).map_err(frame_error_to_py)?;
        Ok(PySeries { inner: res })
    }

    fn between_time(&self, start: &str, end: &str) -> PyResult<PySeries> {
        let res = self
            .inner
            .between_time(start, end)
            .map_err(frame_error_to_py)?;
        Ok(PySeries { inner: res })
    }

    fn asof(&self, py: Python<'_>, label: &Bound<'_, PyAny>) -> PyResult<Py<PyAny>> {
        let lbl = py_to_index_label(label)?;
        let val = self.inner.asof_value(&lbl).map_err(frame_error_to_py)?;
        scalar_to_py(py, &val)
    }

    #[pyo3(signature = (lag=None))]
    fn autocorr(&self, lag: Option<usize>) -> PyResult<f64> {
        let l = lag.unwrap_or(1);
        self.inner.autocorr(l).map_err(frame_error_to_py)
    }

    #[pyo3(signature = (ascending=true))]
    fn argsort(&self, ascending: bool) -> PyResult<PySeries> {
        let res = self.inner.argsort(ascending).map_err(frame_error_to_py)?;
        Ok(PySeries { inner: res })
    }

    #[pyo3(signature = (func, convert_dtype=true, args=None, **kwargs))]
    fn apply(
        &self,
        py: Python<'_>,
        func: &Bound<'_, PyAny>,
        convert_dtype: bool,
        args: Option<&Bound<'_, PyTuple>>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<PySeries> {
        unsupported_params("Series.apply", &[("convert_dtype", convert_dtype)])?;
        let vals = self.inner.column().values();
        let mut out = Vec::with_capacity(vals.len());
        for v in vals {
            let py_val = scalar_to_py(py, v)?;
            let res = if let Some(extra_args) = args {
                let mut full_args = Vec::with_capacity(1 + extra_args.len());
                full_args.push(py_val);
                for a in extra_args.iter() {
                    full_args.push(a.into_any().unbind());
                }
                let t = PyTuple::new(py, &full_args)?;
                func.call(t, kwargs)?
            } else if kwargs.is_some() {
                let t = PyTuple::new(py, &[py_val])?;
                func.call(t, kwargs)?
            } else {
                func.call1((py_val,))?
            };
            out.push(py_to_scalar(py, &res)?);
        }
        // The same index (its name and a tz-aware zone kept).
        let s = series_over_index(self.inner.name(), self.inner.index(), out)?;
        Ok(PySeries { inner: s })
    }

    #[pyo3(signature = (arg, na_action=None))]
    fn map(
        &self,
        py: Python<'_>,
        arg: &Bound<'_, PyAny>,
        na_action: Option<&str>,
    ) -> PyResult<PySeries> {
        let ignore_na = na_action == Some("ignore");
        let vals = self.inner.column().values();
        // Each result keeps this index (its name and a tz-aware zone).
        let index = self.inner.index();
        if arg.is_callable() {
            let mut out = Vec::with_capacity(vals.len());
            for v in vals {
                if ignore_na && (v.is_null() || matches!(v, Scalar::Float64(f) if f.is_nan())) {
                    out.push(v.clone());
                    continue;
                }
                let py_val = scalar_to_py(py, v)?;
                let res = arg.call1((py_val,))?;
                out.push(py_to_scalar(py, &res)?);
            }
            let s = series_over_index(self.inner.name(), index, out)?;
            Ok(PySeries { inner: s })
        } else if let Ok(dict) = arg.cast::<PyDict>() {
            let mut out = Vec::with_capacity(vals.len());
            for v in vals {
                if ignore_na && (v.is_null() || matches!(v, Scalar::Float64(f) if f.is_nan())) {
                    out.push(v.clone());
                    continue;
                }
                let py_val = scalar_to_py(py, v)?;
                if let Some(mapped) = dict.get_item(&py_val)? {
                    out.push(py_to_scalar(py, &mapped)?);
                } else {
                    out.push(Scalar::Float64(f64::NAN));
                }
            }
            let s = series_over_index(self.inner.name(), index, out)?;
            Ok(PySeries { inner: s })
        } else if let Ok(other_ser) = arg.extract::<PyRef<PySeries>>() {
            let mut out = Vec::with_capacity(vals.len());
            for v in vals {
                if ignore_na && (v.is_null() || matches!(v, Scalar::Float64(f) if f.is_nan())) {
                    out.push(v.clone());
                    continue;
                }
                let lbl = match v {
                    Scalar::Utf8(s) => IndexLabel::Utf8(s.clone()),
                    Scalar::Int64(i) => IndexLabel::Int64(*i),
                    Scalar::Float64(f) => IndexLabel::Float64(OrderedF64(*f)),
                    Scalar::Bool(b) => IndexLabel::Bool(*b),
                    _ => IndexLabel::Utf8(v.to_string()),
                };
                let col_val = if let Some(idx_pos) = other_ser.inner.index().get_loc(&lbl) {
                    other_ser
                        .inner
                        .column()
                        .values()
                        .get(idx_pos)
                        .cloned()
                        .unwrap_or(Scalar::Float64(f64::NAN))
                } else {
                    Scalar::Float64(f64::NAN)
                };
                out.push(col_val);
            }
            let s = series_over_index(self.inner.name(), index, out)?;
            Ok(PySeries { inner: s })
        } else {
            Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "map expects a callable, dict, or Series",
            ))
        }
    }

    #[pyo3(signature = (percentiles=None))]
    fn describe(&self, percentiles: Option<Vec<f64>>) -> PyResult<PySeries> {
        let s = match percentiles {
            Some(p) => self
                .inner
                .describe_with_percentiles(&p)
                .map_err(frame_error_to_py)?,
            None => self.inner.describe().map_err(frame_error_to_py)?,
        };
        Ok(PySeries { inner: s })
    }

    fn dot(&self, other: &PySeries) -> PyResult<f64> {
        self.inner.dot(&other.inner).map_err(frame_error_to_py)
    }

    #[pyo3(signature = (cond, other=None, inplace=false, axis=None, level=None))]
    fn r#where(
        &mut self,
        py: Python<'_>,
        cond: &Bound<'_, PyAny>,
        other: Option<&Bound<'_, PyAny>>,
        inplace: Option<bool>,
        axis: Option<&Bound<'_, PyAny>>,
        level: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Option<PySeries>> {
        unsupported_params("Series.where", &[("level", level.is_none())])?;
        let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
        if ax != 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {ax} for object type Series"
            )));
        }
        let cond_series = normalize_series_cond(py, &self.inner, cond)?;
        let other_val = normalize_series_other(py, &self.inner, other)?;
        let res_inner = execute_series_where(&self.inner, &cond_series, &other_val)?;
        if inplace.unwrap_or(false) {
            self.inner = res_inner;
            Ok(None)
        } else {
            Ok(Some(PySeries { inner: res_inner }))
        }
    }

    #[pyo3(signature = (cond, other=None, inplace=false, axis=None, level=None))]
    fn mask(
        &mut self,
        py: Python<'_>,
        cond: &Bound<'_, PyAny>,
        other: Option<&Bound<'_, PyAny>>,
        inplace: Option<bool>,
        axis: Option<&Bound<'_, PyAny>>,
        level: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Option<PySeries>> {
        unsupported_params("Series.mask", &[("level", level.is_none())])?;
        let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
        if ax != 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {ax} for object type Series"
            )));
        }
        let cond_series = normalize_series_cond(py, &self.inner, cond)?;
        let not_cond_series = cond_series.not().map_err(frame_error_to_py)?;
        let other_val = normalize_series_other(py, &self.inner, other)?;
        let res_inner = execute_series_where(&self.inner, &not_cond_series, &other_val)?;
        if inplace.unwrap_or(false) {
            self.inner = res_inner;
            Ok(None)
        } else {
            Ok(Some(PySeries { inner: res_inner }))
        }
    }

    #[pyo3(signature = (func, *args, **kwargs))]
    fn pipe<'py>(
        &self,
        py: Python<'py>,
        func: &Bound<'py, PyAny>,
        args: &Bound<'py, pyo3::types::PyTuple>,
        kwargs: Option<&Bound<'py, PyDict>>,
    ) -> PyResult<Bound<'py, PyAny>> {
        if let Ok(tup) = func.cast::<pyo3::types::PyTuple>()
            && tup.len() == 2
        {
            let f = tup.get_item(0)?;
            let kw_name = tup.get_item(1)?.extract::<String>()?;
            let kw = kwargs.cloned().unwrap_or_else(|| PyDict::new(py));
            kw.set_item(kw_name, self.clone())?;
            return f.call(args, Some(&kw));
        }
        let mut full_args = Vec::with_capacity(args.len() + 1);
        full_args.push(Py::new(py, self.clone())?.into_any());
        for item in args.iter() {
            full_args.push(item.clone().unbind());
        }
        let tuple_args = pyo3::types::PyTuple::new(py, full_args)?;
        func.call(tuple_args, kwargs)
    }

    #[pyo3(signature = (items=None, like=None, regex=None, axis=None))]
    fn filter(
        &self,
        py: Python<'_>,
        items: Option<Vec<String>>,
        like: Option<&str>,
        regex: Option<&str>,
        axis: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<PySeries> {
        let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
        if ax != 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {ax} for object type Series"
            )));
        }
        if let Some(items_list) = items {
            let mut matched_labels = Vec::new();
            let mut matched_values = Vec::new();
            let labels = self.inner.index().labels();
            let values = self.inner.column().values();
            for item in items_list {
                for (lbl, val) in labels.iter().zip(values.iter()) {
                    if lbl.to_string() == item {
                        matched_labels.push(lbl.clone());
                        matched_values.push(val.clone());
                        break;
                    }
                }
            }
            let s = Series::from_values(self.inner.name(), matched_labels, matched_values)
                .map_err(frame_error_to_py)?;
            Ok(PySeries { inner: s })
        } else if let Some(sub) = like {
            let mut matched_labels = Vec::new();
            let mut matched_values = Vec::new();
            let labels = self.inner.index().labels();
            let values = self.inner.column().values();
            for (lbl, val) in labels.iter().zip(values.iter()) {
                if lbl.to_string().contains(sub) {
                    matched_labels.push(lbl.clone());
                    matched_values.push(val.clone());
                }
            }
            let s = Series::from_values(self.inner.name(), matched_labels, matched_values)
                .map_err(frame_error_to_py)?;
            Ok(PySeries { inner: s })
        } else if let Some(pat) = regex {
            let re_mod = py.import("re")?;
            let mut matched_labels = Vec::new();
            let mut matched_values = Vec::new();
            let labels = self.inner.index().labels();
            let values = self.inner.column().values();
            for (lbl, val) in labels.iter().zip(values.iter()) {
                let lbl_str = lbl.to_string();
                let is_match = re_mod
                    .call_method1("search", (pat, &lbl_str))?
                    .is_truthy()?;
                if is_match {
                    matched_labels.push(lbl.clone());
                    matched_values.push(val.clone());
                }
            }
            let s = Series::from_values(self.inner.name(), matched_labels, matched_values)
                .map_err(frame_error_to_py)?;
            Ok(PySeries { inner: s })
        } else {
            Ok(self.clone())
        }
    }

    #[pyo3(signature = (key, default=None))]
    fn get<'py>(
        &self,
        py: Python<'py>,
        key: &Bound<'py, PyAny>,
        default: Option<&Bound<'py, PyAny>>,
    ) -> PyResult<Bound<'py, PyAny>> {
        if let Ok(seq) = key.extract::<Vec<Bound<'py, PyAny>>>() {
            let mut labels = Vec::with_capacity(seq.len());
            for item in &seq {
                if let Ok(label) = py_to_index_label(item) {
                    if self.inner.index().position(&label).is_none() {
                        return Ok(default.cloned().unwrap_or_else(|| py.None().into_bound(py)));
                    }
                    labels.push(label);
                } else {
                    return Ok(default.cloned().unwrap_or_else(|| py.None().into_bound(py)));
                }
            }
            if let Ok(s) = self.inner.loc(&labels) {
                let py_s = Py::new(py, PySeries { inner: s })?;
                return Ok(py_s.into_bound(py).into_any());
            }
            return Ok(default.cloned().unwrap_or_else(|| py.None().into_bound(py)));
        }
        let label = match py_to_index_label(key) {
            Ok(l) => l,
            Err(_) => return Ok(default.cloned().unwrap_or_else(|| py.None().into_bound(py))),
        };
        let positions: Vec<usize> = self
            .inner
            .index()
            .labels()
            .iter()
            .enumerate()
            .filter(|(_, l)| *l == &label)
            .map(|(i, _)| i)
            .collect();
        if positions.len() > 1 {
            if let Ok(sub) = self.inner.loc(&[label]) {
                let py_s = Py::new(py, PySeries { inner: sub })?;
                return Ok(py_s.into_bound(py).into_any());
            }
        } else if let Some(pos) = positions.first() {
            let sc = &self.inner.column().values()[*pos];
            let py_val = scalar_to_py(py, sc)?;
            return Ok(py_val.into_bound(py));
        }
        Ok(default.cloned().unwrap_or_else(|| py.None().into_bound(py)))
    }

    fn first(&self, offset: &str) -> PyResult<PySeries> {
        let s = self.inner.first_offset(offset).map_err(frame_error_to_py)?;
        Ok(PySeries { inner: s })
    }

    fn last(&self, offset: &str) -> PyResult<PySeries> {
        let s = self.inner.last_offset(offset).map_err(frame_error_to_py)?;
        Ok(PySeries { inner: s })
    }

    #[getter]
    fn is_unique(&self) -> bool {
        self.inner.is_unique()
    }

    #[getter]
    fn is_monotonic_increasing(&self) -> bool {
        self.inner.is_monotonic_increasing()
    }

    #[getter]
    fn is_monotonic_decreasing(&self) -> bool {
        self.inner.is_monotonic_decreasing()
    }

    /// pandas' `Series.reindex`. `method` fills absent labels from the
    /// neighbouring source label, `fill_value` fills whatever is still missing
    /// at an absent label (fvsao.5: both used to be dropped through `**kwargs`).
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (index=None, *, axis=None, method=None, copy=None, level=None, fill_value=None, limit=None, tolerance=None))]
    fn reindex(
        &self,
        py: Python<'_>,
        index: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        method: Option<&str>,
        copy: Option<bool>,
        level: Option<&Bound<'_, PyAny>>,
        fill_value: Option<&Bound<'_, PyAny>>,
        limit: Option<usize>,
        tolerance: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<PySeries> {
        // copy= only lets pandas share buffers; a new Series satisfies it.
        let _ = copy;
        unsupported_params(
            "Series.reindex",
            &[
                ("level", level.is_none()),
                ("limit", limit.is_none()),
                ("tolerance", tolerance.is_none()),
            ],
        )?;
        let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
        if ax != 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {ax} for object type Series"
            )));
        }
        let Some(idx_obj) = index else {
            return Ok(self.clone());
        };
        // Any index-like target (a DatetimeIndex raised TypeError).
        let labels = idx_obj.extract::<IndexArg>()?.inner.labels().to_vec();
        let reindexed = match method {
            Some(m) => self.inner.reindex_with_method(labels.clone(), m),
            None => self.inner.reindex(labels.clone()),
        }
        .map_err(frame_error_to_py)?;
        let Some(fill) = fill_value.filter(|fv| !fv.is_none()) else {
            return Ok(PySeries { inner: reindexed });
        };
        let fill = py_to_scalar(py, fill)?;
        let source_positions = self.inner.index().get_indexer(&Index::new(labels.clone()));
        let values = reindexed
            .values()
            .iter()
            .zip(&source_positions)
            .map(|(value, source)| {
                if source.is_none() && value.is_missing() {
                    fill.clone()
                } else {
                    value.clone()
                }
            })
            .collect();
        let filled =
            Series::from_values(reindexed.name(), labels, values).map_err(frame_error_to_py)?;
        Ok(PySeries { inner: filled })
    }

    fn ravel(&self, py: Python<'_>) -> PyResult<Py<PyList>> {
        let vals = self.inner.ravel();
        let list = PyList::empty(py);
        for v in vals {
            list.append(scalar_to_py(py, &v)?)?;
        }
        Ok(list.into())
    }

    fn factorize(&self) -> PyResult<(PySeries, PySeries)> {
        let (codes, uniques) = self.inner.factorize().map_err(frame_error_to_py)?;
        Ok((PySeries { inner: codes }, PySeries { inner: uniques }))
    }

    fn case_when(&self, caselist: &Bound<'_, PyList>) -> PyResult<PySeries> {
        let mut cases = Vec::with_capacity(caselist.len());
        for item in caselist.iter() {
            let pair = item.cast::<pyo3::types::PyTuple>()?;
            if pair.len() != 2 {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    "case_when requires pairs of (condition, value)",
                ));
            }
            let cond = pair.get_item(0)?.extract::<PyRef<'_, PySeries>>()?;
            let val = pair.get_item(1)?.extract::<PyRef<'_, PySeries>>()?;
            cases.push((cond.inner.clone(), val.inner.clone()));
        }
        let s = self.inner.case_when(&cases).map_err(frame_error_to_py)?;
        Ok(PySeries { inner: s })
    }

    #[pyo3(signature = (other, level=None, fill_value=None, axis=None))]
    fn divmod(
        &self,
        py: Python<'_>,
        other: &Bound<'_, PyAny>,
        level: Option<&Bound<'_, PyAny>>,
        fill_value: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<(PySeries, PySeries)> {
        let q = self.floordiv(py, other, level, fill_value, axis)?;
        let r = self.r#mod(py, other, level, fill_value, axis)?;
        Ok((q, r))
    }

    #[pyo3(signature = (other, level=None, fill_value=None, axis=None))]
    fn rdivmod(
        &self,
        py: Python<'_>,
        other: &Bound<'_, PyAny>,
        level: Option<&Bound<'_, PyAny>>,
        fill_value: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<(PySeries, PySeries)> {
        let q = self.rfloordiv(py, other, level, fill_value, axis)?;
        let r = self.rmod(py, other, level, fill_value, axis)?;
        Ok((q, r))
    }

    #[pyo3(signature = (copy=None))]
    fn infer_objects(&self, copy: Option<bool>) -> PyResult<PySeries> {
        // copy= only lets pandas share buffers; a new Series satisfies it.
        let _ = copy;
        let s = self.inner.infer_objects().map_err(frame_error_to_py)?;
        Ok(PySeries { inner: s })
    }

    /// pandas' `Series.interpolate`: linear honours `limit`,
    /// `limit_direction` and `limit_area`; nearest/zero/pad/index/values/time
    /// honour `limit` in the forward direction (fvsao.5: `method` and every
    /// option used to be dropped, so any call gave linear interpolation).
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (method="linear", *, axis=None, limit=None, inplace=false, limit_direction=None, limit_area=None, downcast=None, **kwargs))]
    fn interpolate(
        &mut self,
        method: &str,
        axis: Option<&Bound<'_, PyAny>>,
        limit: Option<usize>,
        inplace: bool,
        limit_direction: Option<&str>,
        limit_area: Option<&str>,
        downcast: Option<&Bound<'_, PyAny>>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Option<PySeries>> {
        unsupported_params("Series.interpolate", &[("downcast", downcast.is_none())])?;
        engine_kwargs("Series.interpolate", "scipy", kwargs)?;
        let result = (|| -> PyResult<PySeries> {
            let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
            if ax != 0 {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "No axis named {ax} for object type Series"
                )));
            }
            if !Series::interpolate_supports(method, limit_direction, limit_area) {
                return Err(not_implemented(&format!(
                    "Series.interpolate(method='{method}') with limit_direction or limit_area"
                )));
            }
            let s = self
                .inner
                .interpolate_with(method, limit, limit_direction, limit_area)
                .map_err(frame_error_to_py)?;
            Ok(PySeries { inner: s })
        })()?;
        Ok(series_inplace(&mut self.inner, result, inplace))
    }

    /// Drops a level (a position or a name) of a MultiIndex; a flat index
    /// has only level 0.
    #[pyo3(signature = (level=None))]
    fn droplevel(&self, level: Option<&Bound<'_, PyAny>>) -> PyResult<PySeries> {
        if let Some(multi) = self.inner.index().row_multiindex() {
            let drop = match level {
                Some(level) => multiindex_level_position(multi, level)?,
                None => 0,
            };
            let keep: Vec<usize> = (0..multi.nlevels()).filter(|&l| l != drop).collect();
            let rows: Vec<usize> = (0..self.inner.len()).collect();
            let (index, rest) = multiindex_levels_index(multi, &rows, &keep)?;
            let index = match rest {
                Some(rest) => index.with_row_multiindex(rest).map_err(index_error_to_py)?,
                None => index,
            };
            let inner = Series::new(self.inner.name(), index, self.inner.column().clone())
                .map_err(frame_error_to_py)?;
            return Ok(PySeries { inner });
        }
        let level_is_zero = level.is_none_or(|level| matches!(level.extract::<i64>(), Ok(0)));
        unsupported_params("Series.droplevel", &[("level", level_is_zero)])?;
        let s = self.inner.droplevel().map_err(frame_error_to_py)?;
        Ok(PySeries { inner: s })
    }

    /// pandas' `Series.unstack(level=-1, fill_value=None, sort=True)`: the last
    /// level becomes the columns; `fill_value` fills the combinations that do
    /// not occur, and an int Series filled with an int stays int, as pandas
    /// fills during the reshape (the method took no arguments;
    /// br-frankenpandas-rc0923-epic-python-honest-dropin-fvsao.13). Other
    /// levels and sort=False are not supported yet.
    #[pyo3(signature = (level=None, fill_value=None, sort=true))]
    fn unstack(
        &self,
        py: Python<'_>,
        level: Option<&Bound<'_, PyAny>>,
        fill_value: Option<&Bound<'_, PyAny>>,
        sort: bool,
    ) -> PyResult<PyDataFrame> {
        // unstack(level=0 or its name) over a two-level MultiIndex swaps the
        // levels and unstacks the last (fvsao.36; it raised
        // NotImplementedError); other levels of a deeper index still raise.
        let mut source = self.inner.clone();
        if let Some(level) = level.filter(|level| !level.is_none())
            && let Some(multi) = self.inner.index().row_multiindex()
        {
            let position = multiindex_level_position(multi, level)?;
            if position + 1 != multi.nlevels() {
                if multi.nlevels() != 2 {
                    return Err(not_implemented(
                        "Series.unstack of a level other than the last of a MultiIndex deeper than two levels",
                    ));
                }
                let rows: Vec<usize> = (0..self.inner.len()).collect();
                let (index, swapped) = multiindex_levels_index(multi, &rows, &[1, 0])?;
                let index = match swapped {
                    Some(swapped) => index
                        .with_row_multiindex(swapped)
                        .map_err(index_error_to_py)?,
                    None => index,
                };
                source = Series::new(self.inner.name(), index, self.inner.column().clone())
                    .map_err(frame_error_to_py)?;
            }
        } else if let Some(level) = level.filter(|level| !level.is_none())
            && !matches!(level.extract::<i64>(), Ok(0 | -1))
        {
            return Err(not_implemented("Series.unstack of this level"));
        }
        if !sort {
            return Err(not_implemented("Series.unstack(sort=False)"));
        }
        let mut df = source.unstack().map_err(frame_error_to_py)?;
        if let Some(fill) = fill_value.filter(|fill| !fill.is_none()) {
            let fill = py_to_scalar(py, fill)?;
            df = df.fillna(&fill).map_err(frame_error_to_py)?;
            if self.inner.dtype() == DType::Int64 && matches!(fill, Scalar::Int64(_)) {
                df = df.astype(DType::Int64).map_err(frame_error_to_py)?;
            }
        }
        Ok(PyDataFrame { inner: df })
    }

    #[pyo3(signature = (indices, axis=None, **kwargs))]
    fn take(
        &self,
        indices: Vec<i64>,
        axis: Option<&Bound<'_, PyAny>>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<PySeries> {
        numpy_compat_kwargs("take", kwargs)?;
        let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
        if ax != 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {ax} for object type Series"
            )));
        }
        let s = self.inner.take(&indices).map_err(frame_error_to_py)?;
        Ok(PySeries { inner: s })
    }

    /// pandas' `Series.explode(ignore_index=False)` expands list-like values
    /// and leaves every scalar, strings included, as it is. A frankenpandas
    /// value is always a scalar, so the Series stays as it is. This used to
    /// split strings on a `sep` keyword pandas does not have (fvsao.5).
    #[pyo3(signature = (ignore_index=false))]
    fn explode(&self, ignore_index: bool) -> PyResult<PySeries> {
        if !ignore_index {
            return Ok(self.clone());
        }
        match self
            .inner
            .reset_index_with_name(true, None)
            .map_err(frame_error_to_py)?
        {
            fp_frame::SeriesResetIndexResult::Series(res) => Ok(PySeries { inner: res }),
            fp_frame::SeriesResetIndexResult::DataFrame(_) => unreachable!(),
        }
    }

    fn info(&self) -> String {
        self.inner.info()
    }

    fn update(&mut self, other: &PySeries) -> PyResult<()> {
        self.inner = self.inner.update(&other.inner).map_err(frame_error_to_py)?;
        Ok(())
    }

    /// pandas' `Series.xs`. On a single-level index `drop_level` changes
    /// nothing in pandas either; another level needs a MultiIndex.
    #[pyo3(signature = (key, axis=None, level=None, drop_level=true))]
    fn xs(
        &self,
        key: &Bound<'_, PyAny>,
        axis: Option<&Bound<'_, PyAny>>,
        level: Option<&Bound<'_, PyAny>>,
        drop_level: bool,
    ) -> PyResult<PySeries> {
        let _ = drop_level;
        unsupported_params("Series.xs", &[("level", level.is_none())])?;
        let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
        if ax != 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {ax} for object type Series"
            )));
        }
        let lbl = py_to_index_label(key)?;
        let s = self.inner.xs(&lbl).map_err(frame_error_to_py)?;
        Ok(PySeries { inner: s })
    }

    /// pandas' `Series.rename_axis`: `mapper` or `index` names the index.
    #[pyo3(signature = (mapper=None, *, index=None, axis=None, copy=None, inplace=false))]
    fn rename_axis(
        &self,
        mapper: Option<&Bound<'_, PyAny>>,
        index: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        copy: Option<bool>,
        inplace: bool,
    ) -> PyResult<PySeries> {
        // copy= only lets pandas share buffers; a new Series satisfies it.
        let _ = copy;
        unsupported_params("Series.rename_axis", &[("inplace", !inplace)])?;
        let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
        if ax != 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {ax} for object type Series"
            )));
        }
        let names = rename_axis_names(&index_names(self.inner.index()), mapper, index)?;
        let s = Series::new(
            self.inner.name(),
            index_with_names(self.inner.index(), names)?,
            self.inner.column().clone(),
        )
        .map_err(frame_error_to_py)?;
        Ok(PySeries { inner: s })
    }

    #[pyo3(signature = (labels, *, axis=None, copy=None))]
    fn set_axis(
        &self,
        labels: &Bound<'_, PyAny>,
        axis: Option<&Bound<'_, PyAny>>,
        copy: Option<bool>,
    ) -> PyResult<PySeries> {
        // copy= only lets pandas share buffers; a new Series satisfies it.
        let _ = copy;
        let ax = parse_axis_param_for_type(axis, "Series")?.unwrap_or(0);
        if ax != 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {ax} for object type Series"
            )));
        }
        let lbls = if let Ok(py_idx) = labels.extract::<PyRef<'_, PyIndex>>() {
            py_idx.inner.labels().to_vec()
        } else if let Ok(list) = labels.cast::<PyList>() {
            let mut v = Vec::with_capacity(list.len());
            for item in list.iter() {
                v.push(py_to_index_label(&item)?);
            }
            v
        } else {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "set_axis expects Index or list of labels",
            ));
        };
        let s = self.inner.set_axis(lbls).map_err(frame_error_to_py)?;
        Ok(PySeries { inner: s })
    }

    /// pandas' `.cat` accessor; on a Series that is not categorical it raises
    /// pandas' AttributeError (it returned empty categories and made-up codes;
    /// br-frankenpandas-hrxn9).
    #[getter]
    fn cat(&self) -> PyResult<PySeriesCategoricalAccessor> {
        if !self.inner.is_categorical() {
            return Err(PyErr::new::<pyo3::exceptions::PyAttributeError, _>(
                "Can only use .cat accessor with a 'category' dtype",
            ));
        }
        Ok(PySeriesCategoricalAccessor {
            series: self.inner.clone(),
        })
    }

    #[pyo3(signature = (other, func, fill_value=None))]
    fn combine(
        &self,
        py: Python<'_>,
        other: &PySeries,
        func: &Bound<'_, PyAny>,
        fill_value: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<PySeries> {
        let fill_scalar = match fill_value {
            Some(fv) if !fv.is_none() => Some(py_to_scalar(py, fv)?),
            _ => None,
        };
        let (s1_aligned, s2_aligned) = self
            .inner
            .align(&other.inner, AlignMode::Outer)
            .map_err(frame_error_to_py)?;
        let plan = fp_index::align(self.inner.index(), other.inner.index(), AlignMode::Outer);
        let n = plan.union_index.len();
        let mut res_vals = Vec::with_capacity(n);
        for i in 0..n {
            let v1 = if plan.left_positions[i].is_none() {
                fill_scalar.clone().unwrap_or(Scalar::Null(NullKind::NaN))
            } else {
                s1_aligned.column().values()[i].clone()
            };
            let v2 = if plan.right_positions[i].is_none() {
                fill_scalar.clone().unwrap_or(Scalar::Null(NullKind::NaN))
            } else {
                s2_aligned.column().values()[i].clone()
            };
            let py_v1 = scalar_to_py(py, &v1)?;
            let py_v2 = scalar_to_py(py, &v2)?;
            let out = func.call1((py_v1, py_v2))?;
            let sc = py_to_scalar(py, &out)?;
            res_vals.push(sc);
        }
        let col = Column::from_values(res_vals)
            .map_err(fp_frame::FrameError::Column)
            .map_err(frame_error_to_py)?;
        let res_name = if self.inner.name() == other.inner.name() {
            self.inner.name().to_string()
        } else {
            String::new()
        };
        let res_series = Series::new(res_name, plan.union_index, col).map_err(frame_error_to_py)?;
        Ok(PySeries { inner: res_series })
    }

