    fn to_xarray(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        if let Ok(xr) = py.import("xarray")
            && let Ok(da) = xr.call_method1("DataArray", (self.to_list(py)?,))
        {
            return Ok(da.into_any().unbind());
        }
        let d = PyDict::new(py);
        d.set_item(self.inner.name(), self.to_list(py)?)?;
        Ok(d.into_any().unbind())
    }

    #[pyo3(signature = (func, axis=0, *args, **kwargs))]
    fn transform(
        &self,
        py: Python<'_>,
        func: &Bound<'_, PyAny>,
        axis: Option<usize>,
        args: &Bound<'_, pyo3::types::PyTuple>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<PySeries> {
        if let Some(bad) = axis.filter(|&a| a != 0) {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "No axis named {bad} for object type Series"
            )));
        }
        self.apply(py, func, true, Some(args), kwargs)
    }

    /// A Series is its own transpose; the arguments are numpy's, which
    /// pandas accepts only at their defaults.
    #[pyo3(signature = (*args, **kwargs))]
    fn transpose(
        &self,
        args: &Bound<'_, pyo3::types::PyTuple>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<PySeries> {
        if !args.is_empty() {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "the 'axes' parameter is not supported in the pandas implementation of transpose()",
            ));
        }
        numpy_compat_kwargs("transpose", kwargs)?;
        Ok(self.clone())
    }

    /// pandas' `Series.tz_convert`: the DatetimeIndex's instants shown in
    /// `tz` (a naive index is pandas' TypeError; it always raised).
