    /// First discrete difference of element.
    #[pyo3(signature = (periods=1, axis=None))]
    fn diff(&self, periods: i64, axis: Option<&Bound<'_, PyAny>>) -> PyResult<PyDataFrame> {
        let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        let res = match ax {
            0 => self.inner.diff(periods).map_err(frame_error_to_py)?,
            1 => self.inner.diff_axis1(periods).map_err(frame_error_to_py)?,
            other => {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "No axis named {other} for object type DataFrame"
                )));
            }
        };
        Ok(PyDataFrame { inner: res })
    }

    /// Percentage change between the current and a prior element.
    ///
    /// Default fill_method is 'pad' like pandas 2.2.3; `fill_method=None`
    /// disables the forward fill.
    #[pyo3(signature = (periods=1, fill_method=Some("pad"), limit=None, freq=None, axis=None))]
    fn pct_change(
        &self,
        periods: i64,
        fill_method: Option<&str>,
        limit: Option<usize>,
        freq: Option<&str>,
        axis: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<PyDataFrame> {
        unsupported_params("DataFrame.pct_change", &[("freq", freq.is_none())])?;
        let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        let res = match ax {
            0 => self
                .inner
                .pct_change_with_fill(periods, fill_method, limit)
                .map_err(frame_error_to_py)?,
            1 => self
                .inner
                .pct_change_axis1(periods)
                .map_err(frame_error_to_py)?,
            other => {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "No axis named {other} for object type DataFrame"
                )));
            }
        };
        Ok(PyDataFrame { inner: res })
    }

    /// Return cumulative sum over a DataFrame or Series axis.
    #[pyo3(signature = (axis=None, skipna=true, **kwargs))]
    fn cumsum(
        &self,
        axis: Option<&Bound<'_, PyAny>>,
        skipna: bool,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<PyDataFrame> {
        numpy_compat_kwargs("cumsum", kwargs)?;
        let ax = parse_axis_param(axis)?;
        let res = if ax == 0 {
            self.inner.cumsum_with_skipna(skipna)
        } else {
            self.inner.cumsum_axis1_with_skipna(skipna)
        }
        .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: res })
    }

