    #[pyo3(signature = (id_vars=None, value_vars=None, var_name=None, value_name=None, col_level=None, ignore_index=true))]
    fn melt(
        &self,
        id_vars: Option<&Bound<'_, PyAny>>,
        value_vars: Option<&Bound<'_, PyAny>>,
        var_name: Option<&str>,
        value_name: Option<&str>,
        col_level: Option<usize>,
        ignore_index: bool,
    ) -> PyResult<PyDataFrame> {
        // Columns are single-level, so level 0 is all of them.
        unsupported_params(
            "DataFrame.melt",
            &[("col_level", col_level.is_none_or(|l| l == 0))],
        )?;
        let id_strings = extract_col_names_flexible(id_vars)?;
        let val_strings = extract_col_names_flexible(value_vars)?;
        let id_refs: Vec<&str> = id_strings.iter().map(String::as_str).collect();
        let val_refs: Vec<&str> = val_strings.iter().map(String::as_str).collect();
        let mut res = self
            .inner
            .melt(&id_refs, &val_refs, var_name, value_name)
            .map_err(frame_error_to_py)?;
        if !ignore_index {
            let n_rows = self.inner.index().len();
            let actual_value_vars_len = if val_strings.is_empty() {
                self.inner
                    .column_names()
                    .into_iter()
                    .filter(|c| !id_strings.contains(c))
                    .count()
            } else {
                val_strings.len()
            };
            if actual_value_vars_len > 0 && n_rows > 0 {
                let orig_labels = self.inner.index().labels();
                let mut repeated_labels = Vec::with_capacity(n_rows * actual_value_vars_len);
                for _ in 0..actual_value_vars_len {
                    repeated_labels.extend(orig_labels.iter().cloned());
                }
                let cols = res.columns().clone();
                let order = res
                    .column_names()
                    .into_iter()
                    .cloned()
                    .collect::<Vec<String>>();
                res = DataFrame::new_with_column_order(Index::new(repeated_labels), cols, order)
                    .map_err(frame_error_to_py)?;
            }
        }
        Ok(PyDataFrame { inner: res })
    }

    #[pyo3(signature = (columns=None, index=None, values=None))]
    fn pivot(
        &self,
        columns: Option<&Bound<'_, PyAny>>,
        index: Option<&Bound<'_, PyAny>>,
        values: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<PyDataFrame> {
        let col_name = match columns {
            Some(c) if !c.is_none() => extract_single_col_name(c)?,
            _ => {
                return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                    "DataFrame.pivot() missing 1 required argument: 'columns'",
                ));
            }
        };

        let val_names = extract_col_names_flexible(values)?;
        let val_name = if !val_names.is_empty() {
            val_names[0].clone()
        } else {
            let skip_index = match index {
                Some(idx_obj) if !idx_obj.is_none() => extract_col_names_flexible(Some(idx_obj))?,
                _ => Vec::new(),
            };
            let candidate = self
                .inner
                .column_names()
                .into_iter()
                .find(|c| *c != &col_name && !skip_index.contains(c));
            match candidate {
                Some(c) => c.clone(),
                None => {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                        "No valid column found to pivot for values",
                    ));
                }
            }
        };

        match index {
            Some(idx_obj) if !idx_obj.is_none() => {
                let idx_name = extract_single_col_name(idx_obj)?;
                let res = self
                    .inner
                    .pivot(&idx_name, &col_name, &val_name)
                    .map_err(frame_error_to_py)?;
                Ok(PyDataFrame { inner: res })
            }
            _ => {
                let idx_scalars: Vec<Scalar> = self
                    .inner
                    .index()
                    .labels()
                    .iter()
                    .map(index_label_to_scalar)
                    .collect();
                let idx_col = Column::from_values(idx_scalars).map_err(column_error_to_py)?;
                let mut col_map = BTreeMap::new();
                for name in self.inner.column_names() {
                    let col = self
                        .inner
                        .column(name)
                        .ok_or_else(|| {
                            PyErr::new::<pyo3::exceptions::PyKeyError, _>(format!(
                                "column '{name}' not found"
                            ))
                        })?
                        .clone();
                    col_map.insert(name.clone(), col);
                }
                const PIVOT_TEMP_INDEX: &str = "__fp_pivot_idx__";
                col_map.insert(PIVOT_TEMP_INDEX.to_string(), idx_col);
                let mut col_order: Vec<String> =
                    self.inner.column_names().into_iter().cloned().collect();
                col_order.push(PIVOT_TEMP_INDEX.to_string());
                let df_tmp = DataFrame::new_with_column_order(
                    self.inner.index().clone(),
                    col_map,
                    col_order,
                )
                .map_err(frame_error_to_py)?;
                let res = df_tmp
                    .pivot(PIVOT_TEMP_INDEX, &col_name, &val_name)
                    .map_err(frame_error_to_py)?;
                Ok(PyDataFrame { inner: res })
            }
        }
    }

    /// pandas' `pivot_table`, with `fill_value` filling the cells no row
    /// reached (it was refused as an unknown keyword;
    /// br-frankenpandas-rc0923-epic-python-honest-dropin-fvsao.13). Without
    /// `columns` (pandas' most common form, which required `columns`) it is
    /// the groupby aggregate of `values` (every other column when None) over
    /// `index`; `margins` adds pandas' `All` row (and `All` column), each
    /// aggregated from the original rows, not from the cells; a list of
    /// functions puts the function level first (fvsao.29). dropna=False and
    /// sort=False are not supported yet; `observed` only matters for
    /// categorical keys.
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (values=None, index=None, columns=None, aggfunc=None, fill_value=None, margins=false, dropna=true, margins_name="All", observed=None, sort=true))]
    fn pivot_table<'py>(
        slf: &Bound<'py, Self>,
        values: Option<&Bound<'py, PyAny>>,
        index: Option<&Bound<'py, PyAny>>,
        columns: Option<&Bound<'py, PyAny>>,
        aggfunc: Option<&Bound<'py, PyAny>>,
        fill_value: Option<&Bound<'py, PyAny>>,
        margins: bool,
        dropna: bool,
        margins_name: &str,
        observed: Option<bool>,
        sort: bool,
    ) -> PyResult<Bound<'py, PyAny>> {
        let py = slf.py();
        let _ = observed;
        unsupported_params("DataFrame.pivot_table", &[("dropna", dropna)])?;
        let names = |spec: Option<&Bound<'py, PyAny>>| -> PyResult<Vec<String>> {
            match spec.filter(|spec| !spec.is_none()) {
                None => Ok(Vec::new()),
                Some(spec) => match spec.extract::<String>() {
                    Ok(name) => Ok(vec![name]),
                    Err(_) => spec.extract::<Vec<String>>(),
                },
            }
        };
        let index_keys = names(index)?;
        let column_keys = names(columns)?;
        if index_keys.is_empty() {
            return Err(not_implemented("DataFrame.pivot_table without index"));
        }
        let mut value_names = names(values)?;
        if value_names.is_empty() {
            value_names = slf
                .borrow()
                .inner
                .column_names()
                .into_iter()
                .filter(|name| !index_keys.contains(name) && !column_keys.contains(name))
                .cloned()
                .collect();
        }
        let default_func = pyo3::types::PyString::new(py, "mean").into_any();
        let aggfunc = aggfunc.filter(|f| !f.is_none()).unwrap_or(&default_func);
        let keyword = |key: &str, value: Bound<'py, PyAny>| -> PyResult<Bound<'py, PyDict>> {
            let kw = PyDict::new(py);
            kw.set_item(key, value)?;
            Ok(kw)
        };
        // A list of functions: one pivot per function, the function level first.
        if aggfunc.is_instance_of::<PyList>() || aggfunc.is_instance_of::<PyTuple>() {
            let funcs: Vec<Bound<'py, PyAny>> = aggfunc.try_iter()?.collect::<PyResult<_>>()?;
            let labels = funcs.iter().map(agg_label).collect::<PyResult<Vec<_>>>()?;
            let mut results = Vec::with_capacity(funcs.len());
            for func in &funcs {
                results.push(Self::pivot_table(
                    slf,
                    values,
                    index,
                    columns,
                    Some(func),
                    fill_value,
                    margins,
                    dropna,
                    margins_name,
                    observed,
                    sort,
                )?);
            }
            return concat_side_by_side(py, results, labels);
        }
        let key_list = |keys: &[String]| -> PyResult<Bound<'py, PyAny>> {
            Ok(if keys.len() == 1 {
                pyo3::types::PyString::new(py, &keys[0]).into_any()
            } else {
                PyList::new(py, keys)?.into_any()
            })
        };
        let values_list = PyList::new(py, &value_names)?;
        let aggregate = |keys: &[String]| -> PyResult<Bound<'py, PyAny>> {
            let groupby_kwargs = PyDict::new(py);
            groupby_kwargs.set_item("sort", sort)?;
            slf.call_method("groupby", (key_list(keys)?,), Some(&groupby_kwargs))?
                .get_item(&values_list)?
                .call_method1("agg", (aggfunc,))
        };
        let simple = column_keys.len() == 1
            && index_keys.len() == 1
            && value_names.len() == 1
            && aggfunc.extract::<String>().is_ok();
        let mut table = if column_keys.is_empty() {
            aggregate(&index_keys)?
        } else if simple {
            let name = aggfunc.extract::<String>()?;
            let frame = slf.borrow().inner.clone();
            let mut res = frame
                .pivot_table(&value_names[0], &index_keys[0], &column_keys[0], &name)
                .map_err(frame_error_to_py)?;
            // pandas unstacks the aggregate: an int one (a count, or sum /
            // min / max / first / last of an int column) with every cell
            // present stays int64 (it came back float64).
            let int_aggregate = match name.as_str() {
                "count" | "size" => true,
                "sum" | "min" | "max" | "first" | "last" => frame
                    .column(&value_names[0])
                    .is_some_and(|column| column.dtype() == DType::Int64),
                _ => false,
            };
            let complete = (0..res.num_columns()).all(|position| {
                res.column_at(position)
                    .is_some_and(|column| !column.values().iter().any(Scalar::is_missing))
            });
            if int_aggregate && complete {
                res = res.astype(DType::Int64).map_err(frame_error_to_py)?;
            }
            // sort=False: rows and columns in the order their key value
            // first appears (they were refused).
            if !sort {
                let first_seen = |key: &str| {
                    let mut order: HashMap<String, usize> = HashMap::new();
                    if let Some(column) = frame.column(key) {
                        for (position, value) in column.values().iter().enumerate() {
                            order
                                .entry(scalar_to_index_label_converter(value).to_string())
                                .or_insert(position);
                        }
                    }
                    order
                };
                let rows = first_seen(&index_keys[0]);
                let mut positions: Vec<usize> = (0..res.len()).collect();
                let labels = res.index().labels().to_vec();
                positions.sort_by_key(|&row| {
                    rows.get(&labels[row].to_string())
                        .copied()
                        .unwrap_or(usize::MAX)
                });
                res = res.take_rows(&positions).map_err(frame_error_to_py)?;
                let columns = first_seen(&column_keys[0]);
                let mut names: Vec<String> = res.column_names().into_iter().cloned().collect();
                names.sort_by_key(|name| columns.get(name).copied().unwrap_or(usize::MAX));
                let refs: Vec<&str> = names.iter().map(String::as_str).collect();
                res = res.select_columns(&refs).map_err(frame_error_to_py)?;
            }
            Bound::new(py, PyDataFrame { inner: res })?.into_any()
        } else {
            return Err(not_implemented(
                "DataFrame.pivot_table with several index / columns / values keys and columns=",
            ));
        };
        if let Some(fill) = fill_value.filter(|fill| !fill.is_none()) {
            let fill = py_to_scalar(py, fill)?;
            let res = table
                .extract::<PyRef<'_, PyDataFrame>>()?
                .inner
                .fillna(&fill)
                .map_err(frame_error_to_py)?;
            // pandas fills while unstacking the aggregate, so an int
            // aggregate (sum/min/max/first/last/count of an int column)
            // filled with an int stays int64.
            let int_aggregate = value_names.len() == 1
                && slf
                    .borrow()
                    .inner
                    .column(&value_names[0])
                    .is_some_and(|c| c.dtype() == DType::Int64)
                && aggfunc.extract::<String>().is_ok_and(|name| {
                    matches!(
                        name.as_str(),
                        "sum" | "min" | "max" | "first" | "last" | "count" | "size"
                    )
                });
            let res = if int_aggregate && matches!(fill, Scalar::Int64(_)) {
                res.astype(DType::Int64).map_err(frame_error_to_py)?
            } else {
                res
            };
            table = Bound::new(py, PyDataFrame { inner: res })?.into_any();
        }
        if !margins {
            return Ok(table);
        }
        if index_keys.len() != 1 {
            return Err(not_implemented(
                "DataFrame.pivot_table(margins=True) over several index keys",
            ));
        }
        let index_name = pyo3::types::PyString::new(py, &index_keys[0]).into_any();
        let concat = py.import("frankenpandas")?.getattr("concat")?;
        let one_row = |cells: Bound<'py, PyDict>| -> PyResult<Bound<'py, PyAny>> {
            let labels = PyList::new(py, [margins_name])?;
            py.get_type::<PyDataFrame>()
                .call((cells,), Some(&keyword("index", labels.into_any())?))
        };
        let totals = slf
            .get_item(&values_list)?
            .call_method1("agg", (aggfunc,))?;
        let with_row = if column_keys.is_empty() {
            let cells = PyDict::new(py);
            for name in &value_names {
                cells.set_item(name, PyList::new(py, [totals.get_item(name)?])?)?;
            }
            concat.call1((PyList::new(py, [table, one_row(cells)?])?,))?
        } else {
            // The All column: each index group over every column label; the
            // All row: each column label over every index group; the corner:
            // everything.
            let value = &value_names[0];
            let by_index = aggregate(&index_keys)?.get_item(value)?;
            let by_column = aggregate(&column_keys)?.get_item(value)?;
            table.set_item(margins_name, by_index)?;
            let cells = PyDict::new(py);
            for label in table.getattr("columns")?.try_iter()? {
                let label = label?;
                let cell = if label.eq(margins_name)? {
                    totals.get_item(value)?
                } else {
                    by_column.get_item(&label)?
                };
                cells.set_item(label, PyList::new(py, [cell])?)?;
            }
            concat.call1((PyList::new(py, [table, one_row(cells)?])?,))?
        };
        with_row.getattr("index")?.setattr("name", index_name)?;
        Ok(with_row)
    }

    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (n=None, frac=None, replace=false, weights=None, random_state=None, axis=None, ignore_index=false))]
    /// pandas' `DataFrame.sample`: the rows (or, axis=1, columns) pandas
    /// draws for the same seed, `weights` included - a column name, a Series
    /// aligned by label, or one weight per item (see
    /// [`pandas_sample_positions`]; fp-frame's own generator drew others,
    /// and weights were refused).
    fn sample(
        &self,
        py: Python<'_>,
        n: Option<i64>,
        frac: Option<f64>,
        replace: bool,
        weights: Option<&Bound<'_, PyAny>>,
        random_state: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        ignore_index: bool,
    ) -> PyResult<PyDataFrame> {
        let ax = parse_axis_param(axis)?;
        let names: Vec<String> = self.inner.column_names().into_iter().cloned().collect();
        let labels: Vec<IndexLabel> = if ax == 1 {
            names
                .iter()
                .map(|name| IndexLabel::Utf8(name.clone()))
                .collect()
        } else {
            self.inner.index().labels().to_vec()
        };
        let weights = weights
            .filter(|weights| !weights.is_none())
            .map(|weights| sample_weights(py, weights, &labels, (ax == 0).then_some(&self.inner)))
            .transpose()?;
        let positions =
            pandas_sample_positions(py, labels.len(), n, frac, replace, weights, random_state)?;
        let mut res = if ax == 1 {
            let picked: Vec<&str> = positions
                .iter()
                .map(|&position| names[position].as_str())
                .collect();
            self.inner
                .select_columns(&picked)
                .map_err(frame_error_to_py)?
        } else {
            self.inner
                .take_rows(&positions)
                .map_err(frame_error_to_py)?
        };
        if ignore_index {
            res = res.reset_index(true).map_err(frame_error_to_py)?;
        }
        Ok(PyDataFrame { inner: res })
    }

    /// pandas' `DataFrame.resample(rule, closed=, label=, origin=, on=)`:
    /// `rule` a string alias or an offset object; `on` bins by that
    /// datetime column instead of the index (it becomes the result's index
    /// and leaves the aggregated columns), as pandas. `on=` raised TypeError.
    #[pyo3(signature = (freq, closed=None, label=None, origin=None, on=None, level=None))]
    #[allow(clippy::too_many_arguments)]
    pub fn resample(
        &self,
        freq: &Bound<'_, PyAny>,
        closed: Option<&str>,
        label: Option<&str>,
        origin: Option<&str>,
        on: Option<&str>,
        level: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<PyResampler> {
        if level.is_some_and(|level| !level.is_none()) {
            return Err(not_implemented("DataFrame.resample(level=...)"));
        }
        let frame = match on {
            Some(on) => self.inner.set_index(on, true).map_err(frame_error_to_py)?,
            None => self.inner.clone(),
        };
        PyResampler::new(
            ResampleTarget::DataFrame(frame),
            freq_alias(freq, "resample")?,
            closed.map(str::to_string),
            label.map(str::to_string),
            origin.map(str::to_string),
        )
    }

