    #[pyo3(signature = (before=None, after=None, axis=None, copy=None))]
    fn truncate(
        &self,
        before: Option<&Bound<'_, PyAny>>,
        after: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        copy: Option<bool>,
    ) -> PyResult<PyDataFrame> {
        let _ = copy;
        let axis_idx = parse_axis_param(axis)?;

        if axis_idx == 0 {
            let is_sorted = self.inner.index().is_monotonic_increasing()
                || self.inner.index().is_monotonic_decreasing();
            if !is_sorted {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    "truncate requires a sorted index",
                ));
            }
            let b = match before {
                Some(obj) => Some(py_to_index_label(obj)?),
                None => None,
            };
            let a = match after {
                Some(obj) => Some(py_to_index_label(obj)?),
                None => None,
            };
            if let (Some(b_lbl), Some(a_lbl)) = (&b, &a) {
                if self.inner.index().is_monotonic_increasing() && b_lbl > a_lbl {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                        "Truncate: {a_lbl} must be after {b_lbl}"
                    )));
                }
            }
            let res = self
                .inner
                .truncate(b.as_ref(), a.as_ref())
                .map_err(frame_error_to_py)?;
            Ok(PyDataFrame { inner: res })
        } else {
            let cols = self.inner.column_names();
            let is_sorted = cols.windows(2).all(|w| w[0] <= w[1]);
            if !is_sorted {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    "truncate requires a sorted index",
                ));
            }
            let b_str = before.map(|obj| obj.extract::<String>()).transpose()?;
            let a_str = after.map(|obj| obj.extract::<String>()).transpose()?;
            if let (Some(b), Some(a)) = (&b_str, &a_str) {
                if b > a {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                        "Truncate: {a} must be after {b}"
                    )));
                }
            }
            let start = match &b_str {
                Some(b) => cols
                    .iter()
                    .position(|c| c.as_str() >= b.as_str())
                    .unwrap_or(cols.len()),
                None => 0,
            };
            let end = match &a_str {
                Some(a) => cols
                    .iter()
                    .rposition(|c| c.as_str() <= a.as_str())
                    .map(|i| i + 1)
                    .unwrap_or(0),
                None => cols.len(),
            };
            let selected_cols: Vec<&str> = if start >= end {
                Vec::new()
            } else {
                cols[start..end].iter().map(|s| s.as_str()).collect()
            };
            let res = self
                .inner
                .select_columns(&selected_cols)
                .map_err(frame_error_to_py)?;
            Ok(PyDataFrame { inner: res })
        }
    }

    #[pyo3(signature = (prefix, axis=None))]
    fn add_prefix(&self, prefix: &str, axis: Option<&Bound<'_, PyAny>>) -> PyResult<PyDataFrame> {
        let axis_idx = match axis {
            None => 1,
            Some(a) => {
                if let Ok(i) = a.extract::<i64>() {
                    match i {
                        0 => 0,
                        1 => 1,
                        other => {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                                "No axis named {other} for object type DataFrame"
                            )));
                        }
                    }
                } else if let Ok(s) = a.extract::<String>() {
                    match s.as_str() {
                        "index" | "rows" => 0,
                        "columns" => 1,
                        other => {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                                "No axis named {other} for object type DataFrame"
                            )));
                        }
                    }
                } else {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                        "axis must be 0, 1, 'index', or 'columns'",
                    ));
                }
            }
        };
        let res = self
            .inner
            .add_prefix_axis(prefix, axis_idx)
            .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: res })
    }

    #[pyo3(signature = (suffix, axis=None))]
    fn add_suffix(&self, suffix: &str, axis: Option<&Bound<'_, PyAny>>) -> PyResult<PyDataFrame> {
        let axis_idx = match axis {
            None => 1,
            Some(a) => {
                if let Ok(i) = a.extract::<i64>() {
                    match i {
                        0 => 0,
                        1 => 1,
                        other => {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                                "No axis named {other} for object type DataFrame"
                            )));
                        }
                    }
                } else if let Ok(s) = a.extract::<String>() {
                    match s.as_str() {
                        "index" | "rows" => 0,
                        "columns" => 1,
                        other => {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                                "No axis named {other} for object type DataFrame"
                            )));
                        }
                    }
                } else {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                        "axis must be 0, 1, 'index', or 'columns'",
                    ));
                }
            }
        };
        let res = self
            .inner
            .add_suffix_axis(suffix, axis_idx)
            .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: res })
    }

    fn first_valid_index(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        match self.inner.first_valid_index() {
            Some(l) => index_label_to_py(py, &l),
            None => Ok(py.None()),
        }
    }

    fn last_valid_index(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        match self.inner.last_valid_index() {
            Some(l) => index_label_to_py(py, &l),
            None => Ok(py.None()),
        }
    }

    fn equals(&self, other: &PyDataFrame) -> bool {
        self.inner.equals(&other.inner)
    }

    fn pop(&mut self, item: &str) -> PyResult<PySeries> {
        let (series, remaining) = self.inner.pop(item).map_err(frame_error_to_py)?;
        self.inner = remaining;
        Ok(PySeries { inner: series })
    }

    #[pyo3(signature = (axis=None))]
    fn squeeze(&self, py: Python<'_>, axis: Option<&Bound<'_, PyAny>>) -> PyResult<Py<PyAny>> {
        let parsed_axis = match axis {
            None => None,
            Some(a) => {
                if let Ok(i) = a.extract::<i64>() {
                    match i {
                        0 => Some(0),
                        1 => Some(1),
                        other => {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                                "No axis named {other} for object type DataFrame"
                            )));
                        }
                    }
                } else if let Ok(s) = a.extract::<String>() {
                    match s.as_str() {
                        "index" | "rows" => Some(0),
                        "columns" => Some(1),
                        other => {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                                "No axis named {other} for object type DataFrame"
                            )));
                        }
                    }
                } else {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                        "axis must be 0, 1, 'index', or 'columns'",
                    ));
                }
            }
        };

        let num_rows = self.inner.len();
        let num_cols = self.inner.column_names().len();

        match parsed_axis {
            None => {
                if num_rows == 1 && num_cols == 1 {
                    let col_name = self.inner.column_names()[0];
                    let col = self.column_series(col_name)?;
                    let s = col.inner.column().values()[0].clone();
                    scalar_to_py(py, &s)
                } else if num_cols == 1 {
                    let col_name = self.inner.column_names()[0];
                    let col = self.column_series(col_name)?;
                    Ok(Py::new(py, col)?.into_any())
                } else if num_rows == 1 {
                    match self.inner.squeeze_to_series(0) {
                        Ok(s) => Ok(Py::new(py, PySeries { inner: s })?.into_any()),
                        Err(_) => Ok(Py::new(
                            py,
                            PyDataFrame {
                                inner: self.inner.clone(),
                            },
                        )?
                        .into_any()),
                    }
                } else {
                    Ok(Py::new(
                        py,
                        PyDataFrame {
                            inner: self.inner.clone(),
                        },
                    )?
                    .into_any())
                }
            }
            Some(0) => {
                if num_rows == 1 {
                    match self.inner.squeeze_to_series(0) {
                        Ok(s) => Ok(Py::new(py, PySeries { inner: s })?.into_any()),
                        Err(_) => Ok(Py::new(
                            py,
                            PyDataFrame {
                                inner: self.inner.clone(),
                            },
                        )?
                        .into_any()),
                    }
                } else {
                    Ok(Py::new(
                        py,
                        PyDataFrame {
                            inner: self.inner.clone(),
                        },
                    )?
                    .into_any())
                }
            }
            Some(1) => {
                if num_cols == 1 {
                    let col_name = self.inner.column_names()[0];
                    let col = self.column_series(col_name)?;
                    Ok(Py::new(py, col)?.into_any())
                } else {
                    Ok(Py::new(
                        py,
                        PyDataFrame {
                            inner: self.inner.clone(),
                        },
                    )?
                    .into_any())
                }
            }
            _ => unreachable!(),
        }
    }

    /// pandas' `DataFrame.keys()`: the columns axis.
    fn keys(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        self.columns(py)
    }

    /// pandas' `DataFrame.items()` / `iterrows()` / `itertuples()` are
    /// iterators (they were lists, so `next(df.iterrows())` raised).
    fn items(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        let mut list = Vec::with_capacity(self.inner.column_names().len());
        for col_name in self.inner.column_names() {
            let s = self.column_series(col_name)?;
            let py_s = Py::new(py, s)?;
            list.push((col_name.as_str(), py_s).into_pyobject(py)?);
        }
        Ok(PyList::new(py, list)?.try_iter()?.into_any().unbind())
    }

    fn iterrows(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        let rows = self.inner.iterrows();
        let mut list = Vec::with_capacity(rows.len());
        for (label, row_data) in rows {
            let py_label = index_label_to_py(py, &label)?;
            let mut col_items = Vec::with_capacity(row_data.len());
            let mut col_labels = Vec::with_capacity(row_data.len());
            for (col_name, val) in row_data {
                col_labels.push(IndexLabel::Utf8(col_name.to_string()));
                col_items.push(val);
            }
            let s = Series::from_values(label.to_string(), col_labels, col_items)
                .map_err(frame_error_to_py)?;
            let py_s = Py::new(py, PySeries { inner: s })?;
            list.push(pyo3::types::PyTuple::new(py, &[py_label, py_s.into_any()])?);
        }
        Ok(PyList::new(py, list)?.try_iter()?.into_any().unbind())
    }

    #[pyo3(signature = (index=true, name="Pandas"))]
    fn itertuples(&self, py: Python<'_>, index: bool, name: Option<&str>) -> PyResult<Py<PyAny>> {
        let tuples = self.inner.itertuples();
        let col_names = self.inner.column_names();
        let named_type = if let Some(n) = name {
            if let Ok(collections) = py.import("collections") {
                let mut field_names = Vec::new();
                if index {
                    field_names.push("Index".to_string());
                }
                for c in &col_names {
                    let mut sanitized: String = c
                        .chars()
                        .map(|ch| if ch.is_alphanumeric() { ch } else { '_' })
                        .collect();
                    if sanitized.is_empty() || sanitized.chars().next().unwrap().is_ascii_digit() {
                        sanitized = format!("_{sanitized}");
                    }
                    field_names.push(sanitized);
                }
                collections
                    .call_method1("namedtuple", (n, field_names))
                    .ok()
            } else {
                None
            }
        } else {
            None
        };

        let mut list = Vec::with_capacity(tuples.len());
        for (label, vals) in tuples {
            let mut py_vals = Vec::with_capacity(vals.len() + usize::from(index));
            if index {
                py_vals.push(index_label_to_py(py, &label)?);
            }
            // Each column's value as iterating that column yields it (a
            // tz-aware Timestamp, a nullable dtype's numpy scalar / pd.NA).
            for (position, v) in vals.iter().enumerate() {
                py_vals.push(match self.inner.column_at(position) {
                    Some(column) => iterated_to_py(py, column, v)?,
                    None => scalar_to_py(py, v)?,
                });
            }
            let row_obj = if let Some(ref nt) = named_type {
                let tup = pyo3::types::PyTuple::new(py, &py_vals)?;
                if let Ok(inst) = nt.call1(&tup) {
                    inst.into_any().unbind()
                } else {
                    tup.into_any().unbind()
                }
            } else {
                pyo3::types::PyTuple::new(py, &py_vals)?.into_any().unbind()
            };
            list.push(row_obj);
        }
        Ok(PyList::new(py, list)?.try_iter()?.into_any().unbind())
    }

    #[pyo3(signature = (axis=None, inplace=false, limit=None, downcast=None))]
    fn pad(
        &mut self,
        axis: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        limit: Option<isize>,
        downcast: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Option<PyDataFrame>> {
        self.ffill(axis, inplace, limit, downcast, None)
    }

    #[pyo3(signature = (axis=None, inplace=false, limit=None, downcast=None))]
    fn backfill(
        &mut self,
        axis: Option<&Bound<'_, PyAny>>,
        inplace: bool,
        limit: Option<isize>,
        downcast: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Option<PyDataFrame>> {
        self.bfill(axis, inplace, limit, downcast, None)
    }

    /// pandas' `DataFrame.agg(func, axis=0, *args, **kwargs)` (see
    /// [`frame_agg`]).
    #[pyo3(signature = (func, axis=None, *args, **kwargs))]
    fn agg<'py>(
        slf: &Bound<'py, Self>,
        func: &Bound<'py, PyAny>,
        axis: Option<&Bound<'py, PyAny>>,
        args: &Bound<'py, PyTuple>,
        kwargs: Option<&Bound<'py, PyDict>>,
    ) -> PyResult<Bound<'py, PyAny>> {
        let axis = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        frame_agg(slf, func, axis, args, kwargs)
    }

    #[pyo3(signature = (func, axis=None, *args, **kwargs))]
    fn aggregate<'py>(
        slf: &Bound<'py, Self>,
        func: &Bound<'py, PyAny>,
        axis: Option<&Bound<'py, PyAny>>,
        args: &Bound<'py, PyTuple>,
        kwargs: Option<&Bound<'py, PyDict>>,
    ) -> PyResult<Bound<'py, PyAny>> {
        let axis = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        frame_agg(slf, func, axis, args, kwargs)
    }

    /// pandas' `memory_usage(index=True, deep=False)` (deep= was an unknown
    /// keyword; fvsao.30).
    #[pyo3(signature = (index=true, deep=false))]
    fn memory_usage(&self, index: bool, deep: bool) -> PyResult<PySeries> {
        let res = self
            .inner
            .memory_usage_with_options(index, deep)
            .map_err(frame_error_to_py)?;
        Ok(PySeries { inner: res })
    }

    #[getter]
    fn axes(&self) -> Vec<Py<PyAny>> {
        Python::attach(|py| {
            let idx = self.index_object(py).ok()?;
            let cols = self.columns(py).ok()?;
            Some(vec![idx, cols])
        })
        .unwrap_or_default()
    }

    #[getter]
    fn attrs<'py>(&self, py: Python<'py>) -> PyResult<Bound<'py, PyDict>> {
        Ok(PyDict::new(py))
    }

    fn r#bool(&self) -> PyResult<bool> {
        let (r, c) = self.inner.shape();
        if r == 1 && c == 1 {
            let col = self.column_series(self.inner.column_names()[0])?;
            col.r#bool()
        } else {
            Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "The truth value of a DataFrame is ambiguous. Use a.empty, a.bool(), a.item(), a.any() or a.all().",
            ))
        }
    }

    fn combine_first(&self, other: &PyDataFrame) -> PyResult<PyDataFrame> {
        let res = self
            .inner
            .combine_first(&other.inner)
            .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: res })
    }

    #[pyo3(signature = (other, join="outer"))]
    fn align(&self, other: &PyDataFrame, join: &str) -> PyResult<(PyDataFrame, PyDataFrame)> {
        let mode = match join {
            "outer" => AlignMode::Outer,
            "inner" => AlignMode::Inner,
            "left" => AlignMode::Left,
            "right" => AlignMode::Right,
            _ => {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                    "Invalid join mode '{join}'"
                )));
            }
        };
        let (df1, df2) = self
            .inner
            .align(&other.inner, mode)
            .map_err(frame_error_to_py)?;
        Ok((PyDataFrame { inner: df1 }, PyDataFrame { inner: df2 }))
    }

    fn compare(&self, other: &PyDataFrame) -> PyResult<PyDataFrame> {
        let res = self
            .inner
            .compare(&other.inner)
            .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: res })
    }

    fn convert_dtypes(&self) -> PyResult<PyDataFrame> {
        let res = self.inner.convert_dtypes().map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: res })
    }

    fn at_time(&self, time: &str) -> PyResult<PyDataFrame> {
        let res = self.inner.at_time(time).map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: res })
    }

    fn between_time(&self, start: &str, end: &str) -> PyResult<PyDataFrame> {
        let res = self
            .inner
            .between_time(start, end)
            .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: res })
    }

    #[pyo3(signature = (label, subset=None))]
    fn asof(&self, label: &Bound<'_, PyAny>, subset: Option<Vec<String>>) -> PyResult<PySeries> {
        let lbl = py_to_index_label(label)?;
        let subset_refs: Option<Vec<&str>> = subset
            .as_ref()
            .map(|s| s.iter().map(String::as_str).collect());
        let res = self
            .inner
            .asof(&lbl, subset_refs.as_deref())
            .map_err(frame_error_to_py)?;
        Ok(PySeries { inner: res })
    }

    #[pyo3(signature = (other, axis=None, drop=false, method="pearson", numeric_only=false))]
    fn corrwith(
        &self,
        other: &Bound<'_, PyAny>,
        axis: Option<&Bound<'_, PyAny>>,
        drop: bool,
        method: Option<&str>,
        numeric_only: bool,
    ) -> PyResult<PySeries> {
        let m = method.unwrap_or("pearson");
        if !matches!(m, "pearson" | "spearman" | "kendall") {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "unsupported correlation method: '{m}'"
            )));
        }
        let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        let calc_corr = |s1: &Series, s2: &Series| -> Result<f64, FrameError> {
            match m {
                "pearson" => s1.corr(s2),
                "spearman" => s1.corr_spearman(s2),
                "kendall" => s1.corr_kendall(s2),
                _ => unreachable!(),
            }
        };

        if let Ok(other_s) = other.extract::<PyRef<PySeries>>() {
            if !matches!(
                other_s.inner.dtype(),
                DType::Int64 | DType::Float64 | DType::Bool
            ) {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    "could not convert non-numeric series to float",
                ));
            }
            if ax == 0 {
                let mut labels = Vec::new();
                let mut values = Vec::new();
                for col_name in self.inner.column_names() {
                    let col = match self.inner.column(col_name) {
                        Some(c) => c,
                        None => continue,
                    };
                    let is_num = matches!(col.dtype(), DType::Int64 | DType::Float64 | DType::Bool);
                    if !is_num {
                        if numeric_only {
                            continue;
                        }
                        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                            "Could not convert non-numeric column '{col_name}' to float"
                        )));
                    }
                    let s_col =
                        Series::new(col_name.clone(), self.inner.index().clone(), col.clone())
                            .map_err(frame_error_to_py)?;
                    let r = calc_corr(&s_col, &other_s.inner).map_err(frame_error_to_py)?;
                    if drop && r.is_nan() {
                        continue;
                    }
                    labels.push(IndexLabel::Utf8(col_name.clone()));
                    values.push(Scalar::Float64(r));
                }
                let res = Series::from_values(String::new(), labels, values)
                    .map_err(frame_error_to_py)?;
                return Ok(PySeries { inner: res });
            } else {
                let mut cols_to_use = Vec::new();
                for col_name in self.inner.column_names() {
                    let col = match self.inner.column(col_name) {
                        Some(c) => c,
                        None => continue,
                    };
                    let is_num = matches!(col.dtype(), DType::Int64 | DType::Float64 | DType::Bool);
                    if !is_num {
                        if numeric_only {
                            continue;
                        }
                        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                            "Could not convert non-numeric column '{col_name}' to float"
                        )));
                    }
                    cols_to_use.push(col_name.to_string());
                }
                let col_labels: Vec<IndexLabel> = cols_to_use
                    .iter()
                    .map(|c| IndexLabel::Utf8(c.clone()))
                    .collect();
                let mut labels = Vec::new();
                let mut values = Vec::new();
                for (row_idx, row_label) in self.inner.index().labels().iter().enumerate() {
                    let mut row_vals = Vec::with_capacity(cols_to_use.len());
                    for c in &cols_to_use {
                        if let Some(col) = self.inner.column(c) {
                            row_vals.push(col.values()[row_idx].clone());
                        }
                    }
                    let row_s =
                        Series::from_values("row".to_string(), col_labels.clone(), row_vals)
                            .map_err(frame_error_to_py)?;
                    let r = calc_corr(&row_s, &other_s.inner).map_err(frame_error_to_py)?;
                    if drop && r.is_nan() {
                        continue;
                    }
                    labels.push(row_label.clone());
                    values.push(Scalar::Float64(r));
                }
                let res = Series::from_values(String::new(), labels, values)
                    .map_err(frame_error_to_py)?;
                return Ok(PySeries { inner: res });
            }
        }

        if let Ok(other_df) = other.extract::<PyRef<PyDataFrame>>() {
            if ax == 0 {
                let mut all_cols: Vec<String> = self
                    .inner
                    .column_names()
                    .into_iter()
                    .map(|s| s.to_string())
                    .collect();
                for c in other_df.inner.column_names() {
                    if !all_cols.contains(&c.to_string()) {
                        all_cols.push(c.to_string());
                    }
                }
                let mut labels = Vec::new();
                let mut values = Vec::new();
                for col_name in &all_cols {
                    let col1 = self.inner.column(col_name);
                    let col2 = other_df.inner.column(col_name);
                    let is_num1 = col1.is_none_or(|c| {
                        matches!(c.dtype(), DType::Int64 | DType::Float64 | DType::Bool)
                    });
                    let is_num2 = col2.is_none_or(|c| {
                        matches!(c.dtype(), DType::Int64 | DType::Float64 | DType::Bool)
                    });
                    if !is_num1 || !is_num2 {
                        if numeric_only {
                            continue;
                        }
                        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                            "Could not convert non-numeric column '{col_name}' to float"
                        )));
                    }
                    let r = match (col1, col2) {
                        (Some(c1), Some(c2)) => {
                            let s1 = Series::new(
                                col_name.clone(),
                                self.inner.index().clone(),
                                c1.clone(),
                            )
                            .map_err(frame_error_to_py)?;
                            let s2 = Series::new(
                                col_name.clone(),
                                other_df.inner.index().clone(),
                                c2.clone(),
                            )
                            .map_err(frame_error_to_py)?;
                            calc_corr(&s1, &s2).map_err(frame_error_to_py)?
                        }
                        _ => f64::NAN,
                    };
                    if drop && r.is_nan() {
                        continue;
                    }
                    labels.push(IndexLabel::Utf8(col_name.clone()));
                    values.push(Scalar::Float64(r));
                }
                let res = Series::from_values(String::new(), labels, values)
                    .map_err(frame_error_to_py)?;
                return Ok(PySeries { inner: res });
            } else {
                let mut shared_cols = Vec::new();
                for c in self.inner.column_names() {
                    if let Some(other_c) = other_df.inner.column(c) {
                        let self_c = self.inner.column(c).unwrap();
                        let s_num =
                            matches!(self_c.dtype(), DType::Int64 | DType::Float64 | DType::Bool);
                        let o_num =
                            matches!(other_c.dtype(), DType::Int64 | DType::Float64 | DType::Bool);
                        if !s_num || !o_num {
                            if numeric_only {
                                continue;
                            }
                            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                                "Could not convert non-numeric column '{c}' to float"
                            )));
                        }
                        shared_cols.push(c.to_string());
                    }
                }
                let col_labels: Vec<IndexLabel> = shared_cols
                    .iter()
                    .map(|c| IndexLabel::Utf8(c.clone()))
                    .collect();
                let other_pos = other_df.inner.index().position_map_first();
                let self_pos = self.inner.index().position_map_first();
                let mut all_labels = self.inner.index().labels().to_vec();
                for lbl in other_df.inner.index().labels() {
                    if !all_labels.contains(lbl) {
                        all_labels.push(lbl.clone());
                    }
                }
                let mut labels = Vec::new();
                let mut values = Vec::new();

                for label in &all_labels {
                    let r = match (self_pos.get(label), other_pos.get(label)) {
                        (Some(&row1), Some(&row2)) => {
                            if shared_cols.len() < 2 {
                                f64::NAN
                            } else {
                                let r1_vals: Vec<Scalar> = shared_cols
                                    .iter()
                                    .map(|c| self.inner.column(c).unwrap().values()[row1].clone())
                                    .collect();
                                let r2_vals: Vec<Scalar> = shared_cols
                                    .iter()
                                    .map(|c| {
                                        other_df.inner.column(c).unwrap().values()[row2].clone()
                                    })
                                    .collect();
                                let s1 = Series::from_values(
                                    "r1".to_string(),
                                    col_labels.clone(),
                                    r1_vals,
                                )
                                .map_err(frame_error_to_py)?;
                                let s2 = Series::from_values(
                                    "r2".to_string(),
                                    col_labels.clone(),
                                    r2_vals,
                                )
                                .map_err(frame_error_to_py)?;
                                calc_corr(&s1, &s2).unwrap_or(f64::NAN)
                            }
                        }
                        _ => f64::NAN,
                    };
                    if drop && r.is_nan() {
                        continue;
                    }
                    labels.push(label.clone());
                    values.push(Scalar::Float64(r));
                }
                let res = Series::from_values(String::new(), labels, values)
                    .map_err(frame_error_to_py)?;
                return Ok(PySeries { inner: res });
            }
        }

        Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
            "other must be a Series or DataFrame",
        ))
    }

    /// pandas' `df.apply(func, axis=0, raw=False, result_type=None, args=(),
    /// by_row='compat', engine='python', engine_kwargs=None, **kwargs)`, as
    /// pandas' `FrameApply`:
    /// - a string is that method of the frame (axis passed on); a list or
    ///   dict of functions is [`frame_agg`];
    /// - a callable gets each column (axis=0) or row (axis=1) as a Series,
    ///   or with raw=True as a 1-D ndarray of `df.values`, then `args` and
    ///   `**kwargs`;
    /// - result_type='broadcast' fills the frame's own shape and dtype;
    /// - otherwise scalars become a Series over the other axis, and
    ///   sequences (lists, tuples, arrays, dicts, Series) a frame as pandas'
    ///   `wrap_results_for_axis` builds it: axis=0 one column per result
    ///   (the frame's index when the lengths match), axis=1 with Series
    ///   results or result_type='expand' one row per result.
    ///
    /// pandas' remaining shapes are a Series of Python objects (lists,
    /// dicts), which needs object cells the columnar store does not hold
    /// (fvsao.33): they raise NotImplementedError where a bare Python list
    /// came back. raw and result_type were refused, `args=` reached func as
    /// a keyword, and string / list / dict funcs raised TypeError.
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (func, axis=None, raw=false, result_type=None, args=None, by_row=None, engine=None, engine_kwargs=None, **kwargs))]
    fn apply<'py>(
        slf: &Bound<'py, Self>,
        func: &Bound<'py, PyAny>,
        axis: Option<&Bound<'py, PyAny>>,
        raw: bool,
        result_type: Option<&str>,
        args: Option<&Bound<'py, PyTuple>>,
        by_row: Option<&Bound<'py, PyAny>>,
        engine: Option<&str>,
        engine_kwargs: Option<&Bound<'py, PyAny>>,
        kwargs: Option<&Bound<'py, PyDict>>,
    ) -> PyResult<Bound<'py, PyAny>> {
        let py = slf.py();
        let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        if !matches!(result_type, None | Some("reduce" | "broadcast" | "expand")) {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "invalid value for result_type, must be one of {None, 'reduce', 'broadcast', 'expand'}",
            ));
        }
        if let Some(by_row) = by_row.filter(|value| {
            !(value.extract::<String>().is_ok_and(|v| v == "compat")
                || value.extract::<bool>().is_ok_and(|v| !v))
        }) {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "by_row={} not allowed",
                by_row.str()?
            )));
        }
        unsupported_params(
            "DataFrame.apply",
            &[
                ("engine", matches!(engine, None | Some("python"))),
                (
                    "engine_kwargs",
                    engine_kwargs.is_none_or(|value| value.is_none()),
                ),
            ],
        )?;
        let args = args.cloned().unwrap_or_else(|| PyTuple::empty(py));
        // A method name: that method, axis passed on (pandas' apply_str).
        if let Ok(name) = func.extract::<String>() {
            let call_kwargs = match kwargs {
                Some(given) => given.copy()?,
                None => PyDict::new(py),
            };
            if ax != 0 {
                call_kwargs.set_item("axis", ax)?;
            }
            return slf.getattr(name.as_str())?.call(args, Some(&call_kwargs));
        }
        // Several functions: DataFrame.agg (pandas' apply_list_or_dict_like).
        if !func.is_callable() {
            return frame_agg(slf, func, ax, &args, kwargs);
        }
        let frame = slf.borrow().inner.clone();
        let (nrows, ncols) = frame.shape();
        let names: Vec<String> = frame.column_names().into_iter().cloned().collect();
        let column_labels: Vec<IndexLabel> = names
            .iter()
            .map(|name| IndexLabel::Utf8(name.clone()))
            .collect();
        let row_index = frame_row_index(&frame)?;
        let column_index = Index::new(column_labels.clone());
        // The results label the other axis; each piece runs `along` one.
        let (count, along, result_index) = if ax == 0 {
            (ncols, nrows, &column_index)
        } else {
            (nrows, ncols, &row_index)
        };
        let np = py.import("numpy")?;
        let empty_series = |index: Index| -> PyResult<Bound<'py, PyAny>> {
            let column = Column::new(DType::Float64, vec![Scalar::Float64(f64::NAN); index.len()])
                .map_err(column_error_to_py)?;
            PySeries {
                inner: Series::new("", index, column).map_err(frame_error_to_py)?,
            }
            .into_bound_py_any(py)
        };
        // An empty axis: pandas' apply_empty_result calls func on an empty
        // float Series to see whether it reduces.
        if result_type != Some("broadcast") && (nrows == 0 || ncols == 0) {
            if !matches!(result_type, None | Some("reduce")) {
                return PyDataFrame { inner: frame }.into_bound_py_any(py);
            }
            let probe = || {
                let piece = if ax == 0 {
                    empty_series(Index::new(Vec::new()))?
                } else {
                    empty_series(column_index.clone())?
                };
                func.call(prepend_arg(piece, Some(&args))?, kwargs)
            };
            let reduces = result_type == Some("reduce")
                || probe().is_ok_and(|result| !result.is_instance_of::<PySeries>());
            if !reduces {
                return PyDataFrame { inner: frame }.into_bound_py_any(py);
            }
            let value = if result_index.is_empty() {
                Scalar::Float64(f64::NAN)
            } else {
                py_to_scalar(
                    py,
                    &func.call(
                        prepend_arg(empty_series(Index::new(Vec::new()))?, Some(&args))?,
                        kwargs,
                    )?,
                )?
            };
            let column = if result_index.is_empty() {
                Column::new(DType::Float64, Vec::new())
            } else {
                Column::from_values(vec![value; result_index.len()])
            }
            .map_err(column_error_to_py)?;
            return PySeries {
                inner: Series::new("", result_index.clone(), column).map_err(frame_error_to_py)?,
            }
            .into_bound_py_any(py);
        }
        // raw=True pieces are the 1-D slices of `df.values` (its common
        // dtype), as np.apply_along_axis hands them over.
        let values = if raw && result_type != Some("broadcast") {
            Some(slf.getattr("values")?)
        } else {
            None
        };
        let cells: Vec<&[Scalar]> = (0..ncols)
            .map(|position| {
                frame
                    .column_at(position)
                    .map(Column::values)
                    .ok_or_else(|| PyErr::new::<pyo3::exceptions::PyIndexError, _>(position))
            })
            .collect::<PyResult<_>>()?;
        let mut results = Vec::with_capacity(count);
        for position in 0..count {
            let piece = match (&values, ax) {
                (Some(values), 0) => values.get_item((pyo3::types::PySlice::full(py), position))?,
                (Some(values), _) => values.get_item(position)?,
                (None, 0) => PySeries {
                    inner: Series::new(
                        &names[position],
                        frame.series_index(),
                        frame.column_at(position).cloned().ok_or_else(|| {
                            PyErr::new::<pyo3::exceptions::PyIndexError, _>(position)
                        })?,
                    )
                    .map_err(frame_error_to_py)?,
                }
                .into_bound_py_any(py)?,
                (None, _) => {
                    let label = frame.index().labels()[position].clone();
                    let row = cells
                        .iter()
                        .map(|column| column[position].clone())
                        .collect();
                    PySeries {
                        inner: Series::from_values(label.to_string(), column_labels.clone(), row)
                            .map_err(frame_error_to_py)?,
                    }
                    .into_bound_py_any(py)?
                }
            };
            results.push(func.call(prepend_arg(piece, Some(&args))?, kwargs)?);
        }
        // result_type='broadcast': pandas fills np.empty_like(df.values) -
        // the frame's own shape and dtype - with each result, a scalar or a
        // 1-D sequence as long as the axis.
        if result_type == Some("broadcast") {
            let out = np.call_method1("empty_like", (slf.getattr("values")?,))?;
            for (position, result) in results.iter().enumerate() {
                let array = np.call_method1("asarray", (result,))?;
                let ndim: usize = array.getattr("ndim")?.extract()?;
                if ndim > 1 {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                        "too many dims to broadcast",
                    ));
                }
                if ndim == 1 && array.len()? != along {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                        "cannot broadcast result",
                    ));
                }
                if ax == 0 {
                    out.set_item((pyo3::types::PySlice::full(py), position), array)?;
                } else {
                    out.set_item(position, array)?;
                }
            }
            return frame_from_values(py, &out, &names, &row_index);
        }
        // raw=True: np.apply_along_axis - 1-D results lie along the axis and
        // keep the frame's shape; scalars fall through to a Series.
        if raw {
            let arrays = results
                .iter()
                .map(|result| np.call_method1("asarray", (result,)))
                .collect::<PyResult<Vec<_>>>()?;
            let vectors = arrays
                .iter()
                .map(|array| array.getattr("ndim")?.extract::<usize>())
                .collect::<PyResult<Vec<_>>>()?;
            if vectors.iter().any(|&ndim| ndim > 1)
                || (vectors.contains(&1) && vectors.contains(&0))
            {
                return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                    "setting an array element with a sequence.",
                ));
            }
            if vectors.contains(&1) {
                let stack = if ax == 0 { "column_stack" } else { "vstack" };
                let stacked = np.call_method1(stack, (PyList::new(py, &arrays)?,))?;
                let (rows, columns): (usize, usize) = stacked.getattr("shape")?.extract()?;
                if (rows, columns) != (nrows, ncols) {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                        "Shape of passed values is ({rows}, {columns}), indices imply ({nrows}, {ncols})"
                    )));
                }
                return frame_from_values(py, &stacked, &names, &row_index);
            }
        }
        let object_cells = || {
            not_implemented(
                "DataFrame.apply whose result is a Series of lists / dicts / tuples (object cells; fvsao.33)",
            )
        };
        // Scalars (pandas decides on the first result): a Series over the
        // other axis.
        if !results.first().is_some_and(|first| is_sequence(first)) {
            let cells = results
                .iter()
                .map(|result| {
                    if is_sequence(result) {
                        Err(object_cells())
                    } else {
                        py_to_scalar(py, result)
                    }
                })
                .collect::<PyResult<Vec<_>>>()?;
            let column = Column::from_values(cells).map_err(column_error_to_py)?;
            return PySeries {
                inner: Series::new("", result_index.clone(), column).map_err(frame_error_to_py)?,
            }
            .into_bound_py_any(py);
        }
        let all_series = results
            .iter()
            .all(|result| result.is_instance_of::<PySeries>());
        let any_series = results
            .iter()
            .any(|result| result.is_instance_of::<PySeries>());
        let all_dicts = results
            .iter()
            .all(|result| result.is_instance_of::<PyDict>());
        let any_dict = results
            .iter()
            .any(|result| result.is_instance_of::<PyDict>());
        let data = PyDict::new(py);
        if ax == 0 {
            // pandas' FrameRowApply.wrap_results_for_axis: 'reduce' and
            // all-dict results are a Series of them; otherwise one column
            // per result, and sequences of unequal length are a Series of
            // them.
            if result_type == Some("reduce") || (result_type.is_none() && all_dicts) {
                return Err(object_cells());
            }
            if any_series != all_series || any_dict {
                return Err(object_cells());
            }
            if !all_series {
                let lengths = results
                    .iter()
                    .map(|result| result.len())
                    .collect::<PyResult<Vec<_>>>()?;
                if lengths.windows(2).any(|pair| pair[0] != pair[1]) {
                    return Err(object_cells());
                }
            }
            if names.iter().collect::<HashSet<_>>().len() != names.len() {
                return Err(not_implemented(
                    "DataFrame.apply returning sequences over duplicate column names",
                ));
            }
            for (name, result) in names.iter().zip(&results) {
                data.set_item(name, result)?;
            }
            let built = py.get_type::<PyDataFrame>().call1((data,))?;
            let mut inner = built.extract::<PyRef<'_, PyDataFrame>>()?.inner.clone();
            if !all_series && inner.len() == nrows {
                inner = with_row_axis(inner, &row_index)?;
            }
            return PyDataFrame { inner }.into_bound_py_any(py);
        }
        // pandas' FrameColumnApply.wrap_results_for_axis: Series results, or
        // any sequences under 'expand', become one row each (a frame over
        // the results, transposed); other sequences are a Series of them.
        if result_type != Some("expand") && !results[0].is_instance_of::<PySeries>() {
            return Err(object_cells());
        }
        // Dicts: a column per key in first-seen order, missing where a row
        // lacks it. pandas builds them through a transpose, so numbers share
        // one dtype: all floats once any row has a float or a missing key.
        if all_dicts {
            let mut keys: Vec<Bound<'py, PyAny>> = Vec::new();
            for result in &results {
                for key in result.cast::<PyDict>()?.keys() {
                    if !keys.iter().any(|seen| seen.eq(&key).unwrap_or(false)) {
                        keys.push(key);
                    }
                }
            }
            let mut cells = Vec::with_capacity(keys.len());
            for key in &keys {
                let mut column = Vec::with_capacity(results.len());
                for result in &results {
                    column.push(match result.cast::<PyDict>()?.get_item(key)? {
                        Some(value) => py_to_scalar(py, &value)?,
                        None => Scalar::Null(NullKind::NaN),
                    });
                }
                cells.push(column);
            }
            let numeric = cells.iter().flatten().all(|value| {
                matches!(
                    value,
                    Scalar::Int64(_) | Scalar::Float64(_) | Scalar::Null(_)
                )
            });
            if numeric
                && cells
                    .iter()
                    .flatten()
                    .any(|value| matches!(value, Scalar::Float64(_) | Scalar::Null(_)))
            {
                for value in cells.iter_mut().flatten() {
                    if let Scalar::Int64(v) = value {
                        *value = Scalar::Float64(*v as f64);
                    }
                }
            }
            let mut columns = BTreeMap::new();
            let mut order = Vec::with_capacity(keys.len());
            for (key, column) in keys.iter().zip(cells) {
                let name = key.str()?.to_string();
                columns.insert(
                    name.clone(),
                    Column::from_values(column).map_err(column_error_to_py)?,
                );
                order.push(name);
            }
            let inner = DataFrame::new_with_column_order(row_index.clone(), columns, order)
                .map_err(frame_error_to_py)?;
            return PyDataFrame {
                inner: with_row_axis(inner, &row_index)?,
            }
            .into_bound_py_any(py);
        }
        for (position, result) in results.iter().enumerate() {
            data.set_item(position, result)?;
        }
        let built = py.get_type::<PyDataFrame>().call1((data,))?;
        let transposed = built.extract::<PyRef<'_, PyDataFrame>>()?.transposed()?;
        PyDataFrame {
            inner: with_row_axis(transposed.inner, &row_index)?,
        }
        .into_bound_py_any(py)
    }

    fn applymap(&self, py: Python<'_>, func: &Bound<'_, PyAny>) -> PyResult<PyDataFrame> {
        let (nrows, ncols) = self.inner.shape();
        let col_names = self.inner.column_names();
        let mut col_map = BTreeMap::new();
        let mut column_order = Vec::with_capacity(ncols);
        for col_name in &col_names {
            let s = self.column_series(col_name)?;
            let vals = s.inner.column().values();
            let mut out = Vec::with_capacity(nrows);
            for v in vals {
                let py_v = scalar_to_py(py, v)?;
                let res = func.call1((py_v,))?;
                out.push(py_to_scalar(py, &res)?);
            }
            let col = Column::from_values(out)
                .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
            column_order.push((*col_name).clone());
            col_map.insert((*col_name).clone(), col);
        }
        let df =
            DataFrame::new_with_column_order(self.inner.index().clone(), col_map, column_order)
                .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    fn map(&self, py: Python<'_>, func: &Bound<'_, PyAny>) -> PyResult<PyDataFrame> {
        self.applymap(py, func)
    }

    fn dot(&self, other: &PyDataFrame) -> PyResult<PyDataFrame> {
        let df = self.inner.dot(&other.inner).map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    #[pyo3(signature = (cond, other=None, inplace=false, axis=None, level=None))]
    fn r#where(
        &mut self,
        py: Python<'_>,
        cond: &Bound<'_, PyAny>,
        other: Option<&Bound<'_, PyAny>>,
        inplace: Option<bool>,
        axis: Option<&Bound<'_, PyAny>>,
        level: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Option<PyDataFrame>> {
        unsupported_params("DataFrame.where", &[("level", level.is_none())])?;
        let ax = parse_axis_param_for_type(axis, "DataFrame")?;
        let cond_norm = normalize_df_cond(py, &self.inner, cond)?;
        let other_norm = normalize_df_other(py, &self.inner, other)?;
        let res_inner = execute_df_where(&self.inner, &cond_norm, &other_norm, ax)?;
        if inplace.unwrap_or(false) {
            self.inner = res_inner;
            Ok(None)
        } else {
            Ok(Some(PyDataFrame { inner: res_inner }))
        }
    }

    #[pyo3(signature = (cond, other=None, inplace=false, axis=None, level=None))]
    fn mask(
        &mut self,
        py: Python<'_>,
        cond: &Bound<'_, PyAny>,
        other: Option<&Bound<'_, PyAny>>,
        inplace: Option<bool>,
        axis: Option<&Bound<'_, PyAny>>,
        level: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<Option<PyDataFrame>> {
        unsupported_params("DataFrame.mask", &[("level", level.is_none())])?;
        let ax = parse_axis_param_for_type(axis, "DataFrame")?;
        let cond_norm = normalize_df_cond(py, &self.inner, cond)?;
        let other_norm = normalize_df_other(py, &self.inner, other)?;
        let res_inner = execute_df_mask(&self.inner, &cond_norm, &other_norm, ax)?;
        if inplace.unwrap_or(false) {
            self.inner = res_inner;
            Ok(None)
        } else {
            Ok(Some(PyDataFrame { inner: res_inner }))
        }
    }

    #[pyo3(signature = (func, *args, **kwargs))]
    fn pipe<'py>(
        &self,
        py: Python<'py>,
        func: &Bound<'py, PyAny>,
        args: &Bound<'py, pyo3::types::PyTuple>,
        kwargs: Option<&Bound<'py, PyDict>>,
    ) -> PyResult<Bound<'py, PyAny>> {
        if let Ok(tup) = func.cast::<pyo3::types::PyTuple>()
            && tup.len() == 2
        {
            let f = tup.get_item(0)?;
            let kw_name = tup.get_item(1)?.extract::<String>()?;
            let kw = kwargs.cloned().unwrap_or_else(|| PyDict::new(py));
            kw.set_item(kw_name, self.clone())?;
            return f.call(args, Some(&kw));
        }
        let mut full_args = Vec::with_capacity(args.len() + 1);
        full_args.push(Py::new(py, self.clone())?.into_any());
        for item in args.iter() {
            full_args.push(item.clone().unbind());
        }
        let tuple_args = pyo3::types::PyTuple::new(py, full_args)?;
        func.call(tuple_args, kwargs)
    }

    #[pyo3(signature = (items=None, like=None, regex=None, axis=None))]
    fn filter(
        &self,
        items: Option<Vec<String>>,
        like: Option<&str>,
        regex: Option<&str>,
        axis: Option<usize>,
    ) -> PyResult<PyDataFrame> {
        let ax = axis.unwrap_or(1);
        let items_refs: Option<Vec<&str>> = items
            .as_ref()
            .map(|v| v.iter().map(String::as_str).collect());
        let df = self
            .inner
            .filter_axis(items_refs.as_deref(), like, regex, ax)
            .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    #[pyo3(signature = (key, default=None))]
    fn get<'py>(
        &self,
        py: Python<'py>,
        key: &Bound<'py, PyAny>,
        default: Option<&Bound<'py, PyAny>>,
    ) -> PyResult<Bound<'py, PyAny>> {
        if let Ok(col_name) = key.extract::<String>() {
            let col_names = self.inner.column_names();
            let matches: Vec<&str> = col_names
                .iter()
                .filter(|c| c.as_str() == col_name.as_str())
                .map(|s| s.as_str())
                .collect();
            if matches.len() > 1 {
                let frame = self
                    .inner
                    .select_columns(&matches)
                    .map_err(frame_error_to_py)?;
                let py_df = Py::new(py, PyDataFrame { inner: frame })?;
                return Ok(py_df.into_bound(py).into_any());
            } else if matches.len() == 1 {
                if let Some(col) = self.inner.column(&col_name) {
                    let s = Series::new(col_name, self.inner.index().clone(), col.clone())
                        .map_err(frame_error_to_py)?;
                    let py_s = Py::new(py, PySeries { inner: s })?;
                    return Ok(py_s.into_bound(py).into_any());
                }
            }
        } else if let Ok(cols) = key.extract::<Vec<String>>() {
            let mut all_exist = true;
            for col in &cols {
                if self.inner.column(col).is_none() {
                    all_exist = false;
                    break;
                }
            }
            if all_exist {
                let refs: Vec<&str> = cols.iter().map(String::as_str).collect();
                let frame = self
                    .inner
                    .select_columns(&refs)
                    .map_err(frame_error_to_py)?;
                let py_df = Py::new(py, PyDataFrame { inner: frame })?;
                return Ok(py_df.into_bound(py).into_any());
            }
        }
        Ok(default.cloned().unwrap_or_else(|| py.None().into_bound(py)))
    }

    fn first(&self, offset: &str) -> PyResult<PyDataFrame> {
        let df = self.inner.first_offset(offset).map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    fn last(&self, offset: &str) -> PyResult<PyDataFrame> {
        let df = self.inner.last_offset(offset).map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    /// pandas' `DataFrame.reindex`. `method` fills absent row labels from the
    /// neighbouring source row and `fill_value` fills absent row labels and
    /// new columns (fvsao.5: both used to be dropped through `**kwargs`).
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (labels=None, *, index=None, columns=None, axis=None, method=None, copy=None, level=None, fill_value=None, limit=None, tolerance=None))]
    fn reindex(
        &self,
        py: Python<'_>,
        labels: Option<&Bound<'_, PyAny>>,
        index: Option<&Bound<'_, PyAny>>,
        columns: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        method: Option<&str>,
        copy: Option<bool>,
        level: Option<&Bound<'_, PyAny>>,
        fill_value: Option<&Bound<'_, PyAny>>,
        limit: Option<usize>,
        tolerance: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<PyDataFrame> {
        // copy= only lets pandas share buffers; a new frame satisfies it.
        let _ = copy;
        let fill = match fill_value.filter(|fv| !fv.is_none()) {
            Some(fv) => Some(py_to_scalar(py, fv)?),
            None => None,
        };
        unsupported_params(
            "DataFrame.reindex",
            &[
                ("level", level.is_none()),
                ("limit", limit.is_none()),
                ("tolerance", tolerance.is_none()),
                (
                    "method",
                    method.is_none() || (fill.is_none() && columns.is_none()),
                ),
            ],
        )?;
        let mut res = self.inner.clone();
        let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        let target_index = index.or_else(|| labels.filter(|_| ax == 0));
        if let Some(idx_obj) = target_index {
            // Any index-like target (a DatetimeIndex raised TypeError).
            let row_labels = idx_obj.extract::<IndexArg>()?.inner.labels().to_vec();
            res = match (method, &fill) {
                (Some(m), _) => res.reindex_with_method(row_labels, m),
                (None, Some(f)) => res.reindex_fill(row_labels, f.clone()),
                (None, None) => res.reindex(row_labels),
            }
            .map_err(frame_error_to_py)?;
        }
        let target_columns = columns.or_else(|| labels.filter(|_| ax == 1));
        if let Some(col_obj) = target_columns {
            let col_names: Vec<String> = if let Ok(list) = col_obj.cast::<PyList>() {
                let mut cols = Vec::with_capacity(list.len());
                for item in list.iter() {
                    cols.push(item.extract::<String>()?);
                }
                cols
            } else {
                col_obj.extract::<Vec<String>>()?
            };
            let str_cols: Vec<&str> = col_names.iter().map(String::as_str).collect();
            res = res.reindex_columns(&str_cols).map_err(frame_error_to_py)?;
            if let Some(f) = &fill {
                for name in col_names.iter().filter(|c| self.inner.column(c).is_none()) {
                    let filled = Column::from_values(vec![f.clone(); res.len()]).map_err(|e| {
                        PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string())
                    })?;
                    res = res
                        .with_column(name.clone(), filled)
                        .map_err(frame_error_to_py)?;
                }
            }
        }
        Ok(PyDataFrame { inner: res })
    }

    #[pyo3(signature = (include=None, exclude=None))]
    fn select_dtypes(
        &self,
        include: Option<&Bound<'_, PyAny>>,
        exclude: Option<&Bound<'_, PyAny>>,
    ) -> PyResult<PyDataFrame> {
        let extract_str_vec = |obj: Option<&Bound<'_, PyAny>>| -> PyResult<Vec<String>> {
            match obj {
                None => Ok(Vec::new()),
                Some(o) => {
                    if let Ok(s) = o.extract::<String>() {
                        Ok(vec![s])
                    } else if let Ok(list) = o.cast::<PyList>() {
                        let mut v = Vec::with_capacity(list.len());
                        for item in list.iter() {
                            v.push(item.extract::<String>()?);
                        }
                        Ok(v)
                    } else {
                        o.extract::<Vec<String>>()
                    }
                }
            }
        };
        let inc = extract_str_vec(include)?;
        let exc = extract_str_vec(exclude)?;
        let inc_refs: Vec<&str> = inc.iter().map(String::as_str).collect();
        let exc_refs: Vec<&str> = exc.iter().map(String::as_str).collect();
        let df = self
            .inner
            .select_dtypes_by_name(&inc_refs, &exc_refs)
            .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    #[pyo3(signature = (loc, column, value, allow_duplicates=false))]
    fn insert(
        &mut self,
        py: Python<'_>,
        loc: usize,
        column: &str,
        value: &Bound<'_, PyAny>,
        allow_duplicates: bool,
    ) -> PyResult<()> {
        // A Series as it stands; a list, tuple, array or Index by position; a
        // scalar broadcast down every row, as pandas (a scalar raised;
        // fvsao.30).
        let col = if let Ok(py_s) = value.extract::<PyRef<'_, PySeries>>() {
            py_s.inner.column().clone()
        } else {
            py_value_to_column(py, value, self.inner.len())?
        };
        self.inner = self
            .inner
            .insert_allow_duplicates(loc, column, col, allow_duplicates)
            .map_err(frame_error_to_py)?;
        Ok(())
    }

    /// pandas' `join(other, on=None, how='left', lsuffix='', rsuffix='',
    /// sort=False, validate=None)`: index on index through [`merge_impl`],
    /// keeping the caller's (typed) index labels - it stringified both
    /// indexes into a key column and returned a fresh 0..n-1 index, and an
    /// int label 1 met a string '1' (fvsao.31); `on=` matches the caller's
    /// column against `other`'s index (it matched a same-named column of
    /// `other`), keeping the caller's index; overlapping columns without a
    /// suffix are pandas' ValueError.
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (other, on=None, how="left", lsuffix="", rsuffix="", sort=false, validate=None))]
    fn join(
        &self,
        py: Python<'_>,
        other: &Bound<'_, PyAny>,
        on: Option<&Bound<'_, PyAny>>,
        how: &str,
        lsuffix: &str,
        rsuffix: &str,
        sort: bool,
        validate: Option<&str>,
    ) -> PyResult<PyDataFrame> {
        let right_df = if let Ok(odf) = other.extract::<PyRef<'_, PyDataFrame>>() {
            odf.inner.clone()
        } else if let Ok(os) = other.extract::<PyRef<'_, PySeries>>() {
            let col_name = os.inner.name();
            let mut map = BTreeMap::new();
            map.insert(col_name.to_string(), os.inner.column().clone());
            DataFrame::new_with_column_order(
                os.inner.index().clone(),
                map,
                vec![col_name.to_string()],
            )
            .map_err(frame_error_to_py)?
        } else {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "join expects DataFrame or Series",
            ));
        };
        let on_keys = on
            .filter(|on| !on.is_none())
            .map(merge_key_names)
            .transpose()?;
        let overlap: Vec<String> = self
            .inner
            .column_names()
            .iter()
            .filter(|name| right_df.column(name).is_some())
            .map(|name| format!("'{name}'"))
            .collect();
        if !overlap.is_empty() && lsuffix.is_empty() && rsuffix.is_empty() {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "columns overlap but no suffix specified: Index([{}], dtype='object')",
                overlap.join(", ")
            )));
        }
        let suffixes = PyTuple::new(py, [lsuffix, rsuffix])?;
        let Some(keys) = on_keys else {
            let args = MergeArgs {
                how,
                on: None,
                left_on: None,
                right_on: None,
                left_index: true,
                right_index: true,
                sort,
                suffixes: Some(suffixes.as_any()),
                indicator: None,
                validate,
            };
            return Ok(PyDataFrame {
                inner: merge_impl(&self.inner, &right_df, &args)?,
            });
        };
        let [key] = keys.as_slice() else {
            return Err(not_implemented(
                "DataFrame.join(on=[several columns]) against a MultiIndex",
            ));
        };
        if !matches!(how, "left" | "inner") {
            return Err(not_implemented(&format!(
                "DataFrame.join(on=..., how='{how}')"
            )));
        }
        // `other`'s index as a key column, and each caller row's position,
        // so the result keeps the caller's labels.
        const OTHER_INDEX: &str = "__fp_join_other_index__";
        const CALLER_ROW: &str = "__fp_join_caller_row__";
        let other_labels: Vec<Scalar> = right_df
            .index()
            .labels()
            .iter()
            .map(index_label_to_scalar)
            .collect();
        let other_keyed = right_df
            .with_column(
                OTHER_INDEX,
                Column::from_values(other_labels).map_err(column_error_to_py)?,
            )
            .map_err(frame_error_to_py)?;
        let rows = i64::try_from(self.inner.len()).unwrap_or(i64::MAX);
        let caller_keyed = self
            .inner
            .with_column(CALLER_ROW, Column::from_i64_values((0..rows).collect()))
            .map_err(frame_error_to_py)?;
        let left_on = pyo3::types::PyString::new(py, key);
        let right_on = pyo3::types::PyString::new(py, OTHER_INDEX);
        let args = MergeArgs {
            how,
            on: None,
            left_on: Some(left_on.as_any()),
            right_on: Some(right_on.as_any()),
            left_index: false,
            right_index: false,
            sort,
            suffixes: Some(suffixes.as_any()),
            indicator: None,
            validate,
        };
        let merged = merge_impl(&caller_keyed, &other_keyed, &args)?;
        let caller_labels = self.inner.index().labels();
        let labels: Vec<IndexLabel> = merged
            .column(CALLER_ROW)
            .map(|rows| {
                rows.values()
                    .iter()
                    .filter_map(|row| match row {
                        Scalar::Int64(row) => usize::try_from(*row).ok(),
                        _ => None,
                    })
                    .filter_map(|row| caller_labels.get(row).cloned())
                    .collect()
            })
            .unwrap_or_default();
        let mut frame = merged
            .drop_column(CALLER_ROW)
            .and_then(|frame| frame.drop_column(OTHER_INDEX))
            .and_then(|frame| frame.set_axis(labels, 0))
            .map_err(frame_error_to_py)?;
        if let Some(name) = self.inner.index().name() {
            frame = frame.rename_axis(name).map_err(frame_error_to_py)?;
        }
        Ok(PyDataFrame { inner: frame })
    }

    #[pyo3(signature = (copy=None))]
    fn infer_objects(&self, copy: Option<bool>) -> PyResult<PyDataFrame> {
        // copy= only lets pandas share buffers; a new frame satisfies it.
        let _ = copy;
        let df = self.inner.infer_objects().map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    /// pandas' `DataFrame.interpolate` down each column (fvsao.5: `method`
    /// and every option used to be dropped, so any call interpolated
    /// linearly).
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (method="linear", *, axis=None, limit=None, inplace=false, limit_direction=None, limit_area=None, downcast=None, **kwargs))]
    fn interpolate(
        &mut self,
        method: &str,
        axis: Option<&Bound<'_, PyAny>>,
        limit: Option<usize>,
        inplace: bool,
        limit_direction: Option<&str>,
        limit_area: Option<&str>,
        downcast: Option<&Bound<'_, PyAny>>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Option<PyDataFrame>> {
        let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        unsupported_params(
            "DataFrame.interpolate",
            &[("axis", ax == 0), ("downcast", downcast.is_none())],
        )?;
        engine_kwargs("DataFrame.interpolate", "scipy", kwargs)?;
        if !Series::interpolate_supports(method, limit_direction, limit_area) {
            return Err(not_implemented(&format!(
                "DataFrame.interpolate(method='{method}') with limit_direction or limit_area"
            )));
        }
        let df = self
            .inner
            .interpolate_with(method, limit, limit_direction, limit_area)
            .map_err(frame_error_to_py)?;
        Ok(frame_inplace(
            &mut self.inner,
            PyDataFrame { inner: df },
            inplace,
        ))
    }

    /// pandas `DataFrame.stack` over a one-level column axis: a Series under
    /// the (row label..., column) MultiIndex, row-major, with the missing
    /// cells dropped as pandas 2.2's default implementation does
    /// (`dropna=False` or `future_stack=True` keep them). An explicit
    /// `dropna=`/`sort=` warns as pandas' deprecated implementation does;
    /// `sort` never reorders a one-level column axis.
    #[pyo3(signature = (level=-1, dropna=None, sort=None, future_stack=false))]
    fn stack(
        &self,
        py: Python<'_>,
        level: i64,
        dropna: Option<bool>,
        sort: Option<bool>,
        future_stack: bool,
    ) -> PyResult<PySeries> {
        if self.inner.columns_multiindex().is_some() {
            return Err(not_implemented("stack of a MultiIndex column axis"));
        }
        if level > 0 {
            return Err(PyErr::new::<pyo3::exceptions::PyIndexError, _>(format!(
                "Too many levels: Index has only 1 level, not {}",
                i128::from(level) + 1
            )));
        }
        if level < -1 {
            return Err(PyErr::new::<pyo3::exceptions::PyIndexError, _>(format!(
                "Too many levels: Index has only 1 level, {level} is not a valid level number"
            )));
        }
        if future_stack && dropna.is_some() {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "dropna must be unspecified with future_stack=True as the new implementation does not introduce rows of NA values. This argument will be removed in a future version of pandas.",
            ));
        }
        if !future_stack && (dropna.is_some() || sort.is_some()) {
            PyErr::warn(
                py,
                &py.get_type::<pyo3::exceptions::PyFutureWarning>(),
                c"The previous implementation of stack is deprecated and will be removed in a future version of pandas. See the What's New notes for pandas 2.1.0 for details. Specify future_stack=True to adopt the new implementation and silence this warning.",
                1,
            )?;
        }
        let drop_missing = !future_stack && dropna.unwrap_or(true);
        let stacked = self.inner.stack().map_err(frame_error_to_py)?;
        let values = stacked
            .column_names()
            .first()
            .and_then(|name| stacked.column(name))
            .ok_or_else(|| not_implemented("stack of a frame without columns"))?;
        let index = self.inner.index();
        let row_multi = self.inner.row_multiindex();
        let row_levels: Vec<Vec<IndexLabel>> = match row_multi {
            Some(multi) => (0..multi.nlevels())
                .map(|lvl| {
                    multi
                        .get_level_values(lvl)
                        .map(|level| level.labels().to_vec())
                        .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))
                })
                .collect::<PyResult<_>>()?,
            None => vec![index.labels().to_vec()],
        };
        let mut names: Vec<Option<String>> = match row_multi {
            Some(multi) => multi.names().to_vec(),
            None => vec![index.name().map(str::to_owned)],
        };
        names.push(None);
        let row_labels = index.labels();
        let columns = self.inner.column_names();
        let mut arrays: Vec<Vec<IndexLabel>> = vec![Vec::new(); row_levels.len() + 1];
        let mut flat = Vec::new();
        let mut keep = Vec::new();
        for (row, row_label) in row_labels.iter().enumerate() {
            for (col, name) in columns.iter().enumerate() {
                let position = row * columns.len() + col;
                if drop_missing && !values.validity().get(position) {
                    continue;
                }
                for (array, level) in arrays.iter_mut().zip(&row_levels) {
                    array.push(level[row].clone());
                }
                arrays[row_levels.len()].push(IndexLabel::Utf8((*name).clone()));
                flat.push(IndexLabel::Utf8(format!("{row_label}|{name}")));
                keep.push(position);
            }
        }
        let levels = fp_index::MultiIndex::from_arrays(arrays)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?
            .set_names(names);
        let index = Index::new(flat)
            .with_row_multiindex(levels)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyValueError, _>(e.to_string()))?;
        let out =
            Series::new("", index, values.take_positions(&keep)).map_err(frame_error_to_py)?;
        Ok(PySeries { inner: out })
    }

    /// pandas' `DataFrame.unstack(level=-1, fill_value=None, sort=True)`
    /// over a row MultiIndex: each column unstacked as a Series (see
    /// `PySeries::unstack`), side by side under its label - pandas'
    /// (column, value) columns. It took no arguments and refused more than
    /// one column.
    #[pyo3(signature = (level=None, fill_value=None, sort=true))]
    fn unstack(
        &self,
        py: Python<'_>,
        level: Option<&Bound<'_, PyAny>>,
        fill_value: Option<&Bound<'_, PyAny>>,
        sort: bool,
    ) -> PyResult<Py<PyAny>> {
        if self.inner.row_multiindex().is_none() {
            unsupported_params(
                "DataFrame.unstack",
                &[
                    ("level", level.is_none_or(|level| level.is_none())),
                    ("fill_value", fill_value.is_none()),
                    ("sort", sort),
                ],
            )?;
            let df = self.inner.unstack().map_err(frame_error_to_py)?;
            return Ok(Py::new(py, PyDataFrame { inner: df })?.into_any());
        }
        let index = self.inner.series_index();
        let mut names = Vec::with_capacity(self.inner.num_columns());
        let mut frames = Vec::with_capacity(self.inner.num_columns());
        for position in 0..self.inner.num_columns() {
            let name = self.inner.column_name_at(position).unwrap_or_default();
            let column = self.inner.column_at(position).cloned().ok_or_else(|| {
                PyErr::new::<pyo3::exceptions::PyIndexError, _>(format!(
                    "column position {position} is out of range"
                ))
            })?;
            let series =
                Series::new(name.clone(), index.clone(), column).map_err(frame_error_to_py)?;
            let unstacked = PySeries { inner: series }.unstack(py, level, fill_value, sort)?;
            frames.push(Py::new(py, unstacked)?.into_bound(py).into_any());
            names.push(name);
        }
        concat_side_by_side(py, frames, names).map(Bound::unbind)
    }

    /// `level` a position or a level name (a name raised TypeError).
    #[pyo3(signature = (level=None))]
    fn droplevel(&self, level: Option<&Bound<'_, PyAny>>) -> PyResult<PyDataFrame> {
        let level = match (level, self.inner.row_multiindex()) {
            (Some(level), Some(multi)) => multiindex_level_position(multi, level)?,
            (Some(level), None) => level.extract::<usize>()?,
            (None, _) => 0,
        };
        let df = self
            .inner
            .droplevel_level(level)
            .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    /// Swaps the last two row levels, pandas' default; other levels and the
    /// column axis are not supported yet (they were ignored).
    #[pyo3(signature = (i=-2, j=-1, axis=0))]
    fn swaplevel(&self, i: isize, j: isize, axis: usize) -> PyResult<PyDataFrame> {
        unsupported_params(
            "DataFrame.swaplevel",
            &[("i", i == -2), ("j", j == -1), ("axis", axis == 0)],
        )?;
        Ok(PyDataFrame {
            inner: self.inner.swaplevel(),
        })
    }

    #[pyo3(signature = (indices, axis=None, **kwargs))]
    fn take(
        &self,
        indices: Vec<i64>,
        axis: Option<&Bound<'_, PyAny>>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<PyDataFrame> {
        numpy_compat_kwargs("take", kwargs)?;
        let axis = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        let df = self.inner.take(&indices, axis).map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    /// pandas' `DataFrame.explode(column, ignore_index=False)` expands
    /// list-like cells and leaves every scalar, strings included, as it is. A
    /// frankenpandas cell is always a scalar, so the rows stay as they are.
    /// This used to split strings on a `sep` keyword pandas does not have,
    /// turning "Smith, John" into two rows (fvsao.5).
    #[pyo3(signature = (column, ignore_index=false))]
    fn explode(&self, column: &Bound<'_, PyAny>, ignore_index: bool) -> PyResult<PyDataFrame> {
        let col_names = extract_col_names_flexible(Some(column))?;
        if col_names.is_empty() {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "column must be nonempty",
            ));
        }
        if let Some(missing) = col_names.iter().find(|c| self.inner.column(c).is_none()) {
            return Err(PyErr::new::<pyo3::exceptions::PyKeyError, _>(
                missing.clone(),
            ));
        }
        let out = if ignore_index {
            self.inner.reset_index(true).map_err(frame_error_to_py)?
        } else {
            self.inner.clone()
        };
        Ok(PyDataFrame { inner: out })
    }

    fn update(&mut self, other: &PyDataFrame) -> PyResult<()> {
        self.inner = self.inner.update(&other.inner).map_err(frame_error_to_py)?;
        Ok(())
    }

    /// pandas' `df.value_counts(subset=None, normalize=False, sort=True,
    /// ascending=False, dropna=True)`: the size of each group over `subset`
    /// (every column by default; a missing key is a group with
    /// dropna=False), sorted by count when `sort` (ties keep key order), as
    /// proportions with `normalize`, named 'count' / 'proportion', over a
    /// MultiIndex whenever `subset` is list-like - one level too. sort=False
    /// and dropna=False were refused and the index was flat 'x, p' text.
    #[pyo3(signature = (subset=None, normalize=false, sort=true, ascending=false, dropna=true))]
    fn value_counts<'py>(
        slf: &Bound<'py, Self>,
        subset: Option<&Bound<'py, PyAny>>,
        normalize: bool,
        sort: bool,
        ascending: bool,
        dropna: bool,
    ) -> PyResult<Bound<'py, PyAny>> {
        let py = slf.py();
        let keys = match subset.filter(|subset| !subset.is_none()) {
            Some(subset) => subset.clone(),
            None => PyList::new(py, slf.borrow().inner.column_names())?.into_any(),
        };
        let list_like = !keys.is_instance_of::<pyo3::types::PyString>() && keys.try_iter().is_ok();
        let groupby_kwargs = PyDict::new(py);
        groupby_kwargs.set_item("dropna", dropna)?;
        groupby_kwargs.set_item("observed", false)?;
        let mut counts = slf
            .call_method("groupby", (keys,), Some(&groupby_kwargs))?
            .call_method0("size")?;
        if sort {
            let sort_kwargs = PyDict::new(py);
            sort_kwargs.set_item("ascending", ascending)?;
            sort_kwargs.set_item("kind", "stable")?;
            counts = counts.call_method("sort_values", (), Some(&sort_kwargs))?;
        }
        if normalize {
            let total = counts.call_method0("sum")?;
            counts = counts.call_method1("__truediv__", (total,))?;
        }
        let counts = counts.extract::<PyRef<'_, PySeries>>()?.inner.clone();
        let mut index = counts.index().clone();
        if list_like && index.row_multiindex().is_none() {
            let levels = fp_index::MultiIndex::from_arrays(vec![index.labels().to_vec()])
                .map_err(index_error_to_py)?
                .set_names(vec![index.name().map(str::to_owned)]);
            index = index
                .with_row_multiindex(levels)
                .map_err(index_error_to_py)?;
        }
        let name = if normalize { "proportion" } else { "count" };
        PySeries {
            inner: Series::new(name, index, counts.column().clone()).map_err(frame_error_to_py)?,
        }
        .into_bound_py_any(py)
    }

    #[pyo3(signature = (axis=None, dropna=true))]
    fn nunique(&self, axis: Option<&Bound<'_, PyAny>>, dropna: bool) -> PyResult<PySeries> {
        let ax = parse_axis_param(axis)?;
        let s = self
            .inner
            .nunique_axis_with_dropna(ax, dropna)
            .map_err(frame_error_to_py)?;
        Ok(PySeries { inner: s })
    }

    /// pandas' `DataFrame.xs` on the row index. The row comes back as a
    /// one-row frame, pandas' drop_level=False shape, whatever drop_level
    /// says (the Series return is fvsao.7's).
    #[pyo3(signature = (key, axis=None, level=None, drop_level=true))]
    fn xs(
        &self,
        key: &Bound<'_, PyAny>,
        axis: Option<&Bound<'_, PyAny>>,
        level: Option<&Bound<'_, PyAny>>,
        drop_level: bool,
    ) -> PyResult<PyDataFrame> {
        let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        // xs(key, level=) over a row MultiIndex: the rows whose `level` is
        // `key`, that level dropped unless drop_level=False (fvsao.36; it
        // raised NotImplementedError).
        if ax == 0
            && let Some(level) = level.filter(|level| !level.is_none())
            && let Some(multi) = self.inner.row_multiindex()
        {
            let position = multiindex_level_position(multi, level)?;
            let label = py_to_index_label(key)?;
            let values = multi
                .get_level_values(position)
                .map_err(index_error_to_py)?;
            let rows: Vec<usize> = values
                .labels()
                .iter()
                .enumerate()
                .filter(|(_, value)| **value == label)
                .map(|(row, _)| row)
                .collect();
            if rows.is_empty() {
                return Err(PyErr::new::<pyo3::exceptions::PyKeyError, _>(format!(
                    "{}",
                    key.repr()?
                )));
            }
            if !drop_level {
                let inner = frame_rows_keeping_multiindex(&self.inner, multi, &rows)?;
                return Ok(PyDataFrame { inner });
            }
            let keep: Vec<usize> = (0..multi.nlevels()).filter(|&l| l != position).collect();
            let (index, rest) = multiindex_levels_index(multi, &rows, &keep)?;
            let positions: Vec<i64> = rows.iter().map(|&row| row as i64).collect();
            let mut inner = self
                .inner
                .take(&positions, 0)
                .and_then(|taken| taken.with_index(index))
                .map_err(frame_error_to_py)?;
            if let Some(rest) = rest {
                inner = inner.with_row_multiindex(rest).map_err(frame_error_to_py)?;
            }
            return Ok(PyDataFrame { inner });
        }
        unsupported_params(
            "DataFrame.xs",
            &[("axis", ax == 0), ("level", level.is_none())],
        )?;
        let lbl = py_to_index_label(key)?;
        let df = self.inner.xs(&lbl).map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    /// pandas' `DataFrame.rename_axis` for the row index (`mapper` or
    /// `index`); naming the columns axis is not supported yet.
    #[pyo3(signature = (mapper=None, *, index=None, columns=None, axis=None, copy=None, inplace=false))]
    fn rename_axis(
        &self,
        mapper: Option<&Bound<'_, PyAny>>,
        index: Option<&Bound<'_, PyAny>>,
        columns: Option<&Bound<'_, PyAny>>,
        axis: Option<&Bound<'_, PyAny>>,
        copy: Option<bool>,
        inplace: bool,
    ) -> PyResult<PyDataFrame> {
        // copy= only lets pandas share buffers; a new frame satisfies it.
        let _ = copy;
        let ax = parse_axis_param_for_type(axis, "DataFrame")?.unwrap_or(0);
        unsupported_params(
            "DataFrame.rename_axis",
            &[
                ("columns", columns.is_none()),
                ("axis", ax == 0),
                ("inplace", !inplace),
            ],
        )?;
        let df = match self.inner.row_multiindex() {
            // A list names each level; index= as a dict / function maps them.
            Some(levels) => {
                let names = rename_axis_names(levels.names(), mapper, index)?;
                self.inner
                    .clone()
                    .with_row_multiindex(levels.clone().set_names(names))
            }
            None => {
                let current = [self.inner.index().name().map(str::to_owned)];
                let names = rename_axis_names(&current, mapper, index)?;
                self.inner
                    .rename_axis(names.into_iter().next().flatten().as_deref().unwrap_or(""))
            }
        }
        .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    #[pyo3(signature = (labels, *, axis=None, copy=None))]
    fn set_axis(
        &self,
        labels: &Bound<'_, PyAny>,
        axis: Option<&Bound<'_, PyAny>>,
        copy: Option<bool>,
    ) -> PyResult<PyDataFrame> {
        // copy= only lets pandas share buffers; a new frame satisfies it.
        let _ = copy;
        let axis_idx = match axis {
            None => 0,
            Some(a) => {
                if let Ok(i) = a.extract::<i64>() {
                    match i {
                        0 => 0,
                        1 => 1,
                        other => {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                                "No axis named {other} for object type DataFrame"
                            )));
                        }
                    }
                } else if let Ok(s) = a.extract::<String>() {
                    match s.as_str() {
                        "index" | "rows" => 0,
                        "columns" => 1,
                        other => {
                            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                                "No axis named {other} for object type DataFrame"
                            )));
                        }
                    }
                } else {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                        "axis must be 0, 1, 'index', or 'columns'",
                    ));
                }
            }
        };
        // A DatetimeIndex (tz-aware ones keep their zone) as the row axis;
        // it raised TypeError.
        if let Ok(dti) = labels.extract::<PyRef<'_, PyDatetimeIndex>>()
            && axis_idx == 0
        {
            let inner = self
                .inner
                .with_index(dti.inner.as_index().clone())
                .map_err(axis_length_error_to_py)?;
            return Ok(PyDataFrame { inner });
        }
        let lbls = if let Ok(py_idx) = labels.extract::<PyRef<'_, PyIndex>>() {
            py_idx.inner.labels().to_vec()
        } else if let Ok(list) = labels.cast::<PyList>() {
            let mut v = Vec::with_capacity(list.len());
            for item in list.iter() {
                v.push(py_to_index_label(&item)?);
            }
            v
        } else {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "set_axis expects Index or list of labels",
            ));
        };
        let df = self
            .inner
            .set_axis(lbls, axis_idx)
            .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: df })
    }

    fn divmod(
        &self,
        py: Python<'_>,
        other: &Bound<'_, PyAny>,
    ) -> PyResult<(PyDataFrame, PyDataFrame)> {
        let q = self.floordiv(py, other, None, None, None)?;
        let r = self.r#mod(py, other, None, None, None)?;
        Ok((q, r))
    }

    fn rdivmod(
        &self,
        py: Python<'_>,
        other: &Bound<'_, PyAny>,
    ) -> PyResult<(PyDataFrame, PyDataFrame)> {
        let q = self.rfloordiv(py, other, None, None, None)?;
        let r = self.rmod(py, other, None, None, None)?;
        Ok((q, r))
    }

