/// Python wrapper for SparseAccessor over Series or DataFrame.
#[pyclass(name = "SparseAccessor", from_py_object)]
#[derive(Clone)]
pub struct PySparseAccessor {
    series: Option<Series>,
    df: Option<DataFrame>,
}

#[pymethods]
impl PySparseAccessor {
    #[getter]
    fn density(&self) -> f64 {
        1.0
    }

    #[getter]
    fn npoints(&self) -> usize {
        if let Some(ref s) = self.series {
            s.len()
        } else if let Some(ref d) = self.df {
            d.len() * d.num_columns()
        } else {
            0
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn execute_window_bivariate<F, G>(
    py: Python<'_>,
    series: Option<&Series>,
    dataframe: Option<&DataFrame>,
    other: Option<&Bound<'_, PyAny>>,
    op: F,
    df_none_pairwise: Option<G>,
    err_msg_empty: &'static str,
    err_msg_df_none: &'static str,
) -> PyResult<Py<PyAny>>
where
    F: Fn(&Series, &Series) -> Result<Series, FrameError>,
    G: Fn(&DataFrame) -> Result<DataFrame, FrameError>,
{
    let (other_series, other_df) = match other {
        Some(o) if !o.is_none() => {
            if let Ok(s) = o.extract::<PyRef<'_, PySeries>>() {
                (Some(s), None)
            } else if let Ok(df) = o.extract::<PyRef<'_, PyDataFrame>>() {
                (None, Some(df))
            } else {
                return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                    "other must be a Series or DataFrame",
                ));
            }
        }
        _ => (None, None),
    };

    if let Some(s) = series {
        if let Some(ref o) = other_series {
            let res = op(s, &o.inner).map_err(frame_error_to_py)?;
            // pandas keeps the name only when both Series share it.
            let res = if s.name() == o.inner.name() {
                res
            } else {
                res.rename("").map_err(frame_error_to_py)?
            };
            return Ok(Py::new(py, PySeries { inner: res })?.into_any());
        } else if let Some(ref o_df) = other_df {
            let mut out_series_list = Vec::new();
            for col_name in o_df.inner.column_names() {
                let Some(col) = o_df.inner.column(col_name) else {
                    continue;
                };
                if col.dtype() != DType::Int64 && col.dtype() != DType::Float64 {
                    continue;
                }
                let col_s = Series::new(col_name.as_str(), o_df.inner.index().clone(), col.clone())
                    .map_err(frame_error_to_py)?;
                let mut res = op(s, &col_s).map_err(frame_error_to_py)?;
                if res.index() != o_df.inner.index() {
                    res = res
                        .reindex(o_df.inner.index().labels().to_vec())
                        .map_err(frame_error_to_py)?;
                }
                let res = Series::new(col_name.as_str(), res.index().clone(), res.column().clone())
                    .map_err(frame_error_to_py)?;
                out_series_list.push(res);
            }
            let res_df = if out_series_list.is_empty() {
                DataFrame::new(o_df.inner.index().clone(), BTreeMap::new())
                    .map_err(frame_error_to_py)?
            } else {
                DataFrame::from_series(out_series_list).map_err(frame_error_to_py)?
            };
            return Ok(Py::new(py, PyDataFrame { inner: res_df })?.into_any());
        } else {
            let res = op(s, s).map_err(frame_error_to_py)?;
            return Ok(Py::new(py, PySeries { inner: res })?.into_any());
        }
    }

    if let Some(df) = dataframe {
        if let Some(ref o) = other_series {
            let mut out_series_list = Vec::new();
            for col_name in df.column_names() {
                let Some(col) = df.column(col_name) else {
                    continue;
                };
                if col.dtype() != DType::Int64 && col.dtype() != DType::Float64 {
                    continue;
                }
                let s1 = Series::new(col_name.as_str(), df.index().clone(), col.clone())
                    .map_err(frame_error_to_py)?;
                let mut res = op(&s1, &o.inner).map_err(frame_error_to_py)?;
                if res.index() != df.index() {
                    res = res
                        .reindex(df.index().labels().to_vec())
                        .map_err(frame_error_to_py)?;
                }
                let res = Series::new(col_name.as_str(), res.index().clone(), res.column().clone())
                    .map_err(frame_error_to_py)?;
                out_series_list.push(res);
            }
            let res_df = if out_series_list.is_empty() {
                DataFrame::new(df.index().clone(), BTreeMap::new()).map_err(frame_error_to_py)?
            } else {
                DataFrame::from_series(out_series_list).map_err(frame_error_to_py)?
            };
            return Ok(Py::new(py, PyDataFrame { inner: res_df })?.into_any());
        } else if let Some(ref o_df) = other_df {
            let (a1, a2) = df
                .align_on_index(&o_df.inner, AlignMode::Outer)
                .map_err(frame_error_to_py)?;
            let mut out_series_list = Vec::new();
            for col_name in a1.column_names() {
                let Some(c1) = a1.column(col_name) else {
                    continue;
                };
                let Some(c2) = a2.column(col_name) else {
                    continue;
                };
                if (c1.dtype() == DType::Int64 || c1.dtype() == DType::Float64)
                    && (c2.dtype() == DType::Int64 || c2.dtype() == DType::Float64)
                {
                    let s1 = Series::new(col_name.as_str(), a1.index().clone(), c1.clone())
                        .map_err(frame_error_to_py)?;
                    let s2 = Series::new(col_name.as_str(), a2.index().clone(), c2.clone())
                        .map_err(frame_error_to_py)?;
                    let res = op(&s1, &s2).map_err(frame_error_to_py)?;
                    let res =
                        Series::new(col_name.as_str(), res.index().clone(), res.column().clone())
                            .map_err(frame_error_to_py)?;
                    out_series_list.push(res);
                }
            }
            let res_df = if out_series_list.is_empty() {
                DataFrame::new(a1.index().clone(), BTreeMap::new()).map_err(frame_error_to_py)?
            } else {
                DataFrame::from_series(out_series_list).map_err(frame_error_to_py)?
            };
            return Ok(Py::new(py, PyDataFrame { inner: res_df })?.into_any());
        } else if let Some(pairwise) = df_none_pairwise {
            let res = pairwise(df).map_err(frame_error_to_py)?;
            return Ok(Py::new(py, PyDataFrame { inner: res })?.into_any());
        } else {
            return Err(PyErr::new::<pyo3::exceptions::PyNotImplementedError, _>(
                err_msg_df_none,
            ));
        }
    }

    Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
        err_msg_empty,
    ))
}

/// A frame window's `agg([...])` with pandas' (column, function) column
/// MultiIndex; fp-frame names each column `{column}_{function}`, column by
/// column in `funcs` order.
fn func_columns(frame: DataFrame, funcs: &[&str]) -> PyResult<DataFrame> {
    if funcs.is_empty() {
        return Ok(frame);
    }
    let mut columns = Vec::new();
    let mut functions = Vec::new();
    for (position, name) in frame.column_names().into_iter().enumerate() {
        let func = funcs[position % funcs.len()];
        let column = name
            .strip_suffix(func)
            .and_then(|rest| rest.strip_suffix('_'))
            .unwrap_or(name);
        columns.push(IndexLabel::Utf8(column.to_owned()));
        functions.push(IndexLabel::Utf8(func.to_owned()));
    }
    let multi =
        fp_index::MultiIndex::from_arrays(vec![columns, functions]).map_err(index_error_to_py)?;
    frame
        .with_columns_multiindex(Some(multi))
        .map_err(frame_error_to_py)
}

/// Python wrapper for rolling window calculations over Series or DataFrame.
#[pyclass(name = "Rolling")]
pub struct PyRolling {
    series: Option<Series>,
    dataframe: Option<DataFrame>,
    window: usize,
    min_periods: Option<usize>,
    center: bool,
    /// A time-based window ('7D', '2h', or a tick offset's freqstr) in
    /// place of the row count, over a datetime index.
    offset: Option<String>,
}

impl PyRolling {
    /// The Series window: `(t - offset, t]` over the datetime index for a
    /// time-based window (min_periods defaulting to 1, as pandas), else
    /// `window` rows.
    fn series_window<'a>(&self, s: &'a Series) -> PyResult<fp_frame::Rolling<'a>> {
        match &self.offset {
            Some(offset) => {
                if self.center {
                    return Err(not_implemented("rolling(<time window>, center=True)"));
                }
                // pandas' own error for a time window over a non-datetime index.
                if !s.index().labels().iter().all(|label| {
                    matches!(
                        label,
                        IndexLabel::Datetime64(_) | IndexLabel::Timedelta64(_)
                    )
                }) {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                        "window must be an integer 0 or greater",
                    ));
                }
                s.rolling_offset(offset, self.min_periods)
                    .map_err(frame_error_to_py)
            }
            None => Ok(s.rolling_with_center(self.window, self.min_periods, self.center)),
        }
    }

    /// `apply(func)` over `s`'s count windows (centred when `center`):
    /// `func` gets every window, NaN rows included, that holds at least
    /// `min_periods` non-missing values; the others are NaN (pandas).
    fn apply_windows(
        &self,
        py: Python<'_>,
        s: &Series,
        func: &Bound<'_, PyAny>,
        raw: bool,
        args: Option<&Bound<'_, PyTuple>>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Series> {
        let windows = s.rolling_with_center(self.window, self.min_periods, self.center);
        let min_periods = self.min_periods.unwrap_or(self.window);
        let values = s.column().values();
        let labels = s.index().labels();
        let mut out = Vec::with_capacity(values.len());
        for i in 0..values.len() {
            let (start, end) = windows.window_bounds(i, values.len());
            let window = &values[start..end];
            if window.iter().filter(|v| !v.is_missing()).count() < min_periods {
                out.push(Scalar::Float64(f64::NAN));
            } else {
                let arg = window_arg(py, window, &labels[start..end], s.name(), raw)?;
                out.push(py_to_scalar(
                    py,
                    &call_window_func(func, arg, args, kwargs)?,
                )?);
            }
        }
        Series::from_values(s.name(), labels.to_vec(), out).map_err(frame_error_to_py)
    }

    /// Refuses a time-based window where `method` only runs count windows
    /// (it would have run a 0-row window).
    fn require_count_window(&self, method: &str) -> PyResult<()> {
        match self.offset {
            Some(_) => Err(not_implemented(&format!(
                "Rolling.{method} over a time-based window"
            ))),
            None => Ok(()),
        }
    }
}

/// A `rolling(window)` argument: a row count, or a time-based window as a
/// string ('7D') or a fixed offset (Day(7)).
fn rolling_window_arg(window: &Bound<'_, PyAny>) -> PyResult<(usize, Option<String>)> {
    if let Ok(count) = window.extract::<usize>() {
        return Ok((count, None));
    }
    if let Ok(offset) = window.extract::<PyRef<'_, PyDateOffset>>() {
        return Ok((0, Some(offset.freqstr())));
    }
    match window.extract::<String>() {
        Ok(text) => Ok((0, Some(text))),
        Err(_) => Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
            "window must be an integer 0 or greater",
        )),
    }
}

