    /// pandas' `DataFrameGroupBy.agg`: a function name, a {column: func}
    /// dict, or named aggregation `agg(out=('col', 'func'), ...)`, which
    /// fp-frame's `agg_named` implements (it used to raise, since `func` was
    /// required). Extra arguments for the function are not supported.
    #[pyo3(signature = (func=None, *args, **kwargs))]
    fn agg(
        &self,
        py: Python<'_>,
        func: Option<&Bound<'_, PyAny>>,
        args: &Bound<'_, PyTuple>,
        kwargs: Option<&Bound<'_, PyDict>>,
    ) -> PyResult<Py<PyAny>> {
        // Callables (fvsao.7): a `_cython_table` one runs as its name, as
        // pandas'; any other (a lambda) runs per group, column by column.
        let given = func.filter(|f| !f.is_none());
        // observed=False's unused categories: column by column, each
        // function adding their rows (the frame-level paths do not).
        if !self.unused.is_empty() {
            return self.agg_per_group(py, given, args, kwargs);
        }
        let renamed_func = match given {
            Some(spec) if agg_spec_has_callable(spec) => {
                match named_agg_spec(spec, "DataFrameGroupBy")? {
                    Some(named) => Some(named),
                    None => return self.agg_per_group(py, given, args, kwargs),
                }
            }
            _ => None,
        };
        let renamed_kwargs = match (given, kwargs.filter(|k| !k.is_empty())) {
            (None, Some(named)) if agg_spec_has_callable(named.as_any()) => {
                match named_agg_spec(named.as_any(), "DataFrameGroupBy")? {
                    Some(renamed) => Some(renamed.cast_into::<PyDict>()?),
                    None => return self.agg_per_group(py, None, args, kwargs),
                }
            }
            _ => None,
        };
        let func = renamed_func.as_ref().or(func);
        let kwargs = renamed_kwargs.as_ref().or(kwargs);
        let named = kwargs.filter(|k| !k.is_empty());
        if !args.is_empty() || (func.is_some() && named.is_some()) {
            return Err(not_implemented(
                "DataFrameGroupBy.agg with arguments for the function",
            ));
        }
        let Some(func) = func.filter(|f| !f.is_none()) else {
            let missing = || {
                PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                    "Must provide 'func' or tuples of '(column, aggfunc).",
                )
            };
            let named = named.ok_or_else(missing)?;
            let mut specs = Vec::with_capacity(named.len());
            for (out, spec) in named.iter() {
                let (column, function): (String, String) = spec.extract().map_err(|_| missing())?;
                specs.push((out.extract::<String>()?, column, function));
            }
            let spec_refs: Vec<(&str, &str, &str)> = specs
                .iter()
                .map(|(out, column, function)| (out.as_str(), column.as_str(), function.as_str()))
                .collect();
            let res = self
                .grouped()
                .map_err(frame_error_to_py)?
                .agg_named(&spec_refs)
                .map_err(frame_error_to_py)?;
            return Ok(Py::new(py, PyDataFrame { inner: res })?.into_any());
        };
        if let Ok(name) = func.extract::<String>() {
            let res = match name.as_str() {
                "sum" => self.sum(false, 0, None, None)?,
                "mean" => self.mean(false, None, None)?,
                "count" => self.count()?,
                "min" => self.min(false, -1, None, None)?,
                "max" => self.max(false, -1, None, None)?,
                "var" => self.var(1, None, None, false)?,
                "std" => self.std(1, None, None, false)?,
                "sem" => self.sem(1, false)?,
                "median" => self.median(false)?,
                "prod" => self.prod(false, 0)?,
                "first" => self.first(false, -1, true)?,
                "last" => self.last(false, -1, true)?,
                "nunique" => self.nunique()?,
                "any" => self.any()?,
                "all" => self.all()?,
                "cumsum" => self.cumsum()?,
                "cumprod" => self.cumprod()?,
                "cummin" => self.cummin()?,
                "cummax" => self.cummax()?,
                "ohlc" => self.ohlc()?,
                _ => {
                    return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                        "unsupported groupby aggregation '{name}'"
                    )));
                }
            };
            return Ok(Py::new(py, res)?.into_any());
        }
        let unsupported = || {
            PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "agg expects a function name, a list of them, or a dict of column -> name(s)",
            )
        };
        // Every function over every value column (a list), or the dict's
        // own (column, functions) in the order it asks - pandas' order, not
        // the frame's; a list anywhere gives the two-level (column, func)
        // column axis.
        let (specs, two_level) = if let Ok(dict) = func.cast::<PyDict>() {
            let mut specs = Vec::with_capacity(dict.len());
            let mut two_level = false;
            for (column, funcs) in dict.iter() {
                let funcs = match funcs.extract::<String>() {
                    Ok(name) => vec![name],
                    Err(_) => {
                        two_level = true;
                        funcs.extract::<Vec<String>>().map_err(|_| unsupported())?
                    }
                };
                specs.push((column.extract::<String>()?, funcs));
            }
            (specs, two_level)
        } else {
            let funcs = func.extract::<Vec<String>>().map_err(|_| unsupported())?;
            let specs = self
                .df
                .column_names()
                .into_iter()
                .filter(|column| !self.by.contains(*column))
                .map(|column| (column.clone(), funcs.clone()))
                .collect();
            (specs, true)
        };
        let missing: Vec<String> = specs
            .iter()
            .filter(|(column, _)| self.df.column(column).is_none())
            .map(|(column, _)| format!("'{column}'"))
            .collect();
        if !missing.is_empty() {
            return Err(PyErr::new::<pyo3::exceptions::PyKeyError, _>(format!(
                "Column(s) [{}] do not exist",
                missing.join(", ")
            )));
        }
        let grouped = self.grouped().map_err(frame_error_to_py)?;
        let res = if two_level {
            grouped.agg_dict_list(&specs)
        } else {
            let requested: Vec<&str> = specs.iter().map(|(column, _)| column.as_str()).collect();
            let map = specs
                .iter()
                .map(|(column, funcs)| (column.clone(), funcs[0].clone()))
                .collect();
            grouped.agg(&map).and_then(|res| {
                let order: Vec<&str> = res
                    .column_names()
                    .into_iter()
                    .map(String::as_str)
                    .filter(|column| !requested.contains(column))
                    .chain(requested.iter().copied())
                    .collect();
                res.select_columns(&order)
            })
        }
        .map_err(frame_error_to_py)?;
        Ok(Py::new(py, PyDataFrame { inner: res })?.into_any())
    }

