    fn fillna(&self, py: Python<'_>, value: &Bound<'_, PyAny>) -> PyResult<PyDataFrame> {
        let sc = py_to_scalar(py, value)?;
        let res = self
            .grouped()
            .map_err(frame_error_to_py)?
            .fillna(&sc)
            .map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: res })
    }

    #[pyo3(signature = (func, dropna=true))]
    fn filter(&self, func: &Bound<'_, PyAny>, dropna: Option<bool>) -> PyResult<PyDataFrame> {
        unsupported_params(
            "DataFrameGroupBy.filter",
            &[("dropna", dropna != Some(false))],
        )?;
        // The kept groups' rows in their original order, as pandas' filter
        // (it concatenated the kept groups in key order; fvsao.30).
        let mut kept: Vec<usize> = Vec::new();
        for (_, positions) in self.ordered_groups(false)? {
            let group_df = self.df.take_rows(&positions).map_err(frame_error_to_py)?;
            let res = func.call1((PyDataFrame { inner: group_df },))?;
            if res.is_truthy()? {
                kept.extend(positions);
            }
        }
        kept.sort_unstable();
        let rows = self.df.take_rows(&kept).map_err(frame_error_to_py)?;
        Ok(PyDataFrame { inner: rows })
    }

    #[getter]
    fn grouper(&self) -> Vec<String> {
        self.by.clone()
    }

    #[getter]
    fn keys(&self, py: Python<'_>) -> PyResult<Py<PyAny>> {
        if self.by.len() == 1 {
            Ok(pyo3::types::PyString::new(py, &self.by[0])
                .into_any()
                .unbind())
        } else {
            let list = PyList::new(py, &self.by)?;
            Ok(list.into_any().unbind())
        }
    }

