#[pyclass(name = "Interval", from_py_object)]
#[derive(Clone, Debug, PartialEq)]
pub struct PyInterval {
    #[pyo3(get)]
    pub left: f64,
    #[pyo3(get)]
    pub right: f64,
    #[pyo3(get)]
    pub closed: String,
}

#[pymethods]
impl PyInterval {
    #[new]
    #[pyo3(signature = (left, right, closed="right"))]
    fn new(left: f64, right: f64, closed: Option<&str>) -> PyResult<Self> {
        let closed_str = closed.unwrap_or("right");
        if !["right", "left", "both", "neither"].contains(&closed_str) {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "closed must be one of 'right', 'left', 'both', 'neither'",
            ));
        }
        Ok(Self {
            left,
            right,
            closed: closed_str.to_string(),
        })
    }

    #[getter]
    fn length(&self) -> f64 {
        self.right - self.left
    }

    #[getter]
    fn mid(&self) -> f64 {
        (self.left + self.right) / 2.0
    }

    /// Whether the left end is closed ('left' / 'both').
    #[getter]
    fn closed_left(&self) -> bool {
        matches!(self.closed.as_str(), "left" | "both")
    }

    /// Whether the right end is closed ('right' / 'both').
    #[getter]
    fn closed_right(&self) -> bool {
        matches!(self.closed.as_str(), "right" | "both")
    }

    #[getter]
    fn open_left(&self) -> bool {
        !self.closed_left()
    }

    #[getter]
    fn open_right(&self) -> bool {
        !self.closed_right()
    }

    /// pandas' `Interval.overlaps`: the two share a point - touching ends
    /// count only when both are closed there (it raised AttributeError).
    fn overlaps(&self, other: &Bound<'_, PyAny>) -> PyResult<bool> {
        let other = other.extract::<PyRef<'_, Self>>().map_err(|_| {
            PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
                "`other` must be an Interval, got {}",
                other
                    .get_type()
                    .name()
                    .map_or_else(|_| "object".to_owned(), |n| n.to_string())
            ))
        })?;
        let before = |a: f64, b: f64, closed: bool| if closed { a <= b } else { a < b };
        Ok(before(
            self.left,
            other.right,
            self.closed_left() && other.closed_right(),
        ) && before(
            other.left,
            self.right,
            other.closed_left() && self.closed_right(),
        ))
    }

    /// Equal ends and closed side, as pandas' Interval (it compared by
    /// identity).
    fn __eq__(&self, other: &Bound<'_, PyAny>) -> bool {
        other.extract::<PyRef<'_, Self>>().is_ok_and(|other| {
            other.left == self.left && other.right == self.right && other.closed == self.closed
        })
    }

    fn __hash__(&self) -> u64 {
        use std::hash::{Hash, Hasher};
        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        self.left.to_bits().hash(&mut hasher);
        self.right.to_bits().hash(&mut hasher);
        self.closed.hash(&mut hasher);
        hasher.finish()
    }

    fn __contains__(&self, val: f64) -> bool {
        match self.closed.as_str() {
            "right" => val > self.left && val <= self.right,
            "left" => val >= self.left && val < self.right,
            "both" => val >= self.left && val <= self.right,
            "neither" => val > self.left && val < self.right,
            _ => false,
        }
    }

    fn __repr__(&self) -> String {
        format!(
            "Interval({}, {}, closed='{}')",
            self.left, self.right, self.closed
        )
    }

    fn __str__(&self) -> String {
        let (l_bracket, r_bracket) = match self.closed.as_str() {
            "right" => ('(', ']'),
            "left" => ('[', ')'),
            "both" => ('[', ']'),
            _ => ('(', ')'),
        };
        format!("{}{}, {}{}", l_bracket, self.left, self.right, r_bracket)
    }
}

#[pyclass(name = "IntervalIndex", from_py_object)]
#[derive(Clone, Debug)]
pub struct PyIntervalIndex {
    pub intervals: Vec<PyInterval>,
    pub name: Option<String>,
}

#[pymethods]
impl PyIntervalIndex {
    #[new]
    #[pyo3(signature = (data=None, name=None))]
    fn new(data: Option<&Bound<'_, PyAny>>, name: Option<&str>) -> PyResult<Self> {
        let mut intervals = Vec::new();
        if let Some(d) = data {
            if let Ok(list) = d.extract::<Vec<PyInterval>>() {
                intervals = list;
            } else if let Ok(seq) = d.cast::<pyo3::types::PySequence>() {
                let len = seq.len()?;
                for i in 0..len {
                    let item = seq.get_item(i)?;
                    if let Ok(iv) = item.extract::<PyInterval>() {
                        intervals.push(iv);
                    }
                }
            }
        }
        Ok(Self {
            intervals,
            name: name.map(str::to_string),
        })
    }

    #[classmethod]
    #[pyo3(signature = (breaks, closed="right", name=None))]
    fn from_breaks(
        _cls: &Bound<'_, pyo3::types::PyType>,
        breaks: Vec<f64>,
        closed: Option<&str>,
        name: Option<&str>,
    ) -> PyResult<Self> {
        let closed_str = closed.unwrap_or("right");
        if breaks.len() < 2 {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "breaks must have at least 2 elements",
            ));
        }
        let mut intervals = Vec::with_capacity(breaks.len() - 1);
        for i in 0..(breaks.len() - 1) {
            intervals.push(PyInterval::new(breaks[i], breaks[i + 1], Some(closed_str))?);
        }
        Ok(Self {
            intervals,
            name: name.map(str::to_string),
        })
    }

    #[classmethod]
    #[pyo3(signature = (data, closed="right", name=None))]
    fn from_tuples(
        _cls: &Bound<'_, pyo3::types::PyType>,
        data: Vec<(f64, f64)>,
        closed: Option<&str>,
        name: Option<&str>,
    ) -> PyResult<Self> {
        let closed_str = closed.unwrap_or("right");
        let mut intervals = Vec::with_capacity(data.len());
        for (left, right) in data {
            intervals.push(PyInterval::new(left, right, Some(closed_str))?);
        }
        Ok(Self {
            intervals,
            name: name.map(str::to_string),
        })
    }

    #[classmethod]
    #[pyo3(signature = (left, right, closed="right", name=None))]
    fn from_arrays(
        _cls: &Bound<'_, pyo3::types::PyType>,
        left: Vec<f64>,
        right: Vec<f64>,
        closed: Option<&str>,
        name: Option<&str>,
    ) -> PyResult<Self> {
        let closed_str = closed.unwrap_or("right");
        if left.len() != right.len() {
            return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(
                "left and right arrays must have equal length",
            ));
        }
        let mut intervals = Vec::with_capacity(left.len());
        for (l, r) in left.into_iter().zip(right) {
            intervals.push(PyInterval::new(l, r, Some(closed_str))?);
        }
        Ok(Self {
            intervals,
            name: name.map(str::to_string),
        })
    }

    #[getter]
    fn name(&self) -> Option<String> {
        self.name.clone()
    }

    #[getter]
    fn length(&self) -> usize {
        self.intervals.len()
    }

    fn __len__(&self) -> usize {
        self.intervals.len()
    }

    fn __getitem__(&self, idx: isize) -> PyResult<PyInterval> {
        let len = self.intervals.len() as isize;
        let pos = if idx < 0 { idx + len } else { idx };
        if pos < 0 || pos >= len {
            return Err(PyErr::new::<pyo3::exceptions::PyIndexError, _>(
                "index out of range",
            ));
        }
        Ok(self.intervals[pos as usize].clone())
    }

    fn __repr__(&self) -> String {
        format!("IntervalIndex({:?})", self.intervals)
    }

    #[getter]
    fn closed(&self) -> String {
        self.intervals
            .first()
            .map_or("right", |iv| iv.closed.as_str())
            .to_string()
    }

    #[getter]
    fn closed_left(&self) -> bool {
        self.to_rust().closed_left()
    }

    #[getter]
    fn closed_right(&self) -> bool {
        self.to_rust().closed_right()
    }

    #[getter]
    fn open_left(&self) -> bool {
        self.to_rust().open_left()
    }

    #[getter]
    fn open_right(&self) -> bool {
        self.to_rust().open_right()
    }

    #[getter]
    fn is_non_overlapping_monotonic(&self) -> bool {
        self.to_rust().is_non_overlapping_monotonic()
    }

    #[getter]
    fn dtype(&self) -> String {
        self.to_rust().dtype()
    }

    #[getter]
    fn is_unique(&self) -> bool {
        self.to_rust().is_unique()
    }

    #[getter]
    fn is_monotonic_increasing(&self) -> bool {
        self.to_rust().is_monotonic_increasing()
    }

    #[getter]
    fn is_monotonic_decreasing(&self) -> bool {
        self.to_rust().is_monotonic_decreasing()
    }

    #[getter]
    fn left(&self) -> PyIndex {
        let labels = self
            .intervals
            .iter()
            .map(|iv| IndexLabel::Float64(fp_index::OrderedF64(iv.left)))
            .collect();
        PyIndex {
            inner: Index::new(labels),
        }
    }

    #[getter]
    fn right(&self) -> PyIndex {
        let labels = self
            .intervals
            .iter()
            .map(|iv| IndexLabel::Float64(fp_index::OrderedF64(iv.right)))
            .collect();
        PyIndex {
            inner: Index::new(labels),
        }
    }

    #[getter]
    fn mid(&self) -> PyIndex {
        let labels = self
            .intervals
            .iter()
            .map(|iv| IndexLabel::Float64(fp_index::OrderedF64(iv.mid())))
            .collect();
        PyIndex {
            inner: Index::new(labels),
        }
    }

    #[getter]
    fn is_overlapping(&self) -> bool {
        self.to_rust().is_overlapping()
    }

    fn contains(&self, point: f64) -> Vec<bool> {
        self.to_rust().contains(point)
    }

    fn get_loc(&self, point: f64) -> PyResult<usize> {
        self.to_rust()
            .get_loc(point)
            .map_err(|e| PyErr::new::<pyo3::exceptions::PyKeyError, _>(e.to_string()))
    }

    #[pyo3(signature = (target))]
    fn get_indexer(&self, target: &Bound<'_, PyAny>) -> PyResult<Vec<i64>> {
        let rust_idx = self.to_rust();
        let points: Vec<f64> = if let Ok(v) = target.extract::<Vec<f64>>() {
            v
        } else if let Ok(seq) = target.cast::<pyo3::types::PySequence>() {
            let len = seq.len()?;
            let mut pts = Vec::with_capacity(len);
            for i in 0..len {
                pts.push(seq.get_item(i)?.extract::<f64>()?);
            }
            pts
        } else {
            return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
                "target must be a sequence of floats",
            ));
        };
        Ok(rust_idx
            .get_indexer(&points)
            .into_iter()
            .map(|opt| opt.map_or(-1, |u| u as i64))
            .collect())
    }

    fn get_indexer_for(&self, target: &Bound<'_, PyAny>) -> PyResult<Vec<i64>> {
        self.get_indexer(target)
    }

    fn to_tuples(&self) -> Vec<(f64, f64)> {
        self.to_rust().to_tuples()
    }

    fn to_list(&self) -> Vec<PyInterval> {
        self.intervals.clone()
    }

    fn tolist(&self) -> Vec<PyInterval> {
        self.intervals.clone()
    }

    fn set_closed(&self, closed: &str) -> PyResult<Self> {
        let mut intervals = Vec::with_capacity(self.intervals.len());
        for iv in &self.intervals {
            intervals.push(PyInterval::new(iv.left, iv.right, Some(closed))?);
        }
        Ok(Self {
            intervals,
            name: self.name.clone(),
        })
    }

    fn overlaps(&self, other: &PyInterval) -> Vec<bool> {
        let other_closed = match other.closed.as_str() {
            "left" => fp_types::IntervalClosed::Left,
            "both" => fp_types::IntervalClosed::Both,
            "neither" => fp_types::IntervalClosed::Neither,
            _ => fp_types::IntervalClosed::Right,
        };
        let other_iv = fp_types::Interval::new(other.left, other.right, other_closed);
        self.to_rust().overlaps(&other_iv)
    }

    fn to_index(&self) -> PyIndex {
        PyIndex {
            inner: self.to_rust().to_index(),
        }
    }
}

impl PyIntervalIndex {
    pub fn to_rust(&self) -> fp_index::IntervalIndex {
        let values: Vec<fp_types::Interval> = self
            .intervals
            .iter()
            .map(|iv| {
                let closed = match iv.closed.as_str() {
                    "left" => fp_types::IntervalClosed::Left,
                    "both" => fp_types::IntervalClosed::Both,
                    "neither" => fp_types::IntervalClosed::Neither,
                    _ => fp_types::IntervalClosed::Right,
                };
                fp_types::Interval::new(iv.left, iv.right, closed)
            })
            .collect();
        let closed = values
            .first()
            .map_or(fp_types::IntervalClosed::Right, |iv| iv.closed);
        fp_index::IntervalIndex::new_with_options(values, closed, self.name.clone())
    }

    pub fn from_rust(rust_idx: &fp_index::IntervalIndex) -> Self {
        let intervals = rust_idx
            .values()
            .iter()
            .map(|iv| PyInterval {
                left: iv.left,
                right: iv.right,
                closed: iv.closed.to_string(),
            })
            .collect();
        Self {
            intervals,
            name: rust_idx.name().map(str::to_string),
        }
    }
}

/// pandas' `Categorical`: the values with their categories, held as a
/// categorical fp-frame Series. The values keep their types (they were all
/// stringified, so `Categorical([1, None])` had the categories '1' and
/// 'None'), missing values are missing, and inferred categories are the
/// sorted distinct values (br-frankenpandas-hrxn9).
#[pyclass(name = "Categorical", from_py_object)]
#[derive(Clone, Debug)]
pub struct PyCategorical {
    inner: Series,
}

impl PyCategorical {
    fn meta(&self) -> CategoricalMetadata {
        self.inner.cat().map_or_else(
            || CategoricalMetadata::new(Vec::new(), false),
            |cat| CategoricalMetadata::new(cat.categories().to_vec(), cat.ordered()),
        )
    }
}

#[pymethods]
impl PyCategorical {
    #[new]
    #[pyo3(signature = (values, categories=None, ordered=None))]
    fn new(
        py: Python<'_>,
        values: &Bound<'_, PyAny>,
        categories: Option<&Bound<'_, PyAny>>,
        ordered: Option<bool>,
    ) -> PyResult<Self> {
        let ordered = ordered.unwrap_or(false);
        let values = values
            .try_iter()?
            .map(|item| py_to_scalar(py, &item?))
            .collect::<PyResult<Vec<Scalar>>>()?;
        let inner = match categories.filter(|c| !c.is_none()) {
            None => Series::from_categorical("", values, ordered),
            Some(categories) => {
                let categories = categories
                    .try_iter()?
                    .map(|item| py_to_scalar(py, &item?))
                    .collect::<PyResult<Vec<Scalar>>>()?;
                // A value outside the given categories is missing, as pandas.
                let codes: Vec<i64> = values
                    .iter()
                    .map(|value| {
                        categories
                            .iter()
                            .position(|category| !value.is_missing() && category.semantic_eq(value))
                            .map_or(-1, |position| position as i64)
                    })
                    .collect();
                Series::from_categorical_codes("", codes, categories, ordered)
            }
        }
        .map_err(frame_error_to_py)?;
        Ok(Self { inner })
    }

    #[getter]
    fn categories(&self) -> PyIndex {
        let labels = self
            .meta()
            .categories
            .iter()
            .map(scalar_to_index_label_converter)
            .collect();
        PyIndex {
            inner: Index::new(labels),
        }
    }

    #[getter]
    fn codes(&self) -> PyResult<Vec<i64>> {
        let cat = self
            .inner
            .cat()
            .ok_or_else(|| PyErr::new::<pyo3::exceptions::PyTypeError, _>("not categorical"))?;
        let codes = cat.codes().map_err(frame_error_to_py)?;
        Ok(codes
            .values()
            .iter()
            .map(|code| match code {
                Scalar::Int64(code) => *code,
                _ => -1,
            })
            .collect())
    }

    #[getter]
    fn ordered(&self) -> bool {
        self.meta().ordered
    }

    #[getter]
    fn dtype(&self) -> PyCategoricalDtype {
        let meta = self.meta();
        PyCategoricalDtype {
            categories: Some(meta.categories.iter().map(ToString::to_string).collect()),
            ordered: meta.ordered,
        }
    }

    fn tolist(&self, py: Python<'_>) -> PyResult<Vec<Py<PyAny>>> {
        self.inner
            .values()
            .iter()
            .map(|value| scalar_to_py(py, value))
            .collect()
    }

    fn __repr__(&self) -> String {
        let meta = self.meta();
        format!(
            "Categorical(categories={:?}, ordered={}, length={})",
            meta.categories
                .iter()
                .map(ToString::to_string)
                .collect::<Vec<_>>(),
            meta.ordered,
            self.inner.len()
        )
    }

    fn __len__(&self) -> usize {
        self.inner.len()
    }
}

/// pandas' date offsets, `pd.DateOffset` and `pd.offsets.*`, in one class:
/// a relativedelta (`DateOffset(years=, months=, days=, ..., day=, ...)`
/// and the fixed ticks Day..Nano), or - with an `anchor` - a calendar
/// offset (MonthEnd, QuarterBegin, YearEnd, Week(weekday=), BusinessDay,
/// ...) that moves between anchor dates. `kind` names the pandas class it
/// stands for. MonthEnd / YearEnd and `months=` / `years=` used to add a
/// flat 30 / 365 days (fvsao.35).
#[pyclass(name = "DateOffset", from_py_object)]
#[derive(Clone, Debug, PartialEq)]
pub struct PyDateOffset {
    #[pyo3(get)]
    pub n: i64,
    #[pyo3(get)]
    pub normalize: bool,
    #[pyo3(get)]
    pub years: i64,
    #[pyo3(get)]
    pub months: i64,
    #[pyo3(get)]
    pub weeks: i64,
    #[pyo3(get)]
    pub days: i64,
    #[pyo3(get)]
    pub hours: i64,
    #[pyo3(get)]
    pub minutes: i64,
    #[pyo3(get)]
    pub seconds: i64,
    #[pyo3(get)]
    pub microseconds: i64,
    #[pyo3(get)]
    pub nanoseconds: i64,
    /// relativedelta's absolute fields, in [`DATE_OFFSET_ABSOLUTE`] order.
    absolute: [Option<i64>; 8],
    /// The anchored alias (ME, QS-MAR, W-MON, B, ...) of a calendar offset.
    anchor: Option<String>,
    /// The pandas class this offset stands for (None: DateOffset).
    kind: Option<&'static str>,
    /// Its repr attribute ("startingMonth=3").
    attr: Option<String>,
    /// pandas' rule code: the freqstr without the count (None for a
    /// DateOffset, whose freqstr is its repr).
    rule_code: Option<String>,
}

/// relativedelta's absolute (replacing) fields, as DateOffset takes them.
const DATE_OFFSET_ABSOLUTE: [&str; 8] = [
    "year",
    "month",
    "day",
    "hour",
    "minute",
    "second",
    "microsecond",
    "nanosecond",
];

impl Default for PyDateOffset {
    fn default() -> Self {
        Self {
            n: 1,
            normalize: false,
            years: 0,
            months: 0,
            weeks: 0,
            days: 0,
            hours: 0,
            minutes: 0,
            seconds: 0,
            microseconds: 0,
            nanoseconds: 0,
            absolute: [None; 8],
            anchor: None,
            kind: None,
            attr: None,
            rule_code: None,
        }
    }
}

impl PyDateOffset {
    /// A calendar offset over the anchored alias `anchor`.
    fn anchored(
        kind: &'static str,
        anchor: String,
        n: i64,
        normalize: bool,
        attr: Option<String>,
    ) -> Self {
        Self {
            n,
            normalize,
            rule_code: Some(anchor.clone()),
            anchor: Some(anchor),
            kind: Some(kind),
            attr,
            ..Default::default()
        }
    }

    /// A fixed tick of `nanos` per unit (Day, Hour, ...).
    fn tick(kind: &'static str, rule_code: &str, n: i64, nanos: i64) -> Self {
        Self {
            n,
            nanoseconds: nanos,
            kind: Some(kind),
            rule_code: Some(rule_code.to_owned()),
            ..Default::default()
        }
    }

    /// The fixed part of one unit, in nanoseconds.
    fn fixed_nanos(&self) -> Option<i64> {
        const SECOND: i64 = 1_000_000_000;
        [
            (self.weeks, 7 * 86_400 * SECOND),
            (self.days, 86_400 * SECOND),
            (self.hours, 3_600 * SECOND),
            (self.minutes, 60 * SECOND),
            (self.seconds, SECOND),
            (self.microseconds, 1_000),
            (self.nanoseconds, 1),
        ]
        .iter()
        .try_fold(0_i64, |total, &(count, unit)| {
            total.checked_add(count.checked_mul(unit)?)
        })
    }

    /// A DateOffset with nothing set, which pandas reads as one day.
    fn is_bare(&self) -> bool {
        self.anchor.is_none()
            && self.kind.is_none()
            && self.years == 0
            && self.months == 0
            && self.fixed_nanos() == Some(0)
            && self.absolute.iter().all(Option::is_none)
    }

    /// `nanos` with this offset applied `times` times (1 adds, -1
    /// subtracts); NaT stays NaT.
    fn apply(&self, py: Python<'_>, nanos: i64, times: i64) -> PyResult<i64> {
        const DAY: i64 = 86_400_000_000_000;
        let overflow = || PyErr::new::<pyo3::exceptions::PyOverflowError, _>("offset overflow");
        if nanos == Timestamp::NAT {
            return Ok(nanos);
        }
        let n = self.n.checked_mul(times).ok_or_else(overflow)?;
        let mut out = if let Some(anchor) = &self.anchor {
            fp_frame::shift_by_anchored_offset(nanos, anchor, n).map_err(frame_error_to_py)?
        } else {
            let mut value = nanos;
            if self.absolute.iter().any(Option::is_some) {
                let narrow = |value: Option<i64>| -> PyResult<Option<u8>> {
                    value
                        .map(|value| u8::try_from(value).map_err(|_| overflow()))
                        .transpose()
                };
                let [year, month, day, hour, minute, second, micro, nano] = self.absolute;
                value = PyTimestamp {
                    inner: Timestamp::from_nanos(value),
                }
                .replace(
                    py,
                    year.map(|year| i32::try_from(year).map_err(|_| overflow()))
                        .transpose()?,
                    narrow(month)?,
                    narrow(day)?,
                    narrow(hour)?,
                    narrow(minute)?,
                    narrow(second)?,
                    micro
                        .map(|micro| u32::try_from(micro).map_err(|_| overflow()))
                        .transpose()?,
                    nano,
                    None,
                )?
                .inner
                .nanos;
            }
            let months = self
                .years
                .checked_mul(12)
                .and_then(|months| months.checked_add(self.months))
                .and_then(|months| months.checked_mul(n))
                .ok_or_else(overflow)?;
            if months != 0 {
                value = fp_frame::add_calendar_months(value, months).map_err(frame_error_to_py)?;
            }
            let unit = if self.is_bare() {
                DAY
            } else {
                self.fixed_nanos().ok_or_else(overflow)?
            };
            unit.checked_mul(n)
                .and_then(|fixed| value.checked_add(fixed))
                .ok_or_else(overflow)?
        };
        if self.normalize {
            out -= out.rem_euclid(DAY);
        }
        Ok(out)
    }

    /// The instant a Timestamp or `datetime` operand stands for.
    fn instant(other: &Bound<'_, PyAny>) -> PyResult<Option<i64>> {
        if let Ok(ts) = other.extract::<PyRef<'_, PyTimestamp>>() {
            return Ok(Some(ts.inner.nanos));
        }
        if let Ok(dt) = other.cast::<PyDateTime>() {
            return py_datetime_nanos(dt).map(Some);
        }
        Ok(None)
    }

    /// `other` (a Timestamp or datetime, a datetime Series or a
    /// DatetimeIndex) with this offset applied `times` times; None for
    /// any other operand.
    fn apply_to_operand(
        &self,
        py: Python<'_>,
        other: &Bound<'_, PyAny>,
        times: i64,
    ) -> PyResult<Option<Py<PyAny>>> {
        if let Some(nanos) = Self::instant(other)? {
            let inner = Timestamp::from_nanos(self.apply(py, nanos, times)?);
            return Ok(Some(PyTimestamp { inner }.into_py_any(py)?));
        }
        if let Ok(series) = other.extract::<PyRef<'_, PySeries>>() {
            let inner = series_apply_offset(py, &series.inner, self, times)?;
            return Ok(Some(PySeries { inner }.into_py_any(py)?));
        }
        if let Ok(index) = other.extract::<PyRef<'_, PyDatetimeIndex>>() {
            return Ok(Some(
                index.offset_applied(py, self, times)?.into_py_any(py)?,
            ));
        }
        Ok(None)
    }
}

/// A frequency argument as its alias: a string as is, an offset object
/// through its freqstr ('2ME', 'W-MON'); `what` names the caller for the
/// DateOffset(months=...) that has none.
fn freq_alias(freq: &Bound<'_, PyAny>, what: &str) -> PyResult<String> {
    match freq.extract::<PyRef<'_, PyDateOffset>>() {
        Ok(offset) if offset.rule_code.is_some() => Ok(offset.freqstr()),
        Ok(_) => Err(not_implemented(&format!("{what}(DateOffset(...))"))),
        Err(_) => freq.extract::<String>(),
    }
}

/// pandas resamples only a datetime axis: any other raises its TypeError
/// (an integer index binned nothing and returned an empty result, a string
/// index was read as dates). A TimedeltaIndex is not supported yet.
/// The `origin` sub-day bins of a tz-aware index are anchored at, as an
/// instant the naive (UTC) binning takes: pandas' 'start_day' / 'end_day' /
/// 'epoch' are local midnights (the first day's, the day after the last's,
/// 1970-01-01 in the zone) and a timestamp text is a wall time in the zone;
/// 'start' / 'end' are instants already.
fn zoned_resample_origin(
    index: &Index,
    zone: &str,
    origin: Option<&str>,
) -> PyResult<Option<String>> {
    const DAY: i64 = 86_400_000_000_000;
    let instants = || {
        index.labels().iter().filter_map(|label| match label {
            IndexLabel::Datetime64(nanos) if *nanos != Timestamp::NAT => Some(*nanos),
            _ => None,
        })
    };
    let wall = |nanos: i64| fp_types::tz_utc_to_wall_nanos(zone, nanos);
    let local_midnight = match origin {
        Some("start" | "end") => return Ok(origin.map(str::to_owned)),
        None | Some("start_day") => match instants().min() {
            Some(first) => wall(first).map(|w| w.div_euclid(DAY) * DAY),
            None => return Ok(origin.map(str::to_owned)),
        },
        // pandas' last.ceil('D') on the local calendar.
        Some("end_day") => match instants().max() {
            Some(last) => wall(last).map(|w| {
                let midnight = w.div_euclid(DAY) * DAY;
                if midnight == w { w } else { midnight + DAY }
            }),
            None => return Ok(origin.map(str::to_owned)),
        },
        Some("epoch") => Ok(0),
        Some(text) => match Timestamp::parse(text) {
            Ok(ts) => Ok(ts.nanos),
            Err(_) => return Ok(origin.map(str::to_owned)),
        },
    }
    .map_err(tz_error_to_py_any)?;
    let instant =
        fp_types::tz_wall_to_utc_nanos(zone, local_midnight).map_err(tz_error_to_py_any)?;
    Ok(Some(fp_index::format_datetime_ns(instant)))
}

/// [`tz_error_to_py`] where no `Python` token is at hand.
fn tz_error_to_py_any(err: fp_types::TimeZoneError) -> PyErr {
    Python::attach(|py| tz_error_to_py(py, err))
}

fn require_resample_axis(index: &Index) -> PyResult<()> {
    let labels = index.labels();
    if labels
        .iter()
        .all(|label| matches!(label, IndexLabel::Datetime64(_) | IndexLabel::Null(_)))
    {
        return Ok(());
    }
    if labels
        .iter()
        .all(|label| matches!(label, IndexLabel::Timedelta64(_) | IndexLabel::Null(_)))
    {
        return Err(not_implemented("resample over a TimedeltaIndex"));
    }
    Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(
        "Only valid with DatetimeIndex, TimedeltaIndex or PeriodIndex, but got an instance of 'Index'",
    ))
}

/// `series` (datetime64) with `offset` applied `times` times to each value;
/// NaT stays NaT.
fn series_apply_offset(
    py: Python<'_>,
    series: &Series,
    offset: &PyDateOffset,
    times: i64,
) -> PyResult<Series> {
    if !matches!(series.column().dtype(), DType::Datetime64 { tz: None }) {
        return Err(PyErr::new::<pyo3::exceptions::PyTypeError, _>(format!(
            "cannot add {} to a Series of dtype {}",
            offset.__repr__(),
            column_pandas_dtype_name(series.column())
        )));
    }
    let values = series
        .values()
        .iter()
        .map(|value| match value {
            Scalar::Datetime64(nanos) if *nanos != Timestamp::NAT => {
                offset.apply(py, *nanos, times).map(Scalar::Datetime64)
            }
            _ => Ok(Scalar::Null(NullKind::NaT)),
        })
        .collect::<PyResult<Vec<Scalar>>>()?;
    let column = Column::new(DType::datetime64_naive(), values).map_err(column_error_to_py)?;
    Series::new(series.name(), series.index().clone(), column).map_err(frame_error_to_py)
}

#[pymethods]
impl PyDateOffset {
    /// pandas' `DateOffset(n=1, normalize=False, **kwds)`: relative
    /// `years`..`nanoseconds` and absolute `year`..`nanosecond`.
    #[new]
    #[allow(clippy::too_many_arguments)]
    #[pyo3(signature = (n=1, normalize=false, *, years=0, months=0, weeks=0, days=0, hours=0, minutes=0, seconds=0, microseconds=0, nanoseconds=0, year=None, month=None, day=None, hour=None, minute=None, second=None, microsecond=None, nanosecond=None))]
    fn new(
        n: i64,
        normalize: bool,
        years: i64,
        months: i64,
        weeks: i64,
        days: i64,
        hours: i64,
        minutes: i64,
        seconds: i64,
        microseconds: i64,
        nanoseconds: i64,
        year: Option<i64>,
        month: Option<i64>,
        day: Option<i64>,
        hour: Option<i64>,
        minute: Option<i64>,
        second: Option<i64>,
        microsecond: Option<i64>,
        nanosecond: Option<i64>,
    ) -> Self {
        Self {
            n,
            normalize,
            years,
            months,
            weeks,
            days,
            hours,
            minutes,
            seconds,
            microseconds,
            nanoseconds,
            absolute: [
                year,
                month,
                day,
                hour,
                minute,
                second,
                microsecond,
                nanosecond,
            ],
            ..Default::default()
        }
    }

    /// A tick's fixed length; pandas' ValueError for any other offset.
    #[getter]
    fn nanos(&self) -> PyResult<i64> {
        if self.anchor.is_none() && self.kind.is_some() {
            if let Some(nanos) = self.fixed_nanos().and_then(|unit| unit.checked_mul(self.n)) {
                return Ok(nanos);
            }
        }
        Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
            "{} is a non-fixed frequency",
            self.__repr__()
        )))
    }

    /// pandas' freqstr: the rule code with the count ("2ME", "W-MON",
    /// "QS-MAR"); a DateOffset's is its repr.
    #[getter]
    fn freqstr(&self) -> String {
        match &self.rule_code {
            Some(code) if self.n == 1 => code.clone(),
            Some(code) => format!("{}{code}", self.n),
            None => self.__repr__(),
        }
    }

    #[getter]
    fn rule_code(&self) -> PyResult<String> {
        self.rule_code
            .clone()
            .ok_or_else(|| not_implemented("DateOffset.rule_code"))
    }

    /// pandas' `name`: the rule code ('D', 'h', 'W-SUN'; it was missing).
    #[getter]
    fn name(&self) -> PyResult<String> {
        self.rule_code()
    }

    /// The Timestamp itself when it is on this offset, else the next one.
    fn rollforward(&self, dt: &Bound<'_, PyAny>) -> PyResult<PyTimestamp> {
        let nanos = Self::instant(dt)?.ok_or_else(|| {
            PyErr::new::<pyo3::exceptions::PyTypeError, _>("rollforward takes a Timestamp")
        })?;
        let inner = match &self.anchor {
            Some(anchor) => Timestamp::from_nanos(
                fp_frame::shift_by_anchored_offset(nanos, anchor, 0).map_err(frame_error_to_py)?,
            ),
            None => Timestamp::from_nanos(nanos),
        };
        Ok(PyTimestamp { inner })
    }

    /// The Timestamp itself when it is on this offset, else the previous one.
    fn rollback(&self, dt: &Bound<'_, PyAny>) -> PyResult<PyTimestamp> {
        let nanos = Self::instant(dt)?.ok_or_else(|| {
            PyErr::new::<pyo3::exceptions::PyTypeError, _>("rollback takes a Timestamp")
        })?;
        let inner = match &self.anchor {
            Some(anchor)
                if !fp_frame::is_on_anchored_offset(nanos, anchor)
                    .map_err(frame_error_to_py)? =>
            {
                Timestamp::from_nanos(
                    fp_frame::shift_by_anchored_offset(nanos, anchor, -1)
                        .map_err(frame_error_to_py)?,
                )
            }
            _ => Timestamp::from_nanos(nanos),
        };
        Ok(PyTimestamp { inner })
    }

    /// Whether the Timestamp's date is on this offset (a relative offset is
    /// on every date).
    fn is_on_offset(&self, dt: &Bound<'_, PyAny>) -> PyResult<bool> {
        let nanos = Self::instant(dt)?.ok_or_else(|| {
            PyErr::new::<pyo3::exceptions::PyTypeError, _>("is_on_offset takes a Timestamp")
        })?;
        match &self.anchor {
            Some(anchor) => {
                fp_frame::is_on_anchored_offset(nanos, anchor).map_err(frame_error_to_py)
            }
            None => Ok(true),
        }
    }

    /// pandas' `<2 * MonthEnds>`, `<-1 * QuarterEnd: startingMonth=3>`,
    /// `<DateOffset: days=2, years=1>` (the plural unless |n| is 1, a
    /// DateOffset's keywords sorted).
    fn __repr__(&self) -> String {
        let class = self.kind.unwrap_or("DateOffset");
        let plural = if self.n.abs() == 1 { "" } else { "s" };
        let count = if self.n == 1 {
            String::new()
        } else {
            format!("{} * ", self.n)
        };
        let attrs = match (&self.attr, self.kind) {
            (Some(attr), _) => attr.clone(),
            (None, Some(_)) => String::new(),
            (None, None) => {
                let relative = [
                    ("years", self.years),
                    ("months", self.months),
                    ("weeks", self.weeks),
                    ("days", self.days),
                    ("hours", self.hours),
                    ("minutes", self.minutes),
                    ("seconds", self.seconds),
                    ("microseconds", self.microseconds),
                    ("nanoseconds", self.nanoseconds),
                ];
                let mut parts: Vec<(&str, i64)> = relative
                    .into_iter()
                    .filter(|(_, value)| *value != 0)
                    .chain(
                        DATE_OFFSET_ABSOLUTE
                            .iter()
                            .zip(self.absolute)
                            .filter_map(|(name, value)| value.map(|value| (*name, value))),
                    )
                    .collect();
                parts.sort_unstable_by_key(|(name, _)| *name);
                parts
                    .iter()
                    .map(|(name, value)| format!("{name}={value}"))
                    .collect::<Vec<_>>()
                    .join(", ")
            }
        };
        let attrs = if attrs.is_empty() {
            attrs
        } else {
            format!(": {attrs}")
        };
        format!("<{count}{class}{plural}{attrs}>")
    }

    fn __hash__(&self) -> u64 {
        use std::hash::{Hash, Hasher};
        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        self.__repr__().hash(&mut hasher);
        hasher.finish()
    }

    fn __richcmp__(
        &self,
        py: Python<'_>,
        other: &Bound<'_, PyAny>,
        op: pyo3::class::basic::CompareOp,
    ) -> PyResult<Py<PyAny>> {
        use pyo3::class::basic::CompareOp;
        // A frequency string compares as the offset it names (pandas'
        // `to_offset`): `date_range(freq='D').freq == 'D'` is True.
        let same = if let Ok(text) = other.extract::<String>() {
            self.rule_code.is_some()
                && fp_index::canonical_freq(&text).as_deref() == Some(self.freqstr().as_str())
        } else if let Ok(other) = other.extract::<PyRef<'_, PyDateOffset>>() {
            *self == *other
        } else {
            return Ok(py.NotImplemented());
        };
        match op {
            CompareOp::Eq => Ok(pyo3::types::PyBool::new(py, same)
                .to_owned()
                .into_any()
                .unbind()),
            CompareOp::Ne => Ok(pyo3::types::PyBool::new(py, !same)
                .to_owned()
                .into_any()
                .unbind()),
            _ => Ok(py.NotImplemented()),
        }
    }

    /// `offset + Timestamp / datetime / datetime Series / DatetimeIndex`.
    fn __add__<'py>(&self, py: Python<'py>, other: &Bound<'py, PyAny>) -> PyResult<Py<PyAny>> {
        Ok(self
            .apply_to_operand(py, other, 1)?
            .unwrap_or_else(|| py.NotImplemented()))
    }

    fn __radd__<'py>(&self, py: Python<'py>, other: &Bound<'py, PyAny>) -> PyResult<Py<PyAny>> {
        self.__add__(py, other)
    }

    /// `Timestamp / Series / DatetimeIndex - offset`.
    fn __rsub__<'py>(&self, py: Python<'py>, other: &Bound<'py, PyAny>) -> PyResult<Py<PyAny>> {
        Ok(self
            .apply_to_operand(py, other, -1)?
            .unwrap_or_else(|| py.NotImplemented()))
    }

    fn __mul__(&self, factor: i64) -> PyResult<Self> {
        let n = self
            .n
            .checked_mul(factor)
            .ok_or_else(|| PyErr::new::<pyo3::exceptions::PyOverflowError, _>("offset overflow"))?;
        Ok(Self { n, ..self.clone() })
    }

    fn __rmul__(&self, factor: i64) -> PyResult<Self> {
        self.__mul__(factor)
    }

    fn __neg__(&self) -> PyResult<Self> {
        self.__mul__(-1)
    }
}

// pandas.tseries.offsets: the fixed ticks and the anchored calendar offsets.
#[pyfunction(name = "Day")]
#[pyo3(signature = (n=1))]
fn offset_day(n: i64) -> PyDateOffset {
    PyDateOffset::tick("Day", "D", n, 86_400_000_000_000)
}

#[pyfunction(name = "Hour")]
#[pyo3(signature = (n=1))]
fn offset_hour(n: i64) -> PyDateOffset {
    PyDateOffset::tick("Hour", "h", n, 3_600_000_000_000)
}

#[pyfunction(name = "Minute")]
#[pyo3(signature = (n=1))]
fn offset_minute(n: i64) -> PyDateOffset {
    PyDateOffset::tick("Minute", "min", n, 60_000_000_000)
}

#[pyfunction(name = "Second")]
#[pyo3(signature = (n=1))]
fn offset_second(n: i64) -> PyDateOffset {
    PyDateOffset::tick("Second", "s", n, 1_000_000_000)
}

#[pyfunction(name = "Milli")]
#[pyo3(signature = (n=1))]
fn offset_milli(n: i64) -> PyDateOffset {
    PyDateOffset::tick("Milli", "ms", n, 1_000_000)
}

#[pyfunction(name = "Micro")]
#[pyo3(signature = (n=1))]
fn offset_micro(n: i64) -> PyDateOffset {
    PyDateOffset::tick("Micro", "us", n, 1_000)
}

#[pyfunction(name = "Nano")]
#[pyo3(signature = (n=1))]
fn offset_nano(n: i64) -> PyDateOffset {
    PyDateOffset::tick("Nano", "ns", n, 1)
}

/// pandas' `Week(n, weekday=)`: seven days, or with a weekday (Monday 0)
/// the next such weekday strictly after the date.
#[pyfunction(name = "Week")]
#[pyo3(signature = (n=1, normalize=false, weekday=None))]
fn offset_week(n: i64, normalize: bool, weekday: Option<i64>) -> PyResult<PyDateOffset> {
    const DAYS: [&str; 7] = ["MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN"];
    let Some(weekday) = weekday else {
        return Ok(PyDateOffset {
            n,
            normalize,
            weeks: 1,
            kind: Some("Week"),
            attr: Some("weekday=None".to_owned()),
            rule_code: Some("W".to_owned()),
            ..Default::default()
        });
    };
    let day = usize::try_from(weekday)
        .ok()
        .and_then(|weekday| DAYS.get(weekday))
        .ok_or_else(|| {
            PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
                "Day must be 0<=day<=6, got {weekday}"
            ))
        })?;
    Ok(PyDateOffset::anchored(
        "Week",
        format!("W-{day}"),
        n,
        normalize,
        Some(format!("weekday={weekday}")),
    ))
}

/// The anchor suffix of a month number (1 -> "JAN").
fn offset_month_abbr(month: i64) -> PyResult<&'static str> {
    const MONTHS: [&str; 12] = [
        "JAN", "FEB", "MAR", "APR", "MAY", "JUN", "JUL", "AUG", "SEP", "OCT", "NOV", "DEC",
    ];
    usize::try_from(month - 1)
        .ok()
        .and_then(|month| MONTHS.get(month).copied())
        .ok_or_else(|| {
            PyErr::new::<pyo3::exceptions::PyValueError, _>("Month must go from 1 to 12")
        })
}

#[pyfunction(name = "MonthEnd")]
#[pyo3(signature = (n=1, normalize=false))]
fn offset_month_end(n: i64, normalize: bool) -> PyDateOffset {
    PyDateOffset::anchored("MonthEnd", "ME".to_owned(), n, normalize, None)
}

#[pyfunction(name = "MonthBegin")]
#[pyo3(signature = (n=1, normalize=false))]
fn offset_month_begin(n: i64, normalize: bool) -> PyDateOffset {
    PyDateOffset::anchored("MonthBegin", "MS".to_owned(), n, normalize, None)
}

#[pyfunction(name = "BMonthEnd")]
#[pyo3(signature = (n=1, normalize=false))]
fn offset_business_month_end(n: i64, normalize: bool) -> PyDateOffset {
    PyDateOffset::anchored("BusinessMonthEnd", "BME".to_owned(), n, normalize, None)
}

#[pyfunction(name = "BMonthBegin")]
#[pyo3(signature = (n=1, normalize=false))]
fn offset_business_month_begin(n: i64, normalize: bool) -> PyDateOffset {
    PyDateOffset::anchored("BusinessMonthBegin", "BMS".to_owned(), n, normalize, None)
}

/// A semi-monthly offset: SME's anchors are `day_of_month` and the month
/// end, SMS's the 1st and `day_of_month` (2..=27, pandas' bounds).
fn offset_semi_month(
    kind: &'static str,
    code: &str,
    n: i64,
    normalize: bool,
    day_of_month: i64,
) -> PyResult<PyDateOffset> {
    if !(2..=27).contains(&day_of_month) {
        return Err(PyErr::new::<pyo3::exceptions::PyValueError, _>(format!(
            "day_of_month must be 2<=day_of_month<=27, got {day_of_month}"
        )));
    }
    let mut offset = PyDateOffset::anchored(
        kind,
        format!("{code}-{day_of_month}"),
        n,
        normalize,
        Some(format!("day_of_month={day_of_month}")),
    );
    if day_of_month == 15 {
        offset.rule_code = Some(code.to_owned());
    }
    Ok(offset)
}

#[pyfunction(name = "SemiMonthEnd")]
#[pyo3(signature = (n=1, normalize=false, day_of_month=15))]
fn offset_semi_month_end(n: i64, normalize: bool, day_of_month: i64) -> PyResult<PyDateOffset> {
    offset_semi_month("SemiMonthEnd", "SME", n, normalize, day_of_month)
}

#[pyfunction(name = "SemiMonthBegin")]
#[pyo3(signature = (n=1, normalize=false, day_of_month=15))]
fn offset_semi_month_begin(n: i64, normalize: bool, day_of_month: i64) -> PyResult<PyDateOffset> {
    offset_semi_month("SemiMonthBegin", "SMS", n, normalize, day_of_month)
}

/// A quarter or year offset anchored on `month` (a quarter's anchor months
/// are every third from it).
fn offset_period_anchor(
    kind: &'static str,
    code: &str,
    n: i64,
    normalize: bool,
    attr: &str,
    month: i64,
) -> PyResult<PyDateOffset> {
    Ok(PyDateOffset::anchored(
        kind,
        format!("{code}-{}", offset_month_abbr(month)?),
        n,
        normalize,
        Some(format!("{attr}={month}")),
    ))
}

#[pyfunction(name = "QuarterEnd")]
#[pyo3(signature = (n=1, normalize=false, startingMonth=3))]
#[allow(non_snake_case)] // pandas' keyword
fn offset_quarter_end(n: i64, normalize: bool, startingMonth: i64) -> PyResult<PyDateOffset> {
    offset_period_anchor(
        "QuarterEnd",
        "QE",
        n,
        normalize,
        "startingMonth",
        startingMonth,
    )
}

#[pyfunction(name = "QuarterBegin")]
