    #[test]
    fn test_py_series_extended_ops() {
        let labels = vec![
            IndexLabel::Int64(0),
            IndexLabel::Int64(1),
            IndexLabel::Int64(2),
            IndexLabel::Int64(3),
        ];
        let values = vec![
            Scalar::Float64(10.0),
            Scalar::Float64(50.0),
            Scalar::Float64(20.0),
            Scalar::Float64(10.0),
        ];
        let s = Series::from_values("s", labels, values).expect("series"); // ubs:ignore — test fixture
        let mut py_s = PySeries { inner: s };

        assert_eq!(py_s.dtype_name(), "float64");
        assert_eq!(py_s.shape(), (4,));
        assert_eq!(py_s.size(), 4);
        assert_eq!(py_s.ndim(), 1);
        assert!(!py_s.empty());

        let isin_res = py_s.inner.isin(&[Scalar::Float64(10.0)]).expect("isin"); // ubs:ignore — test fixture
        assert_eq!(
            isin_res.values(),
            &[
                Scalar::Bool(true),
                Scalar::Bool(false),
                Scalar::Bool(false),
                Scalar::Bool(true)
            ]
        );

        let betw = py_s
            .inner
            .between(&Scalar::Float64(15.0), &Scalar::Float64(55.0), "both")
            .expect("between"); // ubs:ignore — test fixture
        assert_eq!(
            betw.values(),
            &[
                Scalar::Bool(false),
                Scalar::Bool(true),
                Scalar::Bool(true),
                Scalar::Bool(false)
            ]
        );

        assert_eq!(py_s.argmax().expect("argmax"), 1); // ubs:ignore — test fixture
        assert_eq!(py_s.argmin().expect("argmin"), 0); // ubs:ignore — test fixture
        assert_eq!(py_s.inner.idxmax().expect("idxmax"), IndexLabel::Int64(1)); // ubs:ignore — test fixture
        assert_eq!(py_s.inner.idxmin().expect("idxmin"), IndexLabel::Int64(0)); // ubs:ignore — test fixture

        let shifted = py_s.shift(1, None, None, None, None).expect("shift"); // ubs:ignore — test fixture
        assert_eq!(shifted.inner.len(), 4);

        let nlg = py_s.nlargest(2, "first").expect("nlargest"); // ubs:ignore — test fixture
        assert_eq!(nlg.inner.len(), 2);
        let nsm = py_s.nsmallest(2, "first").expect("nsmallest"); // ubs:ignore — test fixture
        assert_eq!(nsm.inner.len(), 2);

        let dedup = py_s
            .drop_duplicates(None, false, false)
            .expect("drop_duplicates")
            .expect("a copy"); // ubs:ignore — test fixture
        assert_eq!(dedup.inner.len(), 3);
        let dups = py_s.duplicated(None).expect("duplicated"); // ubs:ignore — test fixture
        assert_eq!(dups.inner.len(), 4);

        let reset = py_s.inner.reset_index(false).expect("reset_index"); // ubs:ignore — test fixture
        assert!(matches!(
            reset,
            fp_frame::SeriesResetIndexResult::DataFrame(ref df) if df.shape() == (4, 2)
        ));
    }

    #[test]
    fn test_py_dataframe_extended_ops() {
        let df = DataFrame::from_dict(
            &["a", "b"],
            vec![
                (
                    "a",
                    vec![
                        Scalar::Float64(1.0),
                        Scalar::Float64(2.0),
                        Scalar::Float64(3.0),
                    ],
                ),
                (
                    "b",
                    vec![
                        Scalar::Float64(10.0),
                        Scalar::Float64(20.0),
                        Scalar::Float64(30.0),
                    ],
                ),
            ],
        )
        .expect("dataframe"); // ubs:ignore — test fixture
        let mut py_df = PyDataFrame { inner: df };

        assert!(!py_df.empty());
        assert_eq!(py_df.ndim(), 2);
        assert_eq!(py_df.size(), 6);

        let df_copy = py_df.copy();
        assert_eq!(df_copy.shape(), (3, 2));

        let isna_df = py_df.isna().expect("isna"); // ubs:ignore — test fixture
        assert_eq!(isna_df.shape(), (3, 2));
        let notna_df = py_df.notna().expect("notna"); // ubs:ignore — test fixture
        assert_eq!(notna_df.shape(), (3, 2));
        let isnull_df = py_df.isnull().expect("isnull"); // ubs:ignore — test fixture
        assert_eq!(isnull_df.shape(), (3, 2));
        let notnull_df = py_df.notnull().expect("notnull"); // ubs:ignore — test fixture
        assert_eq!(notnull_df.shape(), (3, 2));

        let idxmax_s = py_df.idxmax(None, true, false).expect("idxmax"); // ubs:ignore — test fixture
        assert_eq!(idxmax_s.inner.len(), 2);
        let idxmin_s = py_df.idxmin(None, true, false).expect("idxmin"); // ubs:ignore — test fixture
        assert_eq!(idxmin_s.inner.len(), 2);

        let diff_df = py_df.diff(1, None).expect("diff"); // ubs:ignore — test fixture
        assert_eq!(diff_df.shape(), (3, 2));

        let pct_df = py_df
            .pct_change(1, None, None, None, None)
            .expect("pct_change"); // ubs:ignore — test fixture
        assert_eq!(pct_df.shape(), (3, 2));

        let cs = py_df.cumsum(None, true, None).expect("cumsum"); // ubs:ignore — test fixture
        assert_eq!(cs.shape(), (3, 2));
        let cp = py_df.cumprod(None, true, None).expect("cumprod"); // ubs:ignore — test fixture
        assert_eq!(cp.shape(), (3, 2));
        let cmin = py_df.cummin(None, true, None).expect("cummin"); // ubs:ignore — test fixture
        assert_eq!(cmin.shape(), (3, 2));
        let cmax = py_df.cummax(None, true, None).expect("cummax"); // ubs:ignore — test fixture
        assert_eq!(cmax.shape(), (3, 2));

        let sh = py_df.shift(1, None, None, None, None).expect("shift"); // ubs:ignore — test fixture
        assert_eq!(sh.shape(), (3, 2));

        let queried =
            Python::attach(|py| py_df.query(py, "a > 1", false, None, None, 0, None, None))
                .expect("query") // ubs:ignore — test fixture
                .expect("not inplace, so a frame"); // ubs:ignore — test fixture
        assert_eq!(queried.shape(), (2, 2));

        let dups = py_df.duplicated(None, None).expect("duplicated"); // ubs:ignore — test fixture
        assert_eq!(dups.inner.len(), 3);
        let dedup = py_df
            .drop_duplicates(None, None, false, false)
            .expect("drop_duplicates")
            .expect("a copy"); // ubs:ignore — test fixture
        assert_eq!(dedup.shape(), (3, 2));

        let p_df = py_df.add_prefix("col_", None).expect("add_prefix"); // ubs:ignore — test fixture
        assert_eq!(p_df.column_labels(), vec!["col_a", "col_b"]);
        let s_df = py_df.add_suffix("_end", None).expect("add_suffix"); // ubs:ignore — test fixture
        assert_eq!(s_df.column_labels(), vec!["a_end", "b_end"]);

        assert!(py_df.equals(&df_copy));

        let mut mod_df = py_df.clone();
        let popped = mod_df.pop("a").expect("pop"); // ubs:ignore — test fixture
        assert_eq!(popped.name(), Some("a"));
        assert_eq!(mod_df.column_labels(), vec!["b"]);
        assert!(mod_df.pop("nonexistent").is_err());

        pyo3::Python::initialize();
        pyo3::Python::attach(|py| {
            let dict_obj = py_df.to_dict(py, "dict").expect("to_dict dict"); // ubs:ignore — test fixture
            assert!(dict_obj.bind(py).is_instance_of::<pyo3::types::PyDict>());

            let list_obj = py_df.to_dict(py, "list").expect("to_dict list"); // ubs:ignore — test fixture
            assert!(list_obj.bind(py).is_instance_of::<pyo3::types::PyDict>());

            let records_obj = py_df.to_dict(py, "records").expect("to_dict records"); // ubs:ignore — test fixture
            assert!(records_obj.bind(py).is_instance_of::<pyo3::types::PyList>());

            let index_obj = py_df.to_dict(py, "index").expect("to_dict index"); // ubs:ignore — test fixture
            assert!(index_obj.bind(py).is_instance_of::<pyo3::types::PyDict>());

            let split_obj = py_df.to_dict(py, "split").expect("to_dict split"); // ubs:ignore — test fixture
            assert!(split_obj.bind(py).is_instance_of::<pyo3::types::PyDict>());

            assert!(py_df.to_dict(py, "invalid_orient").is_err());
        });
    }

